window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0058", [{"word":"naturalistic","ipa_uk":"/ˌnætʃəˈlɪstɪk/","ipa_us":"/ˌnætʃərəˈlɪstɪk/","definition_zh":"自然主义的；写实的；自然情境下的；博物学的；自然题材的","definition_en":"relating to naturalism, or representing nature and life as they actually are rather than as one might wish them to be","core_image":"画室里没有人摆姿势，画家把画架搬到田边，画布上留着杂草、泥痕和斜斜的日光。","scene":"美术馆导览员站在一幅乡村画前说，这位画家拒绝把田野画成理想化的风景，只如实记录泥泞、杂草和斜照的光。The painter kept the field naturalistic, showing mud and weeds instead of an ideal view.","sceneCN":"这里 naturalistic 是“以自然主义方式如实再现现实”（第 1 个义项）；句意：画家把这片田野画得写实，画的是泥泞与杂草，而不是理想化的景色。","pos":[{"tag":"adj.","zh":"自然主义的；写实的；自然情境下的；博物学的；自然题材的"}],"collocations":[{"phrase":"a naturalistic painting","zh":"一幅自然主义绘画"},{"phrase":"naturalistic observation","zh":"自然情境观察"},{"phrase":"naturalistic writing","zh":"自然主义写作"},{"phrase":"naturalistic design","zh":"自然题材的装饰设计"},{"phrase":"naturalistic philosophy","zh":"自然主义哲学"},{"phrase":"a naturalistic setting","zh":"自然真实的环境"}],"forms":[{"label":"原级（形容词）","form":"naturalistic"},{"label":"比较级（用 more）","form":"more naturalistic"},{"label":"最高级（用 most）","form":"most naturalistic"},{"label":"副词形式","form":"naturalistically"}],"derivatives":[{"word":"nature","pos":"n.","zh":"自然；天性；本质"},{"word":"natural","pos":"adj.","zh":"自然的；天生的；正常的"},{"word":"naturalism","pos":"n.","zh":"自然主义；自然论"},{"word":"naturalist","pos":"n.","zh":"博物学家；自然主义者"}],"senses":[{"no":"01","title":"The style that copies life","titleCN":"自然主义：把生活原样搬上画布","definition":"relating to naturalism in art or literature, which shows life and nature as they are without idealizing them","definitionCN":"属于文学艺术中的自然主义，如实呈现生活与自然而不作美化","example":"The novel is naturalistic in its refusal to give its poor characters a happy ending.","exampleCN":"这部小说是自然主义的，它拒绝给贫穷的人物一个圆满结局。","why":"Naturalism claims that environment and heredity decide human fate; a naturalistic work therefore records causes and conditions instead of arranging a pleasing outcome.","whyCN":"自然主义主张环境与遗传决定人的命运；因此自然主义作品记录原因与条件，而不安排一个讨喜的结局。"},{"no":"02","title":"Lifelike, close to the real","titleCN":"写实逼真：看起来就像真的","definition":"resembling real life closely in appearance, sound, or behaviour","definitionCN":"在外观、声音或行为上非常接近真实生活","example":"The film's naturalistic dialogue made the actors sound like people we know.","exampleCN":"这部影片的写实对白让演员听起来像我们认识的人。","why":"Here naturalistic judges resemblance, not theory: the test is whether a viewer feels the thing before them could exist outside the frame.","whyCN":"这里的 naturalistic 判断的是相似度而非理论：标准是观众是否觉得眼前之物在画框之外也可能存在。"},{"no":"03","title":"Studied in the wild","titleCN":"自然情境下：不在实验室里观察","definition":"describing research carried out in ordinary surroundings rather than in a controlled laboratory","definitionCN":"指在日常生活环境中而非受控实验室里进行的研究","example":"Naturalistic observation recorded how children actually share toys in the playground.","exampleCN":"自然情境观察记录了儿童在操场上实际如何分享玩具。","why":"The setting itself becomes part of the method: to see behaviour as it naturally occurs, the researcher must give up control over the conditions.","whyCN":"环境本身成了方法的一部分：要看行为自然发生的样子，研究者必须放弃对条件的控制。"},{"no":"04","title":"Belonging to natural history","titleCN":"博物学的：记录花草虫鸟的学问","definition":"relating to the description and study of plants, animals, and minerals in their habitats","definitionCN":"与在栖息地中描述和研究动植物、矿物有关","example":"The museum's naturalistic drawings date from an age before photography.","exampleCN":"博物馆里的博物学绘图来自摄影术出现之前的年代。","why":"Natural history was once the study of everything under nature; its drawings are called naturalistic because accuracy to the specimen, not beauty, is the aim.","whyCN":"博物学曾经研究自然中的一切；其绘图被称作 naturalistic，因为目标是忠实于标本，而不是美观。"},{"no":"05","title":"Nature is all there is","titleCN":"自然主义哲学：只承认自然存在","definition":"holding the philosophical view that nature is the whole of reality and needs no supernatural explanation","definitionCN":"持这样一种哲学观点：自然就是全部现实，无需超自然解释","example":"A naturalistic account of mind tries to explain thought without appealing to anything beyond nature.","exampleCN":"对心灵的自然主义解释试图不借助自然之外的东西来说明思想。","why":"This sense moves the word from style to worldview: whatever exists must be accounted for within nature, so the natural is the boundary of what can be discussed.","whyCN":"这一义项把词从风格移到世界观：凡存在的都须在自然之内解释，因此“自然”成了可讨论之物的边界。"},{"no":"06","title":"Plain, without polish","titleCN":"平实不加修饰：不替现实打光","definition":"presented in a plain, matter-of-fact way that leaves out decoration or idealization","definitionCN":"以平实、就事论事的方式呈现，去掉装饰与理想化","example":"He gave a naturalistic account of the accident, including the parts that made him look careless.","exampleCN":"他平实地叙述了那场事故，连让他显得粗心的部分也没有省略。","why":"When decoration is removed, what remains is claimed to be nature itself; plainness becomes evidence of honesty rather than a lack of skill.","whyCN":"去掉装饰后，剩下的被主张为自然本身；朴素由此成了诚实的证据，而不是技巧的欠缺。"},{"no":"07","title":"Motifs borrowed from nature","titleCN":"自然题材：把枝叶花鸟搬进图案","definition":"using plants, animals, or landscapes as decorative motifs","definitionCN":"以植物、动物或风景作为装饰母题","example":"The wallpaper has a naturalistic pattern of ivy and small birds.","exampleCN":"墙纸上是常春藤和小鸟的自然题材图案。","why":"Decorative arts borrow the shapes of living things but flatten them into repeatable patterns; naturalistic marks the source of the motif, not the realism of the wall.","whyCN":"装饰艺术借用生物的形态，却把它们压平成可重复的图案；naturalistic 标的是母题的来源，而不是墙面的写实程度。"},{"no":"08","title":"Unforced and unstudied","titleCN":"自然不做作：举止里没有排练","definition":"behaving in an easy, unforced way that does not seem planned or performed","definitionCN":"举止轻松自然，看不出刻意安排或表演的痕迹","example":"Her naturalistic manner put the interviewees at ease.","exampleCN":"她自然不做作的举止让受访者放松下来。","why":"A performance becomes naturalistic when the audience stops noticing the performance; the word then praises the absence of visible effort.","whyCN":"当观众不再注意到“表演”时，表演就变得 naturalistic；此时这个词赞美的是看不见的用力痕迹。"}],"etymology":{"intro":{"en":"Naturalistic joins natural with the Greek-derived suffix -istic. The base is Latin natura, from nasci, to be born.","cn":"naturalistic 由 natural 与源自希腊语的后缀 -istic 组合而成。词基是拉丁语 natura，出自 nasci“出生”。"},"items":[{"era":"LATIN nasci / natura","en":"Nasci meant to be born. Its noun natura named the course of things at birth, hence the character of the world and of a person.","cn":"nasci 意为“出生”。其名词 natura 指出生时带来的禀性，进而指世界的本性以及人的天性。"},{"era":"LATIN naturalis","en":"Naturalis meant belonging to nature or produced by it, as opposed to what is made by art or by human arrangement.","cn":"naturalis 意为“属于自然的、由自然产生的”，与人工或人为安排相对。"},{"era":"FRENCH naturel","en":"Old French naturel carried both the outward sense of the physical world and the inward sense of inborn character.","cn":"古法语 naturel 同时承载“外在物质世界”与“内在固有性格”两层意思。"},{"era":"ENGLISH natural","en":"English natural covers what is not artificial, what is inborn, and what is simply normal or expected.","cn":"英语 natural 涵盖“非人工的”“天生的”以及“正常、理所当然的”三层意思。"},{"era":"ENGLISH -istic","en":"The suffix came through French -istique from Greek -istikos. It forms adjectives naming a style, a doctrine, or a practice.","cn":"该后缀经法语 -istique 来自希腊语 -istikos，用来构成表示风格、学说或做法的形容词。"},{"era":"ENGLISH 1849","en":"Naturalistic is recorded in the mid-19th century, first for art that follows nature closely, then for the philosophical view that nature is all of reality.","cn":"naturalistic 的书面记录见于 19 世纪中期，最初指紧贴自然的艺术，随后指“自然即全部现实”的哲学观点。"}]},"similar":{"note":{"en":"The first group is the word family built on nature; the second compares styles and methods that claim to follow reality.","cn":"第一组是基于 nature 的词族；第二组比较几种自称“追随现实”的风格与方法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"natural","ipa":"/ˈnætʃrəl/","tag":"adjective","definition":"existing in nature, not made by people; also inborn or normal. It states a fact about origin.","definitionCN":"自然界存在、非人造的；也指天生的或正常的。它陈述的是来源事实。"},{"word":"naturalism","ipa":"/ˈnætʃrəlɪzəm/","tag":"noun","definition":"the artistic movement or philosophical view that nature is the whole of reality. It names the doctrine.","definitionCN":"主张自然即全部现实的艺术运动或哲学观点；它命名的是学说。"},{"word":"naturalist","ipa":"/ˈnætʃrəlɪst/","tag":"person noun","definition":"a person who studies plants and animals in the field, or an artist who works in the naturalistic style.","definitionCN":"在野外研究动植物的人，或采用自然主义风格的艺术家。"},{"word":"naturalistic","ipa":"/ˌnætʃəˈlɪstɪk/","tag":"adjective","definition":"having the character of naturalism. Unlike natural, it describes a manner of representation.","definitionCN":"具有自然主义特征的。与 natural 不同，它描述的是再现方式。"}]},{"heading":"NEAR MEANING","entries":[{"word":"realistic","ipa":"/riːˈlɪstɪk/","tag":"style adjective","definition":"showing things as they are and accepting practical limits. It often also means sensible about what is possible.","definitionCN":"如实呈现事物并接受现实限制；也常指对可能性抱务实态度。"},{"word":"lifelike","ipa":"/ˈlaɪflaɪk/","tag":"resemblance adjective","definition":"looking or sounding exactly like a living thing. It judges surface resemblance only.","definitionCN":"外观或声音酷似活物；只判断表面的相似度。"},{"word":"veristic","ipa":"/veˈrɪstɪk/","tag":"art-historical adjective","definition":"extremely detailed and exact in art, especially Italian portraiture. It stresses precision of detail rather than social theory.","definitionCN":"艺术上极为精细写实，尤指意大利肖像；强调细节精确而非社会理论。"},{"word":"observational","ipa":"/ˌɒbzəˈveɪʃənl/","tag":"research adjective","definition":"based on watching and recording rather than experiment. It names the method, not the style.","definitionCN":"基于观察记录而非实验；命名的是方法，而不是风格。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: nature plus -istic. The suffix says 'in the manner of', so naturalistic means 'in the manner of nature'.","cn":"只用真实成分：nature 加 -istic。后缀表示“以……的方式”，所以 naturalistic 就是“以自然的方式”。"},"normal":[{"en":"Nature + -istic: in the manner of nature, with no makeup added.","cn":"nature 加 -istic：以自然的方式，不额外化妆。"},{"en":"A naturalistic play ends where life would end, not where the audience would like it to.","cn":"自然主义的戏剧在生活本该结束的地方结束，而不是在观众希望的地方结束。"},{"en":"In psychology, naturalistic means the playground instead of the lab.","cn":"在心理学里，naturalistic 意味着操场而不是实验室。"},{"en":"On wallpaper, naturalistic ivy is still a pattern, not a plant.","cn":"墙纸上的自然题材常春藤仍是图案，不是植物。"},{"en":"A naturalistic manner is one where you cannot see the rehearsing.","cn":"自然不做作的举止，就是你看不出排练痕迹的那种举止。"}],"abstract":[{"en":"To call something naturalistic is to claim that no hand has improved it, and that claim is itself an artistic decision.","cn":"说某物是自然主义的，就是宣称没有手笔修饰过它；而这个宣称本身就是一次艺术决定。"},{"en":"Nature never presents itself unedited; every naturalistic work chooses which parts of nature to keep.","cn":"自然从不以未经剪辑的样子出现；每件自然主义作品都在选择保留自然的哪些部分。"},{"en":"The word holds a quiet argument: if nature is all there is, then explaining anything means staying inside it.","cn":"这个词里藏着一场安静的争论：若自然就是全部，那么解释任何事物都必须留在自然之内。"}]},"examples":[{"en":"The director shot the factory in naturalistic light, so the machines looked heavy and the faces tired.","cn":"导演用自然主义的光拍摄工厂，机器显得沉重，人脸显得疲惫。"},{"en":"A naturalistic study in the classroom found that children help each other more than tests suggest.","cn":"一项在教室里进行的自然情境研究发现了比测验结果更多的儿童互助行为。"},{"en":"The naturalistic explanation of religion treats belief as a product of human minds and societies.","cn":"对宗教的自然主义解释把信仰看作人类心智与社会的产物。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"natural（自然的）+ istic（风格）——照着自然画，不加滤镜，就是自然主义的。","word":"naturalistic"},"root":"由 natural（自然的，源自拉丁语 natura“出生、本性”）加希腊语来源的后缀 -istic（以……方式、属于……派）构成，本义为“以自然为本、按自然的样子呈现”。","sensesIntro":{"en":"Eight senses of naturalistic, all circling one idea: nature supplies the standard. The standard may be a subject to be copied, a setting to be preserved, a doctrine to be defended, or a manner to be kept unforced.","cn":"naturalistic 的八个义项都围绕一个观念：以自然为标准。这个标准可以是被临摹的对象、被保留的环境、被辩护的学说，或被保持为不做作的举止。"},"semanticMap":{"core":{"en":"CORE IMAGE: an easel in a field, paint recording mud, weeds, and slanting light without cleaning them up.","cn":"核心意象：田边的画架，画布记录泥泞、杂草与斜光，一样也不修饰。"},"chain":["LATIN NASCI = TO BE BORN","LATIN NATURA = BIRTH, NATURE","LATIN NATURALIS = OF NATURE","ENGLISH NATURAL = NOT ARTIFICIAL","SUFFIX -ISTIC = IN THE MANNER OF","NATURALISTIC = REPRESENTING IN THE MANNER OF NATURE"],"branches":[{"senses":"S1 · S6","en":"ART WITHOUT POLISH: the movement that refuses idealization and the plain account that refuses decoration.","cn":"不加修饰的艺术：拒绝理想化的流派，与拒绝装饰的平实叙述。"},{"senses":"S2 · S8","en":"RESEMBLANCE IN MANNER: lifelike dialogue and unforced behaviour both make the artificial invisible.","cn":"方式上的相似：写实对白与不做作的举止，都让人为痕迹消失。"},{"senses":"S3 · S4","en":"NATURE AS METHOD: fieldwork in ordinary settings and natural-history drawing both let the object set the terms.","cn":"以自然为方法：日常环境中的田野研究与博物学绘图，都让对象决定规则。"},{"senses":"S5","en":"NATURE AS REALITY: the philosophical claim that nothing exists beyond the natural order.","cn":"以自然为现实：哲学上主张自然秩序之外别无存在。"},{"senses":"S7","en":"NATURE AS SOURCE OF FORM: decorative motifs borrowed from plants and animals.","cn":"以自然为形式来源：从动植物借来的装饰母题。"}]},"affixes":{"intro":{"en":"Naturalistic is natural plus -istic, a suffix that turns a noun or adjective into a style label. The family then adds -ism for the doctrine and -ist for the person.","cn":"naturalistic 是 natural 加 -istic；该后缀把名词或形容词变成风格标签。词族再用 -ism 表示学说、用 -ist 表示人。"},"latinIntro":{"en":"The Latin base is nasci, to be born, with the noun natura and the adjective naturalis. Greek -istikos supplies the style suffix through French.","cn":"拉丁词基是 nasci“出生”，名词 natura，形容词 naturalis。风格后缀则经法语来自希腊语 -istikos。"},"items":[{"word":"nature","structure":"Latin natura (birth, character) < nasci (be born)","meaning":"the physical world, or the inborn character of a thing","meaningCN":"自然界；或事物的固有本性","example":"The nature of the soil decides which plants survive.","exampleCN":"土壤的性质决定哪些植物能存活。"},{"word":"natural","structure":"Latin naturalis (of nature) + English -al","meaning":"produced by nature, not by people; inborn; normal","meaningCN":"自然产生的、非人造的；天生的；正常的","example":"The cave is a natural shelter, not a built one.","exampleCN":"这个洞穴是天然庇护所，不是人造的。"},{"word":"naturalism","structure":"natural + -ism (doctrine or movement)","meaning":"the view that nature is all of reality, or the art movement that follows it","meaningCN":"自然即全部现实的学说，或追随该主张的艺术运动","example":"Naturalism in the novel replaced heroic plots with ordinary lives.","exampleCN":"小说中的自然主义用普通人的生活取代英雄情节。"},{"word":"naturalist","structure":"natural + -ist (person)","meaning":"a field researcher of plants and animals, or a follower of naturalism","meaningCN":"野外研究动植物的学者，或自然主义的追随者","example":"The naturalist spent a year recording birds in the marsh.","exampleCN":"这位博物学家用一年时间记录沼泽里的鸟类。"},{"word":"naturalistic","structure":"natural + -istic (in the manner of)","meaning":"resembling nature or following the naturalist style","meaningCN":"类似自然的；遵循自然主义风格的","example":"The exhibit pairs naturalistic drawings with living specimens.","exampleCN":"展览把博物学绘图与活体标本配对陈列。"},{"word":"naturalistically","structure":"naturalistic + -ally (adverb)","meaning":"in a manner that copies nature closely","meaningCN":"以贴近自然的方式；写实地","example":"The animals were painted naturalistically, down to the mud on their legs.","exampleCN":"这些动物被画得很写实，连腿上的泥都画了出来。"},{"word":"supernatural","structure":"super- (above) + natural","meaning":"beyond the natural order","meaningCN":"超自然的；自然秩序之外的","example":"Naturalism denies any supernatural cause.","exampleCN":"自然主义否认任何超自然原因。"},{"word":"unnatural","structure":"un- (not) + natural","meaning":"contrary to nature or to normal feeling","meaningCN":"违背自然的；反常的","example":"The silence in the forest felt unnatural.","exampleCN":"森林里的寂静让人觉得反常。"},{"word":"naturalize","structure":"natural + -ize (make, become)","meaning":"to make something natural, or to adopt a plant, word, or person as native","meaningCN":"使自然化；使（植物、词语、人）归化","example":"The shrub naturalized itself along the river within a decade.","exampleCN":"这种灌木十年内就在河边归化了。"}],"latinEntries":[{"word":"nasci","structure":"Latin deponent verb","meaning":"to be born, to arise, to grow","meaningCN":"出生；产生；生长"},{"word":"natura","structure":"Latin noun","meaning":"birth, constitution, the natural world","meaningCN":"出生；禀性；自然界"},{"word":"naturalis","structure":"Latin adjective","meaning":"of nature, natural, inborn","meaningCN":"自然的；天生的"}]}},{"word":"naturally","ipa_uk":"/ˈnætʃrəli/","ipa_us":"/ˈnætʃərəli/","definition_zh":"自然地；天生地；理所当然地；未经人工干预地；不做作地","definition_en":"in a natural way, by nature, or as one would reasonably expect","core_image":"一粒种子落在土里，没有支架，也没有指令，它自己朝光长出一片叶子。","scene":"朋友听说你刚搬到海边，笑着说，这大概会自然而然发生。Living by the sea, you will naturally start swimming every day.","sceneCN":"这里 naturally 是“理所当然地、自然而然”（第 3 个义项）；句意：住在海边，你自然会开始每天游泳。","pos":[{"tag":"adv.","zh":"自然地；天生地；理所当然地；未经人工干预地；不做作地"}],"collocations":[{"phrase":"come naturally","zh":"生来就会；做起来很自然"},{"phrase":"naturally occurring","zh":"天然存在的"},{"phrase":"quite naturally","zh":"很自然地；理所当然"},{"phrase":"naturally enough","zh":"自然不过地"},{"phrase":"speak naturally","zh":"自然地说话"},{"phrase":"naturally gifted","zh":"天生有禀赋的"}],"forms":[{"label":"原级（副词）","form":"naturally"},{"label":"比较级（用 more）","form":"more naturally"},{"label":"最高级（用 most）","form":"most naturally"},{"label":"形容词形式","form":"natural"}],"derivatives":[{"word":"nature","pos":"n.","zh":"自然；天性；本质"},{"word":"natural","pos":"adj.","zh":"自然的；天生的；正常的"},{"word":"naturalness","pos":"n.","zh":"自然；不做作"},{"word":"naturalize","pos":"v.","zh":"使归化；使自然化"}],"senses":[{"no":"01","title":"In nature's own way","titleCN":"以自然的方式：不按人为规矩来","definition":"in a way that follows nature rather than human design or convention","definitionCN":"依照自然而非人为设计或惯例的方式进行","example":"The river runs naturally through the valley, without any concrete banks.","exampleCN":"这条河自然地流过山谷，两岸没有水泥护岸。","why":"The adverb describes the manner of an action: it happens as nature would have it, so the absence of human arrangement is the point.","whyCN":"这个副词描述动作的方式：事情按自然本来的样子发生，所以“没有人为安排”正是重点。"},{"no":"02","title":"From birth, by temperament","titleCN":"天生地：生来就带着的本事或性情","definition":"as a result of inborn ability or character rather than training","definitionCN":"出于与生俱来的能力或性格，而非后天训练","example":"She naturally remembers faces, even ones she has seen only once.","exampleCN":"她天生记得住面孔，哪怕只见过一次。","why":"Here the adverb points to the origin of an ability: the talent is treated as part of the person's constitution, not as an acquired skill.","whyCN":"这里副词指向能力的来源：这份才能被视为个人禀赋的一部分，而不是后天习得的技能。"},{"no":"03","title":"As you would expect","titleCN":"理所当然：事情本就该这样","definition":"as is reasonable or unsurprising, given the circumstances","definitionCN":"在那种情形下合乎情理、并不令人意外","example":"Naturally, the children were excited the night before the trip.","exampleCN":"出发前一晚孩子们很兴奋，这是理所当然的。","why":"This sense is about inference, not nature: the speaker says the outcome follows so obviously that no explanation is needed.","whyCN":"这一义项关乎推理而非自然：说话者表示结果显然如此，根本无须解释。"},{"no":"04","title":"Without human help","titleCN":"未经人工干预：自己长出来的","definition":"happening or existing without cultivation, manufacture, or intervention","definitionCN":"在没有栽培、制造或人为干预的情况下发生或存在","example":"The valley is naturally protected from strong winds by its surrounding hills.","exampleCN":"这个山谷因四周的丘陵而天然不受强风侵袭。","why":"The word marks a cause that is not human: whatever produced the result was already there, so no one deserves credit or blame for it.","whyCN":"这个词标出非人为的原因：产生结果的东西本来就存在，因此无人该为此受功或受责。"},{"no":"05","title":"Without pretending","titleCN":"不做作：不摆姿态、不加表演","definition":"in a relaxed and sincere manner that shows no affectation","definitionCN":"以放松而真诚的方式，不显出做作","example":"On camera she laughed naturally, not the way she laughed in advertisements.","exampleCN":"镜头前她笑得很自然，不是广告里那种笑法。","why":"Praise of natural behaviour measures the distance between a person and a performance; the smaller the distance, the more naturally it is done.","whyCN":"称赞举止自然，衡量的是“人”与“表演”之间的距离；距离越小，就做得越自然。"},{"no":"06","title":"By logical consequence","titleCN":"顺理成章：顺着前提必然走到这里","definition":"as a necessary or logical consequence of what came before","definitionCN":"作为先前事情必然或合乎逻辑的结果","example":"Naturally, a longer delay meant a higher final cost.","exampleCN":"工期拖得更久，最终成本自然更高。","why":"The sense borrows the idea of nature as an inevitable order and applies it to reasoning: given the premise, the conclusion could hardly be otherwise.","whyCN":"这一义项借用了“自然是一种必然秩序”的观念，并把它用于推理：前提既定，结论几乎不可能不是这样。"},{"no":"07","title":"Found in the wild","titleCN":"天然存在：自然界里本来就有","definition":"occurring in nature rather than being made or introduced by people","definitionCN":"存在于自然界，而非由人制造或引入","example":"The element is naturally present in seawater at a very low concentration.","exampleCN":"这种元素天然存在于海水中，浓度极低。","why":"In science the word distinguishes a substance that was already in the environment from one released or synthesised by humans.","whyCN":"在科学语境里，这个词区分“本来就在环境中的物质”与“人类释放或合成的物质”。"},{"no":"08","title":"Easily and smoothly","titleCN":"从容自如：做起来不费劲","definition":"with ease and fluency, as if no effort were required","definitionCN":"轻松流畅地，仿佛不需要用力","example":"After a month of practice, the steps came naturally to him.","exampleCN":"练了一个月后，这些步骤他做起来已从容自如。","why":"Skill that has become second nature no longer shows the seams of conscious control; the adverb reports that ease rather than describing the world.","whyCN":"熟练到成为第二天性时，动作不再露出刻意控制的痕迹；这个副词报告的是这种轻松，而不是在描述世界。"}],"etymology":{"intro":{"en":"Naturally is natural plus the adverb suffix -ly. Natural goes back through French to Latin natura and the verb nasci, to be born.","cn":"naturally 是 natural 加副词后缀 -ly。natural 经法语上溯至拉丁语 natura 与动词 nasci“出生”。"},"items":[{"era":"LATIN nasci","en":"Nasci meant to be born or to arise. From it came natura, the condition and character one has at birth.","cn":"nasci 意为“出生、产生”。由它派生出 natura，指出生时的状况与禀性。"},{"era":"LATIN naturalis","en":"Naturalis described what belongs to nature or comes from it, as opposed to what art or human skill produces.","cn":"naturalis 描述属于自然或来自自然的东西，与技艺或人力所产相对。"},{"era":"FRENCH naturel","en":"Old French naturel kept both senses: the physical world and a person's inborn disposition.","cn":"古法语 naturel 保留两层含义：物质世界，以及人的固有性情。"},{"era":"ENGLISH natural + -ly","en":"English formed adverbs with -ly from Old English -lice. Naturally therefore means 'in a natural manner' before it means 'of course'.","cn":"英语用 -ly（古英语 -lice）构成副词。因此 naturally 先表示“以自然的方式”，之后才引申出“当然”。"},{"era":"ENGLISH 17c-18c","en":"The 'as expected' sense grew out of the idea that nature follows a fixed order: what is natural is also what regularly happens.","cn":"“如所预料”义由“自然遵循固定秩序”的观念生长出来：合乎自然的，也就是经常发生的。"},{"era":"MODERN ENGLISH","en":"Science writing added naturally occurring; speech and performance writing added the sense of ease without affectation.","cn":"科学写作发展出 naturally occurring（天然存在）；言语与表演领域则发展出“从容不做作”的义项。"}]},"similar":{"note":{"en":"The first group shares the nature root; the second compares adverbs that describe how an action comes about.","cn":"第一组共享 nature 词根；第二组比较几个描述“动作如何发生”的副词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"natural","ipa":"/ˈnætʃrəl/","tag":"adjective","definition":"existing in nature, inborn, or normal. It modifies a noun.","definitionCN":"自然界存在的、天生的或正常的；修饰名词。"},{"word":"nature","ipa":"/ˈneɪtʃə/","tag":"noun","definition":"the physical world, or the essential character of something.","definitionCN":"物质世界，或某物的本质特性。"},{"word":"naturalness","ipa":"/ˈnætʃrəlnəs/","tag":"quality noun","definition":"the quality of being natural or free from affectation.","definitionCN":"自然、不做作的性质。"},{"word":"naturally","ipa":"/ˈnætʃrəli/","tag":"adverb","definition":"in a natural manner; also as one would expect. It modifies a verb or a whole clause.","definitionCN":"以自然的方式；也指如所预料。它修饰动词或整个小句。"}]},{"heading":"NEAR MEANING","entries":[{"word":"of course","ipa":"/əv ˈkɔːs/","tag":"phrase","definition":"as everyone knows or expects. It marks the obviousness of a fact, not its origin.","definitionCN":"众所周知或如人所料；标出事实的显然，而不涉其来源。"},{"word":"inevitably","ipa":"/ɪnˈevɪtəbli/","tag":"adverb","definition":"in a way that cannot be avoided. It is stronger than naturally and implies necessity.","definitionCN":"以无法避免的方式；比 naturally 更强，含必然性。"},{"word":"instinctively","ipa":"/ɪnˈstɪŋktɪvli/","tag":"adverb","definition":"by automatic animal impulse rather than thought. It applies to living creatures.","definitionCN":"凭本能的自动冲动而非思考；适用于生物。"},{"word":"spontaneously","ipa":"/spɒnˈteɪniəsli/","tag":"adverb","definition":"from one's own impulse, without planning; also happening without external cause.","definitionCN":"出于自身冲动、未经计划；也指无外在原因地发生。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: natural + -ly. The suffix simply turns the adjective into an adverb, so the meaning tracks natural.","cn":"只用真实成分：natural 加 -ly。后缀只是把形容词变成副词，词义随 natural 走。"},"normal":[{"en":"Natural + -ly: do it the way nature would, with no scaffolding.","cn":"natural 加 -ly：照自然的方式做，不加支架。"},{"en":"A talent you never trained comes naturally; a habit you drilled also comes naturally after enough practice.","cn":"没练过的才能，说起来就是“生来就会”；练够了的习惯，用起来也同样轻松自如。"},{"en":"In a chemistry paper, naturally means it was already in the water.","cn":"在化学论文里，naturally 表示它本来就在水里。"},{"en":"Naturally at the start of a sentence usually means 'as you can guess'.","cn":"naturally 放在句首，通常就是“你猜也猜得到”。"},{"en":"A good actor makes a rehearsed line sound naturally spoken.","cn":"好演员能把排练过的台词说得像自然说出的一样。"}],"abstract":[{"en":"Nature and reason share one adverb: what always happens and what must follow are felt to be the same order.","cn":"自然与理性共用一个副词：总会发生的事与必然推出的事，被感受为同一种秩序。"},{"en":"Saying 'naturally' hides who arranged the conditions; it presents a result as if no one had chosen it.","cn":"说 naturally 会隐藏是谁安排了条件：它把结果呈现得好像无人选择过。"},{"en":"Effortless skill is nature edited by years of practice, and the adverb keeps the editing out of sight.","cn":"举重若轻的技艺，是被多年练习剪辑过的自然；而这个副词把剪辑痕迹藏在镜头外。"}]},"examples":[{"en":"The lake is naturally too cold for swimming until late June.","cn":"这个湖天然太冷，要到六月下旬才适合游泳。"},{"en":"Naturally, the students who read the whole book did better on the essay question.","cn":"读过整本书的学生在论述题上表现更好，这是理所当然的。"},{"en":"She stepped onto the stage and began to speak naturally, as if the audience were old friends.","cn":"她走上台，自然地开口，仿佛观众都是老朋友。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"natural（自然的）+ ly（地）——自然地；事情按常理发展，也就成了“当然”。","word":"naturally"},"root":"由 natural（自然的，源自拉丁语 natura“出生、本性”，出自 nasci“出生”）加副词后缀 -ly 构成，本义为“以自然的方式”，后引申为“天生地、理所当然地”。","sensesIntro":{"en":"Eight senses of naturally. One thread runs through them: something happens without visible human arrangement. That can mean without cultivation, without training, without affectation, or simply without any need to explain.","cn":"naturally 的八个义项由一条线串起：事情发生，却看不出人为安排。这可以指未经栽培、未经训练、不加做作，或干脆无须解释。"},"semanticMap":{"core":{"en":"CORE IMAGE: a seed in bare soil, growing toward the light with no stake and no instruction.","cn":"核心意象：裸土里的一粒种子，没有支架也没有指令，自己朝光生长。"},"chain":["LATIN NASCI = TO BE BORN","LATIN NATURA = BIRTH, NATURE","LATIN NATURALIS = OF NATURE","ENGLISH NATURAL = NOT ARTIFICIAL","SUFFIX -LY = IN A ... MANNER","NATURALLY = IN NATURE'S MANNER"],"branches":[{"senses":"S1 · S7","en":"WITHOUT HUMAN DESIGN: a free river and an element already in seawater both exist before anyone acts.","cn":"无人为设计：自由流淌的河与海水中本就存在的元素，都在人行动之前就已存在。"},{"senses":"S2 · S8","en":"WITHOUT TRAINING: inborn memory and practised ease both look as if no learning took place.","cn":"未经训练：天生的记忆力与练成的从容，看起来都像没有学习过。"},{"senses":"S3 · S6","en":"WITHOUT EXPLANATION: 'as you would expect' and 'by consequence' both present the result as obvious.","cn":"无须解释：“如你所料”与“顺理成章”都把结果呈现为显然。"},{"senses":"S4","en":"WITHOUT CULTIVATION: shelter and protection supplied by terrain rather than by builders.","cn":"未经栽培：由地形而非建造者提供的遮蔽与保护。"},{"senses":"S5","en":"WITHOUT PERFORMANCE: behaviour that does not advertise itself as behaviour.","cn":"不加表演：举止不把自己标榜为“举止”。"}]},"affixes":{"intro":{"en":"Naturally is natural plus -ly, the standard English adverb suffix. The family spreads through -ness, -ism, -ist, -ize, and the prefix un-.","cn":"naturally 是 natural 加 -ly，即英语标准副词后缀。词族再通过 -ness、-ism、-ist、-ize 与否定前缀 un- 扩展。"},"latinIntro":{"en":"The Latin base is nasci, to be born, giving natura and naturalis. English -ly descends from Old English -lice, not from Latin.","cn":"拉丁词基是 nasci“出生”，由此得到 natura 与 naturalis。英语 -ly 则源自古英语 -lice，并非来自拉丁语。"},"items":[{"word":"nature","structure":"Latin natura (birth, character) < nasci (be born)","meaning":"the physical world, or the inborn character of something","meaningCN":"自然界；或事物的固有本性","example":"The nature of the clay decides how the pot will fire.","exampleCN":"陶土的性质决定这只陶罐烧成后的样子。"},{"word":"natural","structure":"Latin naturalis (of nature)","meaning":"existing in nature, inborn, or normal","meaningCN":"自然存在的；天生的；正常的","example":"The harbour is a natural shelter for small boats.","exampleCN":"这个港湾是小船天然的避风处。"},{"word":"naturally","structure":"natural + -ly (adverb)","meaning":"in a natural manner; as expected","meaningCN":"以自然的方式；如所预料","example":"The trail climbs naturally along the ridge.","exampleCN":"这条小径顺着山脊自然向上延伸。"},{"word":"naturalness","structure":"natural + -ness (quality noun)","meaning":"the quality of being natural or unaffected","meaningCN":"自然、不做作的性质","example":"The naturalness of her voice made the recording easy to trust.","exampleCN":"她声音里的自然感让这段录音容易让人信服。"},{"word":"naturalism","structure":"natural + -ism (doctrine)","meaning":"the view that nature is all of reality","meaningCN":"自然即全部现实的学说","example":"Naturalism rejects explanations that step outside nature.","exampleCN":"自然主义拒绝越出自然之外的解释。"},{"word":"naturalist","structure":"natural + -ist (person)","meaning":"a field researcher of living things","meaningCN":"野外研究生物的人；博物学家","example":"The naturalist noted the first migrants of spring.","exampleCN":"这位博物学家记下了春天第一批迁徙的鸟。"},{"word":"naturalize","structure":"natural + -ize (make, become)","meaning":"to make natural, or to establish a species or word as native","meaningCN":"使自然化；使物种或词语归化","example":"The plant naturalized quickly in the wet soil.","exampleCN":"这种植物在湿土中很快归化了。"},{"word":"unnatural","structure":"un- (not) + natural","meaning":"contrary to nature or to normal feeling","meaningCN":"违背自然的；反常的","example":"The brightness of the sky at midnight seemed unnatural.","exampleCN":"午夜天空的亮度显得反常。"},{"word":"supernatural","structure":"super- (above) + natural","meaning":"existing beyond the natural order","meaningCN":"存在于自然秩序之外的；超自然的","example":"The story adds a supernatural explanation to a real famine.","exampleCN":"这个故事给一场真实的饥荒加上了超自然解释。"}],"latinEntries":[{"word":"nasci","structure":"Latin deponent verb","meaning":"to be born, to arise","meaningCN":"出生；产生"},{"word":"natura","structure":"Latin noun","meaning":"birth, constitution, the natural world","meaningCN":"出生；禀性；自然界"},{"word":"naturalis","structure":"Latin adjective","meaning":"of nature, inborn, natural","meaningCN":"自然的；天生的"}]}},{"word":"necessity","ipa_uk":"/nəˈsesəti/","ipa_us":"/nəˈsesəti/","definition_zh":"必要性；必需品；贫困；必然性；迫不得已","definition_en":"the state of being necessary; something that cannot be done without; also poverty or unavoidable need","core_image":"一只空水壶立在桌上，旁边是一张写满“必须”的清单，第一行写着水，后面才是别的。","scene":"救援队在出发前清点物资，队长说，干净的水要排在最前面。Clean water is the first necessity for the team.","sceneCN":"这里 necessity 是“不可或缺的东西、必需品”（第 2 个义项）；句意：干净的水是队伍最首要的必需品。","pos":[{"tag":"n.","zh":"必要性；必需品；贫困；必然性；（不得已的）需要"}],"collocations":[{"phrase":"a basic necessity","zh":"基本必需品"},{"phrase":"out of necessity","zh":"出于无奈；迫不得已"},{"phrase":"of necessity","zh":"必然地；不可避免地"},{"phrase":"daily necessities","zh":"日常必需品"},{"phrase":"the necessity of doing something","zh":"做某事的必要性"},{"phrase":"bare necessities","zh":"最低限度的生活必需品"}],"forms":[{"label":"复数（名词）","form":"necessities"},{"label":"形容词形式","form":"necessary"},{"label":"动词形式","form":"necessitate"},{"label":"副词形式","form":"necessarily"}],"derivatives":[{"word":"necessary","pos":"adj.","zh":"必要的；必然的"},{"word":"necessarily","pos":"adv.","zh":"必然地；必定"},{"word":"necessitate","pos":"v.","zh":"使成为必要；需要"},{"word":"unnecessary","pos":"adj.","zh":"不必要的；多余的"}],"senses":[{"no":"01","title":"The state of being needed","titleCN":"必要性：不做就不行","definition":"the condition of being required or indispensable for a purpose","definitionCN":"为达成某目的而被需要、不可缺的状态","example":"The report argues the necessity of a second runway at the airport.","exampleCN":"报告论证了机场修建第二条跑道的必要性。","why":"This is the abstract quality, not the object: it answers the question 'why must this be done?' rather than 'what do we need?'","whyCN":"这是抽象的性质，而不是具体的东西：它回答“为什么非做不可”，而不是“我们需要什么”。"},{"no":"02","title":"Something you cannot do without","titleCN":"必需品：清单上排第一的东西","definition":"an item that is essential for living or for a particular activity","definitionCN":"维持生活或完成某项活动所必需的东西","example":"The clinic lacks the basic necessities: clean water, gloves, and bandages.","exampleCN":"诊所缺少基本必需品：干净的水、手套和绷带。","why":"The abstract quality turns concrete: if something is necessary, then the thing itself can be called a necessity and counted in a list.","whyCN":"抽象性质具体化了：如果某物是必要的，那么该物本身就可以被称为 necessity，并能列进清单里点算。"},{"no":"03","title":"Hardship and poverty","titleCN":"贫困窘迫：被“必需”逼到角落","definition":"the condition of extreme need or poverty, especially when money is short","definitionCN":"极度匮乏或贫困的处境，尤指缺钱的状况","example":"Many families were driven by necessity to sell their tools.","exampleCN":"许多家庭因贫困所迫卖掉了工具。","why":"When needs cannot be met, necessity stops meaning 'requirement' and starts naming the pressure itself, which is close to want and hardship.","whyCN":"当需求无法满足时，necessity 就不再表示“要求”，而开始指那种压力本身，接近匮乏与困苦。"},{"no":"04","title":"Logical inevitability","titleCN":"逻辑必然：前提逼出结论","definition":"the quality of following unavoidably from given premises or laws","definitionCN":"由既定前提或规律不可回避地推出的性质","example":"The necessity of the conclusion follows from the two premises.","exampleCN":"该结论的必然性由那两个前提推出。","why":"In logic the word marks that a step cannot fail: if the premises hold, the conclusion has no alternative.","whyCN":"在逻辑中，这个词标出某一步不可能失手：前提成立，结论就别无选择。"},{"no":"05","title":"What cannot be otherwise","titleCN":"不可避免：事情只能这样发生","definition":"the character of an event that could not have happened differently","definitionCN":"某事无法以别的方式发生的性质","example":"The historian describes the collapse as a necessity rather than an accident.","exampleCN":"这位历史学家把那次崩溃描述为必然，而非意外。","why":"Here necessity is applied to events, not to logic: the claim is that conditions left no room for another outcome.","whyCN":"这里 necessity 用于事件而非逻辑：主张是条件没有给别的结果留余地。"},{"no":"06","title":"The means of living","titleCN":"生计所需：过日子离不开的","definition":"the conditions or resources required to maintain life","definitionCN":"维持生活所必需的条件或资源","example":"The workers asked for enough wages to cover the necessities of life.","exampleCN":"工人们要求足够的工资来支付生活必需品。","why":"The plural ties the word to the household: air, water, food, and shelter are necessities because life cannot continue without them.","whyCN":"复数形式把这个词拴在家计上：空气、水、食物和住所之所以是 necessities，是因为缺了它们生活无法继续。"},{"no":"07","title":"Only because one must","titleCN":"迫不得已：不是想，而是不得不","definition":"the pressure of circumstances that forces an action one would not otherwise choose","definitionCN":"迫使人们做出本不会选择的行为的处境压力","example":"Out of necessity, she took the night shift and gave up her classes.","exampleCN":"迫不得已，她接了夜班，放弃了课程。","why":"In the phrase out of necessity, the word names the cause of an unwanted choice: the action is explained, not praised.","whyCN":"在“出于无奈”这一说法里，这个词说明一个并不想要的选择的原因：它是在解释行为，而不是在赞美行为。"},{"no":"08","title":"A category in philosophy","titleCN":"哲学范畴：必然与偶然相对","definition":"the philosophical category of what must be, as opposed to what happens by chance","definitionCN":"哲学上“必定如此”的范畴，与偶然相对","example":"The dialogue contrasts necessity with chance in the order of the universe.","exampleCN":"这段对话在宇宙秩序中把必然与偶然对照起来。","why":"Philosophy turns the everyday pressure into a category: some things are said to be necessary in themselves, not merely needed by someone.","whyCN":"哲学把日常的压力提升为一个范畴：有些事物被说成自身必然，而不只是被某人需要。"}],"etymology":{"intro":{"en":"Necessity comes from Latin necessitas, from necesse, 'unavoidable'. The internal structure of necesse is disputed, so the word's deeper root is best marked as uncertain.","cn":"necessity 来自拉丁语 necessitas，出自 necesse“不可避免”。necesse 的内部结构存在争议，因此更深的词根应标为来源不确定。"},"items":[{"era":"LATIN necesse","en":"Necesse meant unavoidable or indispensable. It was already used both for logical compulsion and for the pressure of circumstances.","cn":"necesse 意为“不可避免的、不可或缺的”，当时既用于逻辑强制，也用于处境的压力。"},{"era":"LATIN necessitas","en":"The noun added the senses of compulsion, need, poverty, and bonds of duty. It could name both an inner must and an outer shortage.","cn":"名词形式增加了强制、需要、贫困与义务约束等义，既能指内在的“必须”，也能指外在的匮乏。"},{"era":"UNCERTAIN ROOT","en":"The commonly repeated split ne- 'not' plus cedere 'yield' would mean 'not yielding'. This is a plausible reconstruction, not a confirmed derivation, so it is marked uncertain.","cn":"常见的拆解是 ne-“不”加 cedere“让步”，意为“不让步”。这是一种合理的重构，并非已确认的派生，故标为来源不确定。"},{"era":"FRENCH necessité","en":"Old French necessité carried the senses of need, compulsion, and want. English borrowed the word in the 14th century through French.","cn":"古法语 necessité 带有需要、强制与匮乏等义。英语于 14 世纪经法语借入该词。"},{"era":"ENGLISH 14c","en":"English necessity first covered compulsion and need, then widened to include indispensable objects and the philosophical category of inevitability.","cn":"英语 necessity 最初涵盖强制与需要，随后扩展到不可或缺的物品，以及哲学上的必然性范畴。"},{"era":"MODERN ENGLISH","en":"The plural necessities settled into household and economic language, giving phrases such as daily necessities and bare necessities.","cn":"复数 necessities 固定于家庭与经济语境，形成 daily necessities、bare necessities 等说法。"}]},"similar":{"note":{"en":"The first group is the necessary word family; the second compares words for needs and for inevitability.","cn":"第一组是 necessary 的词族；第二组比较表示“需要”与“必然”的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"necessary","ipa":"/ˈnesəsəri/","tag":"adjective","definition":"required, or certain to happen. It describes a thing or a conclusion.","definitionCN":"必需的，或必定发生的；描述事物或结论。"},{"word":"necessitate","ipa":"/nəˈsesɪteɪt/","tag":"verb","definition":"to make something necessary. It names the cause, not the need.","definitionCN":"使某事成为必要；命名的是原因，不是需要本身。"},{"word":"necessarily","ipa":"/ˌnesəˈserəli/","tag":"adverb","definition":"in every case, or as a logical consequence. It often appears in negatives.","definitionCN":"在所有情况下，或作为逻辑结果；常出现在否定句中。"},{"word":"necessity","ipa":"/nəˈsesəti/","tag":"noun","definition":"the state of being needed, or the thing needed. It names the need itself.","definitionCN":"被需要的状态，或被需要之物；命名的是需要本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"essential","ipa":"/ɪˈsenʃl/","tag":"adjective","definition":"absolutely important or basic. It grades importance but does not claim that something cannot be omitted.","definitionCN":"绝对重要或基本的；它给重要性分级，但不宣称不可省略。"},{"word":"requirement","ipa":"/rɪˈkwaɪəmənt/","tag":"noun","definition":"something officially demanded or needed for a purpose. It comes from a rule or authority.","definitionCN":"为某目的被正式要求或需要之物；来源于规定或权威。"},{"word":"inevitability","ipa":"/ɪnˌevɪtəˈbɪləti/","tag":"noun","definition":"the quality of being impossible to avoid. It stresses the future, while necessity can be logical.","definitionCN":"无法避免的性质；侧重未来，而 necessity 可以是逻辑上的。"},{"word":"poverty","ipa":"/ˈpɒvəti/","tag":"noun","definition":"the state of lacking money or goods. It is one concrete sense of necessity, not the whole word.","definitionCN":"缺钱或缺物的状态；它只是 necessity 的一个具体义项。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: Latin necesse, unavoidable, plus the noun suffix -itas, which became English -ity. The word names the 'must' itself.","cn":"只用真实成分：拉丁语 necesse“不可避免”，加名词后缀 -itas（英语作 -ity）。这个词命名的是“必须”本身。"},"normal":[{"en":"A necessity is whatever stands first on the list when everything else is crossed out.","cn":"necessity 就是把其他都划掉后仍留在清单第一行的东西。"},{"en":"Out of necessity means the choice was made by circumstances, not by preference.","cn":"out of necessity 意味着选择是处境做的，不是偏好做的。"},{"en":"Water, food, shelter: plural necessities are the household version of the abstract word.","cn":"水、食物、住所：复数的 necessities 就是这个词的家计版本。"},{"en":"In a proof, necessity is the step that cannot be skipped.","cn":"在证明里，necessity 就是那步不能跳过的地方。"},{"en":"Necessity and necessary share one spine; only the ending changes the job.","cn":"necessity 与 necessary 共享同一根脊梁，只是词尾改变了词性。"}],"abstract":[{"en":"Necessity is a mirror held up to desire: it shows how much of what we call 'must' is only 'would like'.","cn":"necessity 是一面照向欲望的镜子：它照出我们称为“必须”的东西里，有多少其实只是“想要”。"},{"en":"Every claim of necessity removes an option, and whoever defines necessity controls the choices of others.","cn":"每一次“必然”的宣称都在删掉一个选项；谁定义必然，谁就掌握了他人的选择。"},{"en":"The word ties a physical shortage to a logical conclusion, as if what is missing could prove what must be.","cn":"这个词把物质匮乏与逻辑结论绑在一起，仿佛缺什么就能证明什么必然如此。"}]},"examples":[{"en":"The engineers questioned the necessity of the extra tower, given the new safety system.","cn":"鉴于新的安全系统，工程师们质疑了额外那座塔的必要性。"},{"en":"In the drought year, water became a necessity that the town rationed by the bucket.","cn":"干旱那年，水成了小镇按桶配给的必需品。"},{"en":"Of necessity, the team shipped the simple version first and saved the refinements for later.","cn":"不得已之下，团队先交付了简单版本，把改进留到以后。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"ne（不）+ cess（退）+ ity——一步也不退，就是“必要、必然”；不退的东西就是必需品。","word":"necessity"},"root":"源自拉丁语 necessitas（必然、需要、困乏），出自 necesse（不可避免的）；其更早的词根拆解存在争议，通常的说法是 ne-“不”加 cedere“让步”，但未获确证，应视为重构。","sensesIntro":{"en":"Eight senses of necessity, from abstract requirement to concrete goods, hardship, and logical compulsion. The shared core is a door that will not open: something that cannot be refused, omitted, or otherwise arranged.","cn":"necessity 的八个义项，从抽象要求到具体物品、贫困与逻辑强制。共同的核心是一扇打不开的门：某个东西无法被拒绝、省略或另行安排。"},"semanticMap":{"core":{"en":"CORE IMAGE: an empty water jug beside a list whose first line reads water, with everything else below it.","cn":"核心意象：空水壶旁一张清单，第一行写着水，其余都排在下面。"},"chain":["LATIN NEED = UNAVOIDABLE","LATIN NECESSITAS = COMPULSION, NEED","FRENCH NECESSITE = NEED, WANT","ENGLISH NECESSITY = THE STATE OF BEING NEEDED","THE NEEDED THING ENTERS THE LIST","WHAT CANNOT BE OTHERWISE, IN LIFE OR IN LOGIC"],"branches":[{"senses":"S1 · S4","en":"COMPULSION: a required condition and a forced conclusion both leave no alternative.","cn":"强制：必需的条件与被迫的结论，都不留别的可能。"},{"senses":"S2 · S6","en":"THE THING NEEDED: from a clinic's clean water to a household's means of living.","cn":"被需要之物：从诊所的干净水到家庭的生计来源。"},{"senses":"S3 · S7","en":"PRESSURE: poverty and 'out of necessity' both describe circumstances forcing a choice.","cn":"压力：贫困与“迫不得已”都描述处境逼迫下的选择。"},{"senses":"S5","en":"EVENTS THAT COULD NOT DIFFER: history read as inevitability rather than accident.","cn":"无法两样的事件：把历史读成必然而非偶然。"},{"senses":"S8","en":"A PHILOSOPHICAL CATEGORY: necessity set against chance in the order of things.","cn":"哲学范畴：在万物秩序中把必然与偶然对置。"}]},"affixes":{"intro":{"en":"Necessity is Latin necesse plus -ity, the noun suffix from -itas. The family runs through necessary, necessitate, and necessarily, with un- forming the negative.","cn":"necessity 是拉丁语 necesse 加 -ity（源自 -itas 的名词后缀）。词族包括 necessary、necessitate、necessarily，并用 un- 构成否定。"},"latinIntro":{"en":"The base is necesse, unavoidable, with the noun necessitas and the adjective necessarius. The deeper root of necesse is disputed.","cn":"词基是 necesse“不可避免”，名词 necessitas，形容词 necessarius。necesse 的更早词根存在争议。"},"items":[{"word":"necessary","structure":"Latin necessarius (unavoidable) + English -y","meaning":"required, or certain to happen","meaningCN":"必需的；必定发生的","example":"A visa is necessary for entry into the country.","exampleCN":"进入该国需要签证。"},{"word":"necessity","structure":"Latin necessitas (need, compulsion) + English -ity","meaning":"the state of being needed, or the thing needed","meaningCN":"必要性；必需品","example":"The war turned bread into a daily necessity.","exampleCN":"战争让面包成了日常必需品。"},{"word":"necessarily","structure":"necessary + -ly (adverb)","meaning":"in every case, or by logical consequence","meaningCN":"必然地；必定","example":"A higher price does not necessarily mean better quality.","exampleCN":"价格更高并不必然意味着质量更好。"},{"word":"necessitate","structure":"necessity + -ate (verb)","meaning":"to make something necessary","meaningCN":"使成为必要；需要","example":"The repair will necessitate closing the road for a week.","exampleCN":"这项维修将使道路必须关闭一周。"},{"word":"unnecessary","structure":"un- (not) + necessary","meaning":"not needed; avoidable","meaningCN":"不必要的；可避免的","example":"The extra form added an unnecessary delay.","exampleCN":"那张额外的表格造成了不必要的延误。"},{"word":"necessaries","structure":"necessary + -ies (plural noun)","meaning":"things needed for a purpose, especially in law and trade","meaningCN":"所需物品，尤用于法律与贸易语境","example":"The contract covered the necessaries for the voyage.","exampleCN":"合同涵盖了此次航行所需的物品。"},{"word":"necessitous","structure":"necessity + -ous (adjective)","meaning":"poor or needy; in urgent want","meaningCN":"贫困的；急需的","example":"The fund was set up for necessitous families.","exampleCN":"这项基金是为贫困家庭设立的。"},{"word":"necessities","structure":"necessity + -ies (plural noun)","meaning":"the goods needed for daily life","meaningCN":"日常生活所需的物品","example":"The shelter stores blankets and other necessities.","exampleCN":"收容所存放毯子和其他生活必需品。"}],"latinEntries":[{"word":"necesse","structure":"Latin adjective","meaning":"unavoidable, indispensable","meaningCN":"不可避免的；不可或缺的"},{"word":"necessitas","structure":"Latin noun","meaning":"compulsion, need, poverty","meaningCN":"强制；需要；贫困"},{"word":"necessarius","structure":"Latin adjective","meaning":"necessary, closely connected","meaningCN":"必要的；关系密切的"}]}},{"word":"negligible","ipa_uk":"/ˈneɡlɪdʒəbl/","ipa_us":"/ˈneɡlɪdʒəbl/","definition_zh":"微不足道的；可忽略不计的；微小的；无关紧要的","definition_en":"so small or unimportant that it can be ignored, especially in a calculation or judgement","core_image":"天平一端放着一整袋米，另一端只落了一粒芝麻，指针几乎没有动。","scene":"工程师盯着检测报告说，这点误差不会影响桥梁的承重判断。The error is negligible and will not affect the bridge's load estimate.","sceneCN":"这里 negligible 是“小到可以忽略不计的”（第 1 个义项）；句意：这点误差微不足道，不会影响桥梁的承重估算。","pos":[{"tag":"adj.","zh":"微不足道的；可忽略不计的；微小的；无关紧要的"}],"collocations":[{"phrase":"a negligible amount","zh":"可忽略的数量"},{"phrase":"a negligible effect","zh":"微不足道的影响"},{"phrase":"a negligible difference","zh":"可忽略的差异"},{"phrase":"a negligible risk","zh":"极低的风险"},{"phrase":"statistically negligible","zh":"统计上可忽略的"},{"phrase":"negligible cost","zh":"可忽略的成本"},{"phrase":"negligible in comparison","zh":"相比之下微不足道"}],"forms":[{"label":"原级（形容词）","form":"negligible"},{"label":"比较级（用 more）","form":"more negligible"},{"label":"最高级（用 most）","form":"most negligible"},{"label":"副词形式","form":"negligibly"}],"derivatives":[{"word":"neglect","pos":"v./n.","zh":"忽视；疏忽"},{"word":"negligence","pos":"n.","zh":"疏忽；失职"},{"word":"negligent","pos":"adj.","zh":"疏忽的；不留心的"},{"word":"negligibly","pos":"adv.","zh":"微乎其微地"}],"senses":[{"no":"01","title":"Small enough to ignore","titleCN":"微不足道：小到不必理会","definition":"so slight or unimportant that it need not be considered","definitionCN":"轻微或不重要到无须纳入考虑","example":"The dent in the door was negligible and could be left as it was.","exampleCN":"门上的凹痕微不足道，可以保持原样。","why":"The word does not measure size by itself; it measures the size against a purpose, and finds it below the level where action is required.","whyCN":"这个词本身不衡量大小，而是把大小放到某个目的旁边衡量，判定它低于需要采取行动的水平。"},{"no":"02","title":"A quantity too small to count","titleCN":"数量微小：多它一个也不变结果","definition":"a quantity so small that adding or removing it changes nothing measurable","definitionCN":"数量极小，增加或去掉都改变不了可测量的结果","example":"The impurity occurs in a negligible quantity, below one part per million.","exampleCN":"这种杂质的含量微乎其微，低于百万分之一。","why":"In measurement the threshold of the instrument sets the line: below that line the quantity exists but cannot affect the reading.","whyCN":"在测量中，仪器的阈值划出这条线：低于这条线的数量虽存在，却影响不了读数。"},{"no":"03","title":"A difference not worth arguing about","titleCN":"差异可忽略：差一点点，不算差","definition":"a difference between two things that is too small to matter in practice","definitionCN":"两事物之间的差异过小，在实践中无关紧要","example":"The two coatings differed by a negligible margin in wear tests.","exampleCN":"两种涂层在磨损测试中的差距可忽略不计。","why":"Comparing two results invites the question 'does it matter?'; negligible answers no, and so closes the comparison without denying the difference.","whyCN":"比较两个结果会引出“这要紧吗”的问题；negligible 回答“不要紧”，从而在不否认差异的前提下结束比较。"},{"no":"04","title":"A risk that can be accepted","titleCN":"风险极低：可以接受，不必防范","definition":"a level of danger low enough that no further protection is thought necessary","definitionCN":"危险程度低到被认为无须再采取额外防护","example":"Health officials called the exposure risk negligible for local residents.","exampleCN":"卫生官员称当地居民面临的暴露风险极低。","why":"Risk language adds a decision: when a hazard is negligible, the cost of guarding against it is judged higher than the hazard itself.","whyCN":"风险语言加入了一层决定：当危害 negligible 时，防范它的成本被判定为高于危害本身。"},{"no":"05","title":"Cost one barely notices","titleCN":"成本可忽略：花了也像没花","definition":"an expense small in relation to the budget or benefit involved","definitionCN":"相对于预算或收益而言小到几乎可以不计的开支","example":"The extra memory is a negligible cost compared with the processor.","exampleCN":"与处理器相比，增加的内存成本可以忽略。","why":"Money becomes negligible only against a larger figure; the adjective always implies a scale that makes one item fade.","whyCN":"只有对照更大的数字，金钱才显得 negligible；这个形容词总暗含一个让某项淡出的尺度。"},{"no":"06","title":"An effect too faint to detect","titleCN":"作用微弱：发生了，却看不出","definition":"an influence so weak that its results cannot be distinguished from noise","definitionCN":"影响弱到其结果无法与噪声区分","example":"The second variable had a negligible effect on the final score.","exampleCN":"第二个变量对最终得分的影响微乎其微。","why":"An effect is judged against background variation; if it hides inside the noise, it is negligible even if it is real.","whyCN":"作用是对照背景波动来判断的；如果它藏在噪声里，即使真实存在也算 negligible。"},{"no":"07","title":"Not statistically significant","titleCN":"统计上不显著：样本里看不出来","definition":"too small, relative to variation, for a statistical test to call it significant","definitionCN":"相对于数据波动太小，统计检验无法判为显著","example":"The difference in recovery rates was negligible at the chosen confidence level.","exampleCN":"在所选的置信水平上，康复率的差异在统计上可忽略。","why":"Statistical judgement compares an effect with the spread of the data; a negligible difference is one the test cannot separate from chance.","whyCN":"统计判断把效应与数据离散度相比；negligible 的差异就是检验无法与偶然区分开的差异。"},{"no":"08","title":"Safe to drop from a model","titleCN":"可省略：近似计算里直接划掉","definition":"small enough in a model or approximation that the term containing it can be omitted","definitionCN":"在模型或近似中足够小，可以删去含它的那一项","example":"For slow speeds, the relativistic correction is negligible.","exampleCN":"在低速情况下，相对论修正项可忽略不计。","why":"Here the word is an instruction: drop the term, and the error introduced stays inside the tolerance the model already accepts.","whyCN":"这里的词是一道指令：删掉该项，引入的误差仍落在模型本来就接受的容差之内。"}],"etymology":{"intro":{"en":"Negligible comes from French négligible, from the verb négliger, to neglect. That verb goes back to Latin neglegere, to disregard, literally 'not to pick up'.","cn":"negligible 来自法语 négligible，出自动词 négliger“忽视”。该动词上溯至拉丁语 neglegere“不理会”，字面意思是“不去捡起”。"},"items":[{"era":"LATIN neglegere","en":"Neglegere combined nec- 'not' with legere 'to pick up or choose'. To neglect was literally to leave something lying there, unpicked.","cn":"neglegere 由 nec-“不”与 legere“捡起、选择”组合而成。忽视就是字面上让某物躺在那儿，不去捡。"},{"era":"LATIN neglegibilis","en":"The adjective meant that could be disregarded. Latin used it for things one was entitled to leave out of account.","cn":"形容词形式意为“可以被不理会”。拉丁语用它指那些有权不计入考虑范围的事物。"},{"era":"FRENCH négliger","en":"Old French négliger kept the sense of neglecting a duty or a thing, and added the idea of carelessness in appearance and dress.","cn":"古法语 négliger 保留了“疏于职责或事物”的意思，并增加了外表与衣着上的随意、不修边幅之义。"},{"era":"FRENCH négligible","en":"French formed négligible as 'that may be neglected'. English took the word over in the 18th century with the quantitative sense already attached.","cn":"法语造出 négligible，意为“可以忽略的”。英语在 18 世纪借入时，数量化的含义已经附着在词上。"},{"era":"ENGLISH 18c","en":"English negligible first meant 'disregardable', then settled into the modern sense of a quantity or effect too small to matter.","cn":"英语 negligible 最初意为“可不予理会的”，随后固定为现代义：数量或作用小到无关紧要。"},{"era":"MODERN ENGLISH","en":"Statistics and engineering made the word a standard label for effects below a stated threshold, as in negligible risk and negligible error.","cn":"统计学与工程学使该词成为“低于既定阈值”的标准标签，如 negligible risk、negligible error。"}]},"similar":{"note":{"en":"The first group is the neglect family; the second compares words for smallness and unimportance, each with a different standard.","cn":"第一组是 neglect 词族；第二组比较表示“小”与“不重要”的词，各自标准不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"neglect","ipa":"/nɪˈɡlekt/","tag":"verb or noun","definition":"to fail to care for or attend to something. It names the act of leaving it undone.","definitionCN":"未能照料或处理某事；命名的是“放着不管”的行为。"},{"word":"negligence","ipa":"/ˈneɡlɪdʒəns/","tag":"legal noun","definition":"a failure to take proper care, especially as a breach of duty. It carries responsibility.","definitionCN":"未尽应有注意，尤指失职；带有责任意味。"},{"word":"negligent","ipa":"/ˈneɡlɪdʒənt/","tag":"adjective","definition":"careless about a duty or about safety. It describes a person or an act, not a size.","definitionCN":"对职责或安全疏忽的；描述人或行为，而非大小。"},{"word":"negligible","ipa":"/ˈneɡlɪdʒəbl/","tag":"adjective","definition":"small enough to be disregarded. The -ible ending makes it a passive possibility: can be neglected.","definitionCN":"小到可以不予理会；-ible 结尾表示被动可能：可以被忽略。"}]},{"heading":"NEAR MEANING","entries":[{"word":"insignificant","ipa":"/ˌɪnsɪɡˈnɪfɪkənt/","tag":"importance adjective","definition":"lacking meaning, influence, or importance. It judges significance rather than size.","definitionCN":"缺乏意义、影响或重要性；判断的是意义而非大小。"},{"word":"trivial","ipa":"/ˈtrɪviəl/","tag":"importance adjective","definition":"of little worth or consequence. It often carries a tone of dismissal.","definitionCN":"价值或后果很小；常带轻视语气。"},{"word":"marginal","ipa":"/ˈmɑːdʒɪnl/","tag":"degree adjective","definition":"at the edge of what matters, or very slight. It suggests a border rather than a vanishing point.","definitionCN":"处在重要性的边缘，或非常轻微；暗示边界而非消失点。"},{"word":"minute","ipa":"/maɪˈnjuːt/","tag":"size adjective","definition":"extremely small in size or amount. It states smallness without yet saying it can be ignored.","definitionCN":"尺寸或数量极小；只陈述小，还未说可以忽略。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: neglegere, to not pick up, plus -ible, 'able to be'. Negligible means 'able to be left lying there'.","cn":"只用真实成分：neglegere“不去捡起”，加 -ible“可以被……”。negligible 就是“可以被搁在那儿不管的”。"},"normal":[{"en":"Negligible = neglect + able: small enough that neglect is allowed.","cn":"negligible 等于 neglect 加 able：小到“可以 neglect（不管）”。"},{"en":"One sesame seed on one side of the scale moves the needle by almost nothing.","cn":"天平一端只放一粒芝麻，指针几乎不动。"},{"en":"Below the instrument's threshold, a quantity is real but negligible.","cn":"低于仪器阈值时，数量真实存在，但可忽略。"},{"en":"Negligible risk means the guard costs more than the danger.","cn":"风险可忽略，意味着防护的成本高于危险本身。"},{"en":"In a physics model, negligible is a permit to delete the term.","cn":"在物理模型里，negligible 就是允许你删掉那一项的通行证。"}],"abstract":[{"en":"Negligible is never a fact about the world alone; it is a fact about a purpose, a threshold, and a decision.","cn":"negligible 从来不只是关于世界的事实；它关于一个目的、一条阈值和一次决定。"},{"en":"What is negligible to one observer is the whole signal to another with a finer instrument.","cn":"对一个观察者可忽略的东西，对另一个拿着更精细仪器的人可能就是全部信号。"},{"en":"The word quietly forgives neglect: it says the thing was not worth picking up in the first place.","cn":"这个词悄悄为“忽视”开脱：它说那东西本来就不值得弯腰去捡。"}]},"examples":[{"en":"The warming effect of the extra lamp was negligible beside the heat already in the room.","cn":"与房间里已有的热量相比，那盏额外灯管的加热作用微不足道。"},{"en":"The two drugs differ by a negligible margin in the trial, so cost becomes the deciding factor.","cn":"两种药在试验中的差距可忽略，因此成本成了决定因素。"},{"en":"For a first model, we treat the friction of the pulley as negligible and check the error later.","cn":"在初版模型中，我们把滑轮的摩擦视为可忽略，事后再检验误差。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"negligible 里有 neglect（忽视）的影子——小到可以直接忽视，就是“微不足道”。","word":"negligible"},"root":"源自法语 négligible，出自 négliger（忽视），上溯拉丁语 neglegere：nec-“不”+ legere“捡起、选择”，字面为“不去捡起”，故引申为“可不予理会、微不足道”。","sensesIntro":{"en":"Eight senses of negligible. All say the same thing in different settings: whatever is being discussed falls below a threshold that would require attention. The threshold may be an instrument, a budget, a risk decision, a statistical test, or a model's tolerance.","cn":"negligible 的八个义项在不同场景里说着同一件事：所讨论之物低于需要关注的门槛。门槛可以是仪器精度、预算、风险决定、统计检验，或模型的容差。"},"semanticMap":{"core":{"en":"CORE IMAGE: a scale with a sack of rice on one side and a single sesame seed on the other; the pointer barely moves.","cn":"核心意象：天平一边一袋米，另一边一粒芝麻，指针几乎不动。"},"chain":["LATIN LEGERE = TO PICK UP, CHOOSE","LATIN NEC- = NOT","LATIN NEGLEGERE = TO LEAVE UNPICKED","LATIN NEGLEGIBILIS = THAT MAY BE DISREGARDED","FRENCH NEGLIGIBLE = DISREGARDABLE","ENGLISH NEGLIGIBLE = TOO SMALL TO MATTER"],"branches":[{"senses":"S1 · S3","en":"BELOW ATTENTION: too slight to act on, and a difference too small to argue about.","cn":"低于注意力线：轻微到无须行动，差异小到不必争论。"},{"senses":"S2 · S5","en":"BELOW SCALE: a quantity under the instrument's threshold and a cost under the budget's notice.","cn":"低于尺度：数量在仪器阈值之下，成本在预算注意之外。"},{"senses":"S4","en":"BELOW ACCEPTABLE HARM: a risk cheaper to accept than to guard against.","cn":"低于可接受的伤害：接受风险比防范更划算。"},{"senses":"S6 · S7","en":"BELOW NOISE: an effect hidden in variation, whether in the lab or in a statistical test.","cn":"低于噪声：作用藏在波动里，无论在实验室还是统计检验中。"},{"senses":"S8","en":"BELOW TOLERANCE: a term that can be deleted from a model without breaking it.","cn":"低于容差：可以从模型中删去而不使它失效的项。"}]},"affixes":{"intro":{"en":"Negligible is Latin neglegere plus -ible, 'able to be'. The family keeps the legere root in neglect, negligence, and negligent, where the idea is failing to pick something up.","cn":"negligible 是拉丁语 neglegere 加 -ible“可以被……”。词族在 neglect、negligence、negligent 中保留 legere 词根，核心意象是“没去捡起”。"},"latinIntro":{"en":"The base is legere, to pick up, read, or choose, negated by nec-. Legere also gives collect, select, elect, and lecture through related prefixes.","cn":"词基是 legere“捡起、阅读、选择”，由 nec- 否定。legere 还通过其他前缀给出 collect、select、elect、lecture。"},"items":[{"word":"neglect","structure":"Latin neglegere (not pick up) through French neglect","meaning":"to fail to care for or attend to","meaningCN":"忽视；疏于照料","example":"They neglected the roof until it leaked.","exampleCN":"他们一直没管屋顶，直到它漏水。"},{"word":"negligence","structure":"negligent + -ence (state noun)","meaning":"failure to take proper care, especially as a legal fault","meaningCN":"疏忽；尤指法律上的过失","example":"The court found negligence in the maintenance of the lift.","exampleCN":"法院认定电梯维护存在过失。"},{"word":"negligent","structure":"Latin neglegens (disregarding) + -ent","meaning":"careless about a duty","meaningCN":"对职责疏忽的","example":"A negligent driver failed to check the mirror.","exampleCN":"一位疏忽的司机没有看后视镜。"},{"word":"negligible","structure":"neglect + -ible (able to be)","meaning":"small enough to be disregarded","meaningCN":"小到可以不予理会","example":"The delay was negligible for most passengers.","exampleCN":"对大多数乘客而言，这点延误微不足道。"},{"word":"negligibly","structure":"negligible + -y (adverb)","meaning":"to a degree that can be ignored","meaningCN":"微乎其微地","example":"The new route is negligibly longer than the old one.","exampleCN":"新路线只比旧路线长一点点。"},{"word":"collect","structure":"col- (together) + legere (pick up)","meaning":"to gather things together","meaningCN":"收集；聚集","example":"The survey collects responses from every district.","exampleCN":"这项调查从每个区收集反馈。"},{"word":"select","structure":"se- (apart) + legere (choose)","meaning":"to pick out from a group","meaningCN":"挑选；选出","example":"The panel selects ten applicants for interview.","exampleCN":"评审小组选出十名申请人参加面试。"},{"word":"eligible","structure":"e- (out) + legere (pick) + -ible","meaning":"qualified to be chosen","meaningCN":"有资格被选中的","example":"Only full members are eligible to vote.","exampleCN":"只有正式成员有资格投票。"},{"word":"legible","structure":"legere (read) + -ible (able to be)","meaning":"clear enough to be read","meaningCN":"清晰可读的","example":"The signature was barely legible.","exampleCN":"那个签名几乎看不清。"}],"latinEntries":[{"word":"legere","structure":"Latin verb","meaning":"to pick up, gather, read, choose","meaningCN":"捡起；收集；阅读；选择"},{"word":"neglegere","structure":"nec- (not) + legere","meaning":"to disregard, leave uncared for","meaningCN":"不理会；疏于照料"},{"word":"neglegibilis","structure":"Latin adjective","meaning":"that may be disregarded","meaningCN":"可不予理会的"}]}},{"word":"negotiation","ipa_uk":"/ˌneɡəʊʃiˈeɪʃn/","ipa_us":"/ˌneɡoʊʃiˈeɪʃn/","definition_zh":"谈判；协商；议价；通过（弯道、障碍）；（票据）兑现","definition_en":"the process of discussing something in order to reach an agreement, or the successful passing of a difficult route or a financial instrument","core_image":"两个人隔桌而坐，桌上摊着一张纸，各自把笔移到中间那条线的两侧。","scene":"两家公司在会议室里逐条修改合同，先把价格放一边。They began a long negotiation over delivery dates.","sceneCN":"这里 negotiation 是“为达成协议而进行的谈判”（第 1 个义项）；句意：他们开始就交货日期进行长时间的谈判。","pos":[{"tag":"n.","zh":"谈判；协商；议价；（弯道、障碍的）通过；（票据的）兑现、转让"}],"collocations":[{"phrase":"enter into negotiations","zh":"开始谈判"},{"phrase":"peace negotiations","zh":"和平谈判"},{"phrase":"a negotiation over pay","zh":"关于薪酬的谈判"},{"phrase":"under negotiation","zh":"在谈判中"},{"phrase":"negotiation skills","zh":"谈判技巧"},{"phrase":"a negotiating position","zh":"谈判立场"}],"forms":[{"label":"复数（名词）","form":"negotiations"},{"label":"动词形式","form":"negotiate"},{"label":"名词（谈判者）","form":"negotiator"},{"label":"形容词形式","form":"negotiable"}],"derivatives":[{"word":"negotiate","pos":"v.","zh":"谈判；协商；通过（险处）；兑现（票据）"},{"word":"negotiator","pos":"n.","zh":"谈判者；协商代表"},{"word":"negotiable","pos":"adj.","zh":"可谈判的；可兑现的"},{"word":"renegotiate","pos":"v.","zh":"重新谈判；重新协商"}],"senses":[{"no":"01","title":"Talk aimed at agreement","titleCN":"谈判：把分歧谈到一致","definition":"the process of discussion between parties who want an agreement but do not yet share the same terms","definitionCN":"希望达成协议但条件尚未一致的各方向进行讨论的过程","example":"The negotiation lasted three days before both sides signed.","exampleCN":"谈判持续了三天，双方才签字。","why":"The word names the whole process, not one offer: parties move positions until a text can be accepted by both.","whyCN":"这个词命名的是整个过程，而不是某一次报价：各方不断移动立场，直到出现双方都能接受的文本。"},{"no":"02","title":"Bargaining over price and terms","titleCN":"议价磋商：一项一项地换条件","definition":"bargaining in which price, quantity, delivery, or other terms are traded against each other","definitionCN":"就价格、数量、交货或其他条款相互交换让步的讨价还价","example":"The price was settled in a separate negotiation over volume discounts.","exampleCN":"价格在另一场关于批量折扣的议价中确定。","why":"Commerce turns agreement into a trade of terms: one side gives on price, the other gives on time, and the sum must still balance.","whyCN":"商业把协议变成条款交换：一方在价格上让步，另一方在时间上让步，总和仍须平衡。"},{"no":"03","title":"Diplomatic bargaining","titleCN":"外交谈判：国家之间的文字较量","definition":"formal talks between states or political groups, often over conflict, borders, or treaties","definitionCN":"国家或政治集团之间就冲突、边界或条约进行的正式会谈","example":"The peace negotiation produced a ceasefire but no final border.","exampleCN":"和平谈判带来了停火，却没有确定最终边界。","why":"When the parties are states, the same process carries public authority: what is agreed becomes a document that binds populations, not just signers.","whyCN":"当各方是国家时，同一过程带有公共权威：谈成的内容会成为约束民众而不仅是签字者的文件。"},{"no":"04","title":"Dealing over work and pay","titleCN":"合同薪酬谈判：把自己的条件摆上桌","definition":"talks between an employer and an employee or union about wages, hours, and working conditions","definitionCN":"雇主与雇员或工会就工资、工时与劳动条件进行的会谈","example":"Her salary negotiation gained a raise and an extra week of leave.","exampleCN":"她的薪酬谈判争取到了加薪和额外一周假期。","why":"Here the abstract process becomes personal: the terms being traded are the conditions of one's daily life, so preparation and timing matter.","whyCN":"这里抽象过程变得切身：被交换的条款是一个人日常生活的条件，因此准备与时机都很重要。"},{"no":"05","title":"Getting a vehicle round a bend","titleCN":"过弯：把车身稳稳带过弯道","definition":"the act of steering or driving a vehicle safely through a curve or narrow passage","definitionCN":"操纵车辆安全通过弯道或狭窄路段的行为","example":"The bus slowed for the sharp negotiation of the mountain road.","exampleCN":"大巴减速以通过山路的急弯。","why":"From 'dealing with a difficulty' comes the physical sense: the driver negotiates the curve as a rider negotiates a rough path.","whyCN":"从“应对困难”引申出物理义：司机把车稳稳带过弯道，就像骑手带马穿过一段崎岖小路。"},{"no":"06","title":"Passing an obstacle","titleCN":"越过险处：从障碍中穿过去","definition":"the successful passing of a physical obstruction, such as a fence, a reef, or rough ground","definitionCN":"成功穿过栅栏、暗礁或崎岖地面等物理障碍","example":"The boat's negotiation of the reef took all the crew's attention.","exampleCN":"船只穿越暗礁的过程让全体船员全神贯注。","why":"The sense keeps the core idea of dealing with something difficult, but the difficulty is now ground or water rather than another person.","whyCN":"这一义项保留“应对难事”的核心意思，但难事从“另一个人”变成了地面或水面。"},{"no":"07","title":"Cashing or transferring an instrument","titleCN":"票据兑现：让一张纸变成钱","definition":"the passing of a cheque, bill, or other financial instrument through the banking system so that it is paid or transferred","definitionCN":"让支票、汇票等金融票据经银行系统完成付款或转让","example":"The negotiation of the cheque failed because the signature did not match.","exampleCN":"这张支票因签名不符而未能兑现。","why":"A financial instrument must also be 'carried through' a system; the old commercial sense of negotiation survives in banking as the successful passage of paper.","whyCN":"金融票据也必须“穿过”一套系统；negotiation 古老的商业义项在银行领域以“票据顺利通过”的形式留存下来。"},{"no":"08","title":"Agreeing on what words mean","titleCN":"意义协商：边说边确认对方懂了","definition":"the interactive process by which speakers adjust wording until both understand a meaning in the same way","definitionCN":"说话者调整措辞，直到双方以相同方式理解某一含义的互动过程","example":"In the language class, the negotiation of meaning happened through gestures and repetition.","exampleCN":"在语言课上，意义协商通过手势和重复完成。","why":"Even without a contract, two minds must reach a shared version of what a word refers to; that temporary agreement is a negotiation too.","whyCN":"即使没有合同，两个头脑也必须就一个词指什么达成共同版本；这种临时一致同样是一场谈判。"}],"etymology":{"intro":{"en":"Negotiation comes from Latin negotiatio, business or trade, from negotiari, to do business, and negotium, a matter of business. Its literal makeup is 'not leisure'.","cn":"negotiation 来自拉丁语 negotiatio“生意、交易”，出自动词 negotiari“做买卖”与名词 negotium“事务、业务”。其字面构成是“不闲暇”。"},"items":[{"era":"LATIN otium","en":"Otium meant leisure, ease, or time free from public affairs. It is the peaceful half of the word's ancestry.","cn":"otium 意为闲暇、安逸，或免于公共事务的时间；它是这个词祖先中安静的那一半。"},{"era":"LATIN negotium","en":"Negotium joined nec- 'not' to otium: not-leisure, hence business, employment, and a matter requiring effort.","cn":"negotium 把 nec-“不”与 otium 结合：不闲暇，因而指业务、职务，以及需要费力的事务。"},{"era":"LATIN negotiari","en":"The verb meant to carry on business, to trade, and also to transact or manage a matter.","cn":"该动词意为做买卖、从事交易，也指经办或处理一桩事务。"},{"era":"LATIN negotiatio","en":"The noun named business, traffic in goods, and the conduct of a transaction. It did not yet mean formal talks.","cn":"该名词指生意、货物交易以及交易的处理，当时还没有“正式会谈”的意思。"},{"era":"FRENCH négociation","en":"French narrowed the word toward the talks that precede a transaction, and English borrowed that sense in the 16th century.","cn":"法语把词义收窄到交易之前的商谈，英语在 16 世纪借入了这一含义。"},{"era":"MODERN ENGLISH","en":"Diplomacy, labour relations, and banking each kept a branch: talks, bargaining, and the passing of an instrument through a system.","cn":"外交、劳资关系与银行各自保留了一条分支：会谈、议价，以及票据在系统中的通过。"}]},"similar":{"note":{"en":"The first group is the negotiate family; the second compares ways of settling a difference, from friendly talk to third-party decision.","cn":"第一组是 negotiate 词族；第二组比较解决分歧的方式，从友好商谈到第三方裁决。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"negotiate","ipa":"/ˈneɡəʊʃieɪt/","tag":"verb","definition":"to discuss in order to agree, or to get past a difficulty. It names the action.","definitionCN":"为达成一致而商谈，或越过困难；命名的是动作。"},{"word":"negotiator","ipa":"/ˌneɡəʊʃiˈeɪtə/","tag":"person noun","definition":"a person who takes part in talks on behalf of a side. It names the actor, not the process.","definitionCN":"代表一方参加谈判的人；命名的是行动者，不是过程。"},{"word":"negotiable","ipa":"/ˌneɡəʊʃiˈeɪbl/","tag":"adjective","definition":"open to being changed by agreement, or able to be transferred as payment. It describes a quality of terms.","definitionCN":"可经协商改变的，或可作为支付转让的；描述条款的性质。"},{"word":"negotiation","ipa":"/ˌneɡəʊʃiˈeɪʃn/","tag":"noun","definition":"the process or an instance of bargaining. The -ation ending makes it the activity itself.","definitionCN":"谈判的过程或一次谈判；-ation 后缀使它成为活动本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"bargaining","ipa":"/ˈbɑːɡənɪŋ/","tag":"noun","definition":"hard trading of offers, especially over price. It sounds more competitive than negotiation.","definitionCN":"围绕报价的强硬交换，尤指价格；比 negotiation 更有竞争味。"},{"word":"mediation","ipa":"/ˌmediˈeɪʃn/","tag":"noun","definition":"help from a neutral third party to reach agreement. The parties still decide, but someone else runs the talk.","definitionCN":"由中立第三方协助达成协议；仍由当事方决定，但谈话由他人主持。"},{"word":"arbitration","ipa":"/ˌɑːbɪˈtreɪʃn/","tag":"noun","definition":"settlement by an outside judge whose decision binds the parties. It replaces negotiation with a ruling.","definitionCN":"由外部裁决者作出有约束力的决定；以裁决取代谈判。"},{"word":"consultation","ipa":"/ˌkɒnsʌlˈteɪʃn/","tag":"noun","definition":"asking for opinions before deciding. It gathers views but does not require agreement.","definitionCN":"决定前征求意见；收集看法，但不要求达成一致。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: nec- 'not' plus otium 'leisure'. Business is literally not-leisure, and negotiation is the talk that business requires.","cn":"只用真实成分：nec-“不”加 otium“闲暇”。业务字面上就是“不闲暇”，而 negotiation 是业务所需的商谈。"},"normal":[{"en":"Not-leisure: the moment people stop relaxing and start trading terms.","cn":"不闲暇：人们停止放松、开始交换条件的那一刻。"},{"en":"A negotiation is a table with two pens and one text between them.","cn":"谈判就是一张桌子、两支笔，以及中间那一份文本。"},{"en":"In banking, negotiation is paper passing through a system; in driving, it is a car passing through a curve.","cn":"在银行，negotiation 是票据穿过系统；在驾驶，是车穿过弯道。"},{"en":"Salary negotiation trades hours of your life for a number on a contract.","cn":"薪酬谈判用你生命中的小时数换合同上的一个数字。"},{"en":"Language learners negotiate meaning with gestures before they find the word.","cn":"语言学习者先用手势协商意义，然后才找到那个词。"}],"abstract":[{"en":"Negotiation begins only where two sides are both dependent and unwilling to lose the other.","cn":"谈判只始于双方既相互依赖、又不愿失去对方的地方。"},{"en":"The word's ancestry says business is the absence of leisure; the modern noun says agreement is the absence of easy silence.","cn":"这个词的祖先说业务是闲暇的缺席；现代名词则说协议是轻松沉默的缺席。"},{"en":"To negotiate a bend is to accept that the path will not be straight; every agreement has a curve built into it.","cn":"把车带过一个弯道，就是接受道路不会笔直；每份协议里都内置了一道弯。"}]},"examples":[{"en":"The union entered negotiations with a single demand: a fixed schedule two weeks in advance.","cn":"工会带着一项诉求进入谈判：提前两周给出固定排班。"},{"en":"Years of practice let the old driver negotiate the narrow bridge without slowing much.","cn":"多年练习让老司机几乎不减速就通过了那座窄桥。"},{"en":"The cheque failed negotiation because the account had been closed.","cn":"这张支票未能兑现，因为账户已经销户。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"nego（不）+ tiation（歇）——不歇着，坐下来谈条件，就是谈判。","word":"negotiation"},"root":"源自拉丁语 negotiatio（生意、交易），出自 negotium（事务、业务），字面为 nec-“不”+ otium“闲暇”，即“不闲暇之事”；后经法语收窄为“交易前的商谈”，再扩展出外交、劳资、过弯与票据兑现等义。","sensesIntro":{"en":"Eight senses of negotiation. The core is always a difficult passage made manageable: two sides pass from disagreement to agreement, a driver passes a curve, a cheque passes through a bank, or two speakers pass into shared meaning.","cn":"negotiation 的八个义项，核心始终是“让一段难走的路变得可走”：双方从分歧走到一致，司机通过弯道，支票穿过银行系统，两个说话者进入共同理解。"},"semanticMap":{"core":{"en":"CORE IMAGE: two people at a table, one sheet of paper, and each pen moving toward the middle line.","cn":"核心意象：两人隔桌，一张纸，两支笔各自向中间那条线移动。"},"chain":["LATIN OTIUM = LEISURE","LATIN NEC-OTIUM = NOT-LEISURE, BUSINESS","LATIN NEGOTIARI = TO DO BUSINESS","LATIN NEGOTIATIO = TRADE, TRANSACTION","FRENCH NEGOCIATION = TALKS BEFORE A DEAL","ENGLISH NEGOTIATION = THE PROCESS OF REACHING TERMS"],"branches":[{"senses":"S1 · S2","en":"MAKING A DEAL: the general process and the item-by-item trade of price and terms.","cn":"达成交易：一般谈判过程，与逐项交换价格和条款的议价。"},{"senses":"S3 · S4","en":"TALKS WITH WEIGHT: state-to-state diplomacy and employer-to-employee bargaining.","cn":"有分量的会谈：国家对国家的外交，与雇主对雇员的劳资谈判。"},{"senses":"S5 · S6","en":"PHYSICAL PASSAGE: steering through a bend and passing a reef or rough ground.","cn":"物理通过：驾车过弯，以及穿过暗礁或崎岖地面。"},{"senses":"S7","en":"FINANCIAL PASSAGE: a cheque or bill carried through the banking system.","cn":"金融通过：支票或汇票经银行系统完成流转。"},{"senses":"S8","en":"SHARED MEANING: speakers adjusting words until both mean the same thing.","cn":"共享意义：说话者调整措辞，直到双方所指相同。"}]},"affixes":{"intro":{"en":"Negotiation is negotiate plus -ion, the action-noun suffix. The family adds -or for the person, -able for what can be traded or changed, and re- for doing it again.","cn":"negotiation 是 negotiate 加 -ion（动作名词后缀）。词族用 -or 表示人，-able 表示可交易或可更改，re- 表示重新进行。"},"latinIntro":{"en":"The Latin base is otium, leisure, negated by nec-. Negotium and negotiari are the business words built on that negation.","cn":"拉丁词基是 otium“闲暇”，由 nec- 否定。negotium 与 negotiari 就是建立在这一否定之上的业务用语。"},"items":[{"word":"otium","structure":"Latin noun","meaning":"leisure, ease, freedom from public business","meaningCN":"闲暇；安逸；免于公共事务","example":"Otium in Roman life meant time for letters and thought.","exampleCN":"在罗马生活中，otium 指用于写信与思考的时间。"},{"word":"negotiate","structure":"Latin negotiari (do business) + English -ate","meaning":"to discuss for agreement, or to get past a difficulty","meaningCN":"为达成协议而商谈，或越过困难","example":"They negotiated the price down by ten percent.","exampleCN":"他们把价格谈低了百分之十。"},{"word":"negotiation","structure":"negotiate + -ion (action noun)","meaning":"the process of bargaining or passing a difficulty","meaningCN":"谈判过程，或通过困难的过程","example":"The negotiation produced a draft both sides could sign.","exampleCN":"谈判产生了一份双方都能签署的草案。"},{"word":"negotiator","structure":"negotiate + -or (agent noun)","meaning":"one who conducts talks","meaningCN":"进行谈判的人","example":"The chief negotiator asked for a short break.","exampleCN":"首席谈判代表要求短暂休息。"},{"word":"negotiable","structure":"negotiate + -able (able to be)","meaning":"open to agreement, or legally transferable","meaningCN":"可协商的，或可依法转让的","example":"The delivery date is still negotiable.","exampleCN":"交货日期仍可协商。"},{"word":"renegotiate","structure":"re- (again) + negotiate","meaning":"to open the terms again","meaningCN":"重新谈判；重开条款","example":"The landlord agreed to renegotiate the lease.","exampleCN":"房东同意重新协商租约。"},{"word":"negotiant","structure":"Latin negotians (one doing business) + -ant","meaning":"a merchant or dealer, now rare","meaningCN":"商人、交易者（今已罕用）","example":"The old records list him as a negotiant in silk.","exampleCN":"旧档案把他记为丝绸商人。"},{"word":"negotiated","structure":"negotiate + -ed (past participle)","meaning":"settled by talks rather than by rule","meaningCN":"经谈判议定的，而非按规定定的","example":"The workers returned under a negotiated settlement.","exampleCN":"工人们在谈判达成的解决方案下复工。"}],"latinEntries":[{"word":"otium","structure":"Latin noun","meaning":"leisure, ease","meaningCN":"闲暇；安逸"},{"word":"negotium","structure":"nec- (not) + otium","meaning":"business, affair, task","meaningCN":"业务；事务；任务"},{"word":"negotiari","structure":"Latin deponent verb","meaning":"to do business, to trade","meaningCN":"做买卖；交易"}]}},{"word":"neutrality","ipa_uk":"/neˈtræləti/","ipa_us":"/neˈtræləti/","definition_zh":"中立；中性；不偏不倚；（化学）中性；（电）电中性；碳中和","definition_en":"the state of not taking sides, or of being neither one thing nor its opposite, as in chemistry, electricity, or climate policy","core_image":"一根细线吊着的小球停在两块磁铁正中间，两边拉力相等，它既不向左也不向右。","scene":"两国边境的小镇宣布不向任何一方提供补给，也不允许军队通过。The town declared its neutrality and let no troops through.","sceneCN":"这里 neutrality 是“在冲突中不偏向任何一方”（第 1 个义项）；句意：这座小镇宣布保持中立，不许任何军队通过。","pos":[{"tag":"n.","zh":"中立；中性；不偏不倚；（化学）中性；（电）电中性；碳中和"}],"collocations":[{"phrase":"political neutrality","zh":"政治中立"},{"phrase":"maintain neutrality","zh":"保持中立"},{"phrase":"declare neutrality","zh":"宣布中立"},{"phrase":"chemical neutrality","zh":"化学中性"},{"phrase":"a position of neutrality","zh":"中立立场"},{"phrase":"carbon neutrality","zh":"碳中和"}],"forms":[{"label":"不可数名词（通常无复数）","form":"neutrality"},{"label":"形容词形式","form":"neutral"},{"label":"动词形式","form":"neutralize"},{"label":"名词（中和过程）","form":"neutralization"}],"derivatives":[{"word":"neutral","pos":"adj.","zh":"中立的；中性的；无偏向的"},{"word":"neutralize","pos":"v.","zh":"使中和；抵消；使失效"},{"word":"neutralization","pos":"n.","zh":"中和；抵消"},{"word":"neutrally","pos":"adv.","zh":"中立地；不带倾向地"}],"senses":[{"no":"01","title":"Not taking a side","titleCN":"不站队：不偏向任何一边","definition":"the condition of not supporting either party in a dispute or conflict","definitionCN":"在争端或冲突中不支持任何一方的状态","example":"The mediator's neutrality was accepted by both families.","exampleCN":"这位调解人的中立态度为两个家庭所接受。","why":"The core sense is a refusal to tilt: the neutral party may care about the outcome but does not throw its weight behind one side.","whyCN":"核心含义是拒绝倾斜：中立方可以在意结果，但不把自己的分量压到某一方。"},{"no":"02","title":"A state's declared position","titleCN":"国家中立：不结盟、不参战","definition":"the formal policy of a country that does not join military alliances or take part in a war","definitionCN":"一国不加入军事同盟、不参与战争的正式政策","example":"The country's neutrality was written into its constitution.","exampleCN":"该国的中立地位被写入宪法。","why":"When a state is the subject, neutrality becomes law and policy: it must be declared, defended, and recognised by others to work.","whyCN":"当主体是国家时，中立变成法律与政策：它必须被宣布、被维护，并被他人承认才有效。"},{"no":"03","title":"Neither acid nor alkali","titleCN":"化学中性：两边都不偏","definition":"the condition of a solution that is neither acidic nor alkaline","definitionCN":"溶液既非酸性也非碱性的状态","example":"Pure water at room temperature shows chemical neutrality.","exampleCN":"室温下的纯水呈化学中性。","why":"Chemistry borrows the political image: the hydrogen ion and the hydroxide ion balance each other, so the solution stands at the middle.","whyCN":"化学借用了政治意象：氢离子与氢氧根离子相互平衡，于是溶液停在中间。"},{"no":"04","title":"Balanced electric charge","titleCN":"电中性：正负电荷相等","definition":"the state of an object or region with equal positive and negative charge","definitionCN":"物体或区域内正负电荷相等的状态","example":"A conductor returns to electrical neutrality once the extra charge spreads out.","exampleCN":"额外电荷散开后，导体便恢复电中性。","why":"Here neutrality is a sum: the plus and minus charges add to zero, and the object shows no net field of its own.","whyCN":"这里的 neutrality 是一个总和：正负电荷相加为零，物体不再显出自身的净场。"},{"no":"05","title":"A tone without colour","titleCN":"语气中性：不带情绪色彩","definition":"a style of speech or writing that avoids emotional colouring or evaluation","definitionCN":"避免情绪色彩或评价的说话与写作风格","example":"The report described the damage with deliberate neutrality.","exampleCN":"报告刻意以中性语气描述损失。","why":"Style also has sides: praise and blame pull a sentence one way, and neutrality keeps the wording flat enough to let facts stand alone.","whyCN":"文风也有方向：褒与贬把句子拉向一边，而中性让措辞足够平，好让事实自己站住。"},{"no":"06","title":"Reporting without favour","titleCN":"新闻中立：不替任何一方说话","definition":"the professional standard of presenting competing views without favouring one","definitionCN":"呈现对立观点而不偏袒某一方的职业标准","example":"Readers questioned the paper's neutrality after it ran the same source twice.","exampleCN":"该报两次采用同一消息源后，读者质疑其中立性。","why":"In journalism the claim is procedural: equal access, attributed sources, and no editorial tilt in the news pages.","whyCN":"在新闻业，这一主张是程序性的：平等接触、注明来源，新闻版面不带社论倾向。"},{"no":"07","title":"A judge free of interest","titleCN":"裁决中立：与结果无利害关系","definition":"the quality of an arbitrator or judge who has no personal stake in the outcome","definitionCN":"仲裁者或法官对结果没有个人利害关系的品质","example":"The panel chose an outside expert to guarantee neutrality.","exampleCN":"评审组选了一位外部专家来保证中立。","why":"Decision-making neutrality adds an institutional test: not only must one feel unbiased, one must also have nothing to gain.","whyCN":"裁决中的中立增加了一道制度检验：不仅要自觉无偏，还必须确实无利可图。"},{"no":"08","title":"Net zero in climate policy","titleCN":"碳中和：排放与吸收相抵","definition":"the condition in which the greenhouse gases added to the atmosphere are balanced by those removed","definitionCN":"排入大气的温室气体与被移除的量相抵的状态","example":"The city aims for carbon neutrality by mid-century.","exampleCN":"这座城市力争在本世纪中叶实现碳中和。","why":"Climate policy reuses the balance image: emissions on one side, removals on the other, and the goal is a net of zero.","whyCN":"气候政策再次使用“平衡”意象：一边排放，一边移除，目标是净额为零。"}],"etymology":{"intro":{"en":"Neutrality is neutral plus -ity. Neutral goes back to Latin neutralis, from neuter, 'neither of the two', built from ne- 'not' and uter 'either one of two'.","cn":"neutrality 是 neutral 加 -ity。neutral 上溯拉丁语 neutralis，出自 neuter“两者皆非”，由 ne-“不”与 uter“两者之一”构成。"},"items":[{"era":"LATIN uter","en":"Uter meant which of the two. It is the root of the pair image: the word always imagines exactly two alternatives.","cn":"uter 意为“两者中的哪一个”。它是“成对”意象的词根：这个词总在设想恰好两个选项。"},{"era":"LATIN neuter","en":"Ne- plus uter gave neuter, neither one nor the other. Latin grammar used it for the third gender, neither masculine nor feminine.","cn":"ne- 加 uter 得到 neuter：两者都不是。拉丁语法用它指第三种性，既非阳性也非阴性。"},{"era":"LATIN neutralis","en":"Neutralis described what belongs to neither side. It was used in grammar and in law before it was used in politics.","cn":"neutralis 描述不属于任何一方的事物。它先用于语法与法律，之后才用于政治。"},{"era":"FRENCH neutralité","en":"French neutralité developed the political sense of a state that joins neither side in a war.","cn":"法语 neutralité 发展出政治含义：一国在战争中不加入任何一方。"},{"era":"ENGLISH 16c-17c","en":"English neutrality first named the legal and political condition, then extended to chemistry and electricity as those sciences found balanced states.","cn":"英语 neutrality 先指法律与政治状态，随后在化学与电学发现“平衡态”后扩展到这两门学科。"},{"era":"MODERN ENGLISH","en":"The 20th century added journalistic and judicial standards, and the 21st added carbon neutrality, all built on the same balance of two sides.","cn":"20 世纪增加了新闻与司法标准，21 世纪又增加了碳中和；它们都建立在同样的两边平衡之上。"}]},"similar":{"note":{"en":"The first group is the neutral family; the second compares ways of standing apart from a dispute.","cn":"第一组是 neutral 词族；第二组比较与争端保持距离的各种方式。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"neutral","ipa":"/ˈnjuːtrəl/","tag":"adjective","definition":"not supporting either side, or neither acid nor alkaline. It describes the state.","definitionCN":"不支持任何一方，或既非酸也非碱；描述状态。"},{"word":"neutralize","ipa":"/ˈnjuːtrəlaɪz/","tag":"verb","definition":"to cancel the effect of something, as an alkali cancels an acid.","definitionCN":"抵消某物的作用，如碱抵消酸。"},{"word":"neutralization","ipa":"/ˌnjuːtrəlaɪˈzeɪʃn/","tag":"noun","definition":"the act or process of cancelling an effect or a charge.","definitionCN":"抵消作用或电荷的行为与过程。"},{"word":"neutrally","ipa":"/ˈnjuːtrəli/","tag":"adverb","definition":"in a way that favours neither side.","definitionCN":"以不偏袒任何一方的方式。"}]},{"heading":"NEAR MEANING","entries":[{"word":"impartiality","ipa":"/ˌɪmpɑːˈʃiæləti/","tag":"judicial noun","definition":"fairness between parties, without favour or prejudice. It is a moral quality, while neutrality can be a policy.","definitionCN":"对各方公平、无偏无私；是道德品质，而 neutrality 可以是政策。"},{"word":"objectivity","ipa":"/ˌɒbdʒekˈtɪvəti/","tag":"epistemic noun","definition":"judgement based on evidence rather than personal feeling. It concerns facts, not sides.","definitionCN":"依据证据而非个人感受的判断；关乎事实，而非阵营。"},{"word":"non-alignment","ipa":"/ˌnɒn əˈlaɪnmənt/","tag":"political noun","definition":"a policy of not joining either bloc of powers. It is an active foreign policy, not a legal status.","definitionCN":"不加入任何大国集团的政策；是主动的外交政策，而非法律地位。"},{"word":"indifference","ipa":"/ɪnˈdɪfrəns/","tag":"attitude noun","definition":"lack of interest or concern. It can look like neutrality but comes from not caring about the outcome.","definitionCN":"缺乏兴趣或关心；表面上像中立，实则源于不在意结果。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: ne- 'not' plus uter 'either of two', then -ity. Neutrality is the state of being neither of the two.","cn":"只用真实成分：ne-“不”加 uter“两者之一”，再加 -ity。neutrality 就是“两者皆非”的状态。"},"normal":[{"en":"Ne-uter: not either one. The whole word is a refusal to choose between two.","cn":"ne-uter：两者都不是。整个词就是拒绝在两个选项之间选边。"},{"en":"A ball hung exactly between two magnets is the picture of neutrality.","cn":"小球悬在两块磁铁正中间，就是 neutrality 的画面。"},{"en":"In water, acid and alkali cancel; in politics, two sides cancel into silence.","cn":"在水里，酸碱相抵；在政治里，两方相抵成沉默。"},{"en":"A neutral report is flat in tone so that facts can stand upright.","cn":"中立的报道语气平坦，好让事实自己站直。"},{"en":"Carbon neutrality: emissions on one pan, removals on the other, net zero.","cn":"碳中和：一边排放，一边移除，净额为零。"}],"abstract":[{"en":"Neutrality is a position, and a position can be captured: whoever guarantees it may also lean on it.","cn":"中立是一种立场，而立场可以被占据：谁保证它，也可能借它施压。"},{"en":"In a world of two sides, saying 'neither' is still a choice that someone will count as support for the other.","cn":"在只有两方的世界里，说“都不是”仍是一种选择，总会有人把它算作对另一方的支持。"},{"en":"The word needs exactly two sides to exist; where there are three, neutrality has to be redefined.","cn":"这个词需要恰好两方才能成立；一旦有三方，中立就必须重新定义。"}]},"examples":[{"en":"The referee's neutrality was tested when both captains questioned the same decision.","cn":"两位队长都质疑同一个判罚时，裁判的中立性受到了考验。"},{"en":"A solution with equal acid and base shows neutrality, but it is not the same as pure water.","cn":"酸碱量相等的溶液呈中性，但它并不等同于纯水。"},{"en":"The firm promised carbon neutrality by 2040 and published its annual emissions audit.","cn":"该公司承诺在 2040 年前实现碳中和，并公布了年度排放审计。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"neuter（两者皆非）——既不偏左也不偏右，就是中立、中性。","word":"neutrality"},"root":"源自拉丁语 neutralis（不属于任何一方的），出自 neuter“两者皆非”，由 ne-“不”加 uter“两者之一”构成；经法语 neutralité 进入英语，由政治中立扩展到化学、电学与气候政策中的“平衡态”。","sensesIntro":{"en":"Eight senses of neutrality, all built on a balance of exactly two sides: two parties, acid and alkali, positive and negative charge, praise and blame, emission and removal. To be neutral is to keep the two in a state where neither wins.","cn":"neutrality 的八个义项都建立在“恰好两方”的平衡上：两个当事方、酸与碱、正与负电荷、褒与贬、排放与移除。中立就是让两边保持没有一方占上风的状态。"},"semanticMap":{"core":{"en":"CORE IMAGE: a small ball hanging exactly midway between two magnets, pulled equally from both sides.","cn":"核心意象：小球悬在两块磁铁正中，两边拉力相等。"},"chain":["LATIN UTER = EITHER OF TWO","LATIN NE-UTER = NEITHER OF THE TWO","LATIN NEUTRALIS = BELONGING TO NEITHER SIDE","FRENCH NEUTRALITE = NOT JOINING EITHER SIDE","ENGLISH NEUTRALITY = THE STATE OF NOT TILTING","ANY BALANCED STATE BETWEEN TWO OPPOSITES"],"branches":[{"senses":"S1 · S2","en":"POLITICAL BALANCE: a mediator who does not lean, and a state that does not enlist.","cn":"政治平衡：不倾斜的调解人，与不入伍的国家。"},{"senses":"S3 · S4","en":"PHYSICAL BALANCE: acid against alkali, positive charge against negative.","cn":"物理平衡：酸对碱，正电荷对负电荷。"},{"senses":"S5 · S6","en":"RHETORICAL BALANCE: a flat tone and a report that gives both views equal room.","cn":"修辞平衡：平坦的语气，以及给双方同等篇幅的报道。"},{"senses":"S7","en":"INSTITUTIONAL BALANCE: a judge with nothing to gain from the outcome.","cn":"制度平衡：裁决者与结果无利害关系。"},{"senses":"S8","en":"CLIMATE BALANCE: greenhouse gases emitted set against those removed.","cn":"气候平衡：排出的温室气体与移除的量相抵。"}]},"affixes":{"intro":{"en":"Neutrality is neutral plus -ity, the noun suffix for a state or quality. The family adds -ize for making neutral, -ization for that process, and -ly for manner.","cn":"neutrality 是 neutral 加 -ity（表示状态或性质的名词后缀）。词族用 -ize 表示“使中性”，-ization 表示该过程，-ly 表示方式。"},"latinIntro":{"en":"The base is uter, either of two, negated by ne-. Latin neuter and neutralis carry the 'neither side' idea into grammar, law, and politics.","cn":"词基是 uter“两者之一”，由 ne- 否定。拉丁语 neuter 与 neutralis 把“两边皆非”的观念带入语法、法律与政治。"},"items":[{"word":"neutral","structure":"Latin neutralis (belonging to neither) + English -al","meaning":"not favouring either side; neither acid nor alkaline","meaningCN":"不偏袒任何一方；既非酸也非碱","example":"The chair kept a neutral expression throughout.","exampleCN":"主席全程保持中立表情。"},{"word":"neutrality","structure":"neutral + -ity (state noun)","meaning":"the state of not taking sides","meaningCN":"不选边的状态；中立","example":"The treaty guaranteed the neutrality of the port.","exampleCN":"条约保证了该港口的中立地位。"},{"word":"neutralize","structure":"neutral + -ize (make)","meaning":"to cancel or make ineffective","meaningCN":"中和；抵消；使失效","example":"Lime is added to neutralize the acid in the soil.","exampleCN":"加入石灰以中和土壤中的酸。"},{"word":"neutralization","structure":"neutralize + -ation (process noun)","meaning":"the process of cancelling an effect","meaningCN":"中和或抵消的过程","example":"Neutralization of the spill took two days.","exampleCN":"泄漏物的中和处理花了两天。"},{"word":"neutrally","structure":"neutral + -ly (adverb)","meaning":"without favouring either side","meaningCN":"不偏不倚地","example":"The moderator phrased the question neutrally.","exampleCN":"主持人以中立措辞提出问题。"},{"word":"neutron","structure":"neutral + -on (particle suffix)","meaning":"a particle with no electric charge","meaningCN":"不带电荷的粒子；中子","example":"A neutron carries no charge and is not bent by a magnet.","exampleCN":"中子不带电，不会被磁铁偏转。"},{"word":"neutrino","structure":"Italian neutrino, from neutro (neutral) + -ino (small)","meaning":"a nearly massless neutral particle","meaningCN":"几乎无质量的中性粒子；中微子","example":"The detector caught a neutrino from the sun.","exampleCN":"探测器捕获了一个来自太阳的中微子。"},{"word":"neutralism","structure":"neutral + -ism (policy)","meaning":"a policy of staying out of great-power blocs","meaningCN":"不加入大国集团的政策；中立主义","example":"Neutralism guided the country's foreign policy for decades.","exampleCN":"中立主义指导该国外交数十年。"}],"latinEntries":[{"word":"uter","structure":"Latin pronoun","meaning":"either one of two","meaningCN":"两者中的任一"},{"word":"neuter","structure":"ne- (not) + uter","meaning":"neither of the two; the neuter gender","meaningCN":"两者皆非；中性（语法）"},{"word":"neutralis","structure":"Latin adjective","meaning":"belonging to neither side","meaningCN":"不属于任何一方的；中性的"}]}},{"word":"numerical","ipa_uk":"/njuːˈmerɪkl/","ipa_us":"/nuːˈmerɪkl/","definition_zh":"数字的；数值的；用数字表示的；数量上的","definition_en":"relating to numbers, or expressed by numbers rather than by words or symbols","core_image":"一面墙上钉满小格，每一格里只写一个数字，没有形容词，也没有描述。","scene":"实验报告不写“效果很好”，只列出一排测量值。The report gives only numerical results.","sceneCN":"这里 numerical 是“以数字形式表示、与数值有关的”（第 2 个义项）；句意：报告只给出数值结果。","pos":[{"tag":"adj.","zh":"数字的；数值的；用数字表示的；数量上的"}],"collocations":[{"phrase":"a numerical value","zh":"数值"},{"phrase":"numerical data","zh":"数值数据"},{"phrase":"numerical order","zh":"数字顺序"},{"phrase":"numerical analysis","zh":"数值分析"},{"phrase":"numerical superiority","zh":"数量上的优势"},{"phrase":"numerical control","zh":"数字控制；数控"},{"phrase":"a numerical simulation","zh":"数值模拟"}],"forms":[{"label":"原级（形容词）","form":"numerical"},{"label":"比较级（用 more）","form":"more numerical"},{"label":"最高级（用 most）","form":"most numerical"},{"label":"副词形式","form":"numerically"},{"label":"异体拼写","form":"numeric"}],"derivatives":[{"word":"number","pos":"n./v.","zh":"数字；数量；编号"},{"word":"numeral","pos":"n./adj.","zh":"数字符号；数字的"},{"word":"numerically","pos":"adv.","zh":"数值上；按数字地"},{"word":"numerate","pos":"adj./v.","zh":"识数的；计算"}],"senses":[{"no":"01","title":"Belonging to numbers","titleCN":"数字的：与数字本身有关","definition":"relating to numbers as such, or to the system of counting and calculation","definitionCN":"与数字本身或计数与计算体系有关","example":"The keyboard layout follows a numerical system, not an alphabetical one.","exampleCN":"这个键盘布局遵循数字体系，而不是字母体系。","why":"The adjective marks the domain: the subject is numbers, so questions of value, order, and amount all belong here.","whyCN":"这个形容词标出领域：主题是数字，因此值、顺序与数量的问题都归在这里。"},{"no":"02","title":"Expressed as a number","titleCN":"用数字表示：不写形容词，只写数","definition":"given in the form of a number rather than a word or a symbol","definitionCN":"以数字而非词语或符号的形式给出","example":"The rating is numerical, from one to ten, with no verbal comment.","exampleCN":"评分是数值型的，从一到十，不附文字评语。","why":"Here the word contrasts forms of expression: the same fact could be said in words, but a numerical form allows counting and comparison.","whyCN":"这里这个词对比表达形式：同一事实可以用文字说，但数值形式便于计数与比较。"},{"no":"03","title":"A number attached to a quantity","titleCN":"数值：给量配上一个数","definition":"the particular number that expresses the size of a quantity in stated units","definitionCN":"在给定单位下表示某一量大小的具体数字","example":"The numerical value of the coefficient depends on the units chosen.","exampleCN":"该系数的数值取决于所选单位。","why":"A quantity has a size, and numerical names the number that reports it; change the unit and the number changes while the quantity does not.","whyCN":"一个量有大小，numerical 指的是报告它大小的那个数；换单位，数会变，量本身不变。"},{"no":"04","title":"Ordered by number","titleCN":"按数字排序：一二三四排下去","definition":"arranged according to number rather than by name, date, or topic","definitionCN":"按数字而非名称、日期或主题排列","example":"The files are stored in numerical order from 001 to 999.","exampleCN":"这些档案按 001 到 999 的数字顺序存放。","why":"Numbers provide a sequence that needs no interpretation: once the rule is fixed, anyone can find where an item belongs.","whyCN":"数字提供一种无须解释的次序：规则一旦固定，任何人都能找到某物该放哪儿。"},{"no":"05","title":"Strength in count, not skill","titleCN":"数量优势：人多，而非更强","definition":"advantage that comes from having more people or units than an opponent","definitionCN":"因人数或单位数量多于对手而取得的优势","example":"The defenders had numerical superiority but no better position.","exampleCN":"防守方在人数上占优，但地形并不更好。","why":"In military and competitive settings, numerical compares counts rather than quality, and the word admits that quantity can decide even without skill.","whyCN":"在军事与竞赛语境里，numerical 比较的是数量而非质量；这个词承认数量有时无须技巧也能决定胜负。"},{"no":"06","title":"Solved by calculation","titleCN":"数值方法：用近似计算求解","definition":"describing methods that approximate solutions by repeated calculation rather than exact algebra","definitionCN":"指通过反复计算逼近解，而非求出精确代数解的方法","example":"The weather model uses numerical methods to step the atmosphere forward.","exampleCN":"天气模型用数值方法把大气状态一步步向前推进。","why":"When equations cannot be solved exactly, calculation replaces derivation; numerical marks that the answer is an approximation built from many small steps.","whyCN":"当方程无法精确求解时，计算取代推导；numerical 标出答案是由许多小步凑出的近似。"},{"no":"07","title":"Data in number form","titleCN":"数值数据：能进表格的那种资料","definition":"information recorded as measurements or counts and therefore open to arithmetic","definitionCN":"以测量值或计数记录、因而可作算术处理的信息","example":"The study combined numerical data with interviews of the same families.","exampleCN":"该研究把数值数据与对同一批家庭的访谈结合起来。","why":"Data becomes numerical when it has been given units and a scale, which is what allows it to be averaged, plotted, and tested.","whyCN":"数据在被赋予单位与标度后才成为数值数据，也正因如此才能求平均、绘图与检验。"},{"no":"08","title":"Machine control by numbers","titleCN":"数控：让机器照着数字走","definition":"describing the control of a machine by coded numerical instructions rather than by a hand-operated lever","definitionCN":"指用编码数字指令而非手动操纵杆控制机器","example":"The workshop replaced its manual lathes with numerical control machines.","exampleCN":"这家车间用数控机床取代了手动车床。","why":"The word entered manufacturing because a path can be described as a list of coordinates; numbers then become the instructions a tool follows.","whyCN":"这个词进入制造业，是因为一条路径可以写成一组坐标；数字由此成为刀具遵循的指令。"}],"etymology":{"intro":{"en":"Numerical comes from Latin numerus, a number, through the adjective numericus and the English suffix -al. The same root gives numeral, numerous, and enumerate.","cn":"numerical 来自拉丁语 numerus“数字”，经形容词 numericus 与英语后缀 -al 构成。同一词根还给出 numeral、numerous、enumerate。"},"items":[{"era":"LATIN numerus","en":"Numerus meant a number, a count, a measure, and also a rhythm or a place in a series.","cn":"numerus 意为数字、计数、度量，也可指节奏或序列中的位置。"},{"era":"LATIN numerare","en":"The verb meant to count or to reckon. It is the source of English enumerate, to count out one by one.","cn":"动词意为计数、结算。它是英语 enumerate（逐一点数）的来源。"},{"era":"LATIN numerosus","en":"The adjective meant full of numbers, hence numerous or many. English numerous keeps only the 'many' sense.","cn":"该形容词意为“充满数字的”，因而表示“众多”。英语 numerous 只保留了“多”的意思。"},{"era":"LATIN numericus","en":"Later Latin numericus meant concerned with numbers. It passed into learned English as numeric and numerical.","cn":"晚期拉丁语 numericus 意为“与数字有关的”，作为学术词进入英语，形成 numeric 与 numerical。"},{"era":"ENGLISH 17c","en":"Numerical entered English through mathematical writing, where it distinguished quantity from shape, word, or symbol.","cn":"numerical 经数学写作进入英语，用来把“数量”与形状、词语、符号区分开。"},{"era":"MODERN ENGLISH","en":"Computing and engineering widened the word to numerical methods, numerical data, and numerical control, where numbers serve as instructions.","cn":"计算与工程把该词扩展到数值方法、数值数据与数控；在这些领域，数字成了指令。"}]},"similar":{"note":{"en":"The first group is the number family; the second compares adjectives that describe measurement and quantity.","cn":"第一组是 number 词族；第二组比较描述度量与数量的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"number","ipa":"/ˈnʌmbə/","tag":"noun or verb","definition":"a count or symbol; or to count. It is the base noun behind all these forms.","definitionCN":"计数或数字符号；也可作动词表示计数。它是这些形式背后的基础名词。"},{"word":"numeral","ipa":"/ˈnjuːmərəl/","tag":"noun or adjective","definition":"a written symbol for a number, such as 7 or VII. It names the mark, not the quantity.","definitionCN":"表示数字的书写符号，如 7 或 VII；命名的是符号，不是数量。"},{"word":"numeric","ipa":"/ˈnjuːmərɪk/","tag":"adjective","definition":"another form of numerical, now especially common in computing and keypads.","definitionCN":"numerical 的另一种形式，今多用于计算机与键盘语境。"},{"word":"numerical","ipa":"/njuːˈmerɪkl/","tag":"adjective","definition":"relating to numbers or expressed by them. It is the general academic form.","definitionCN":"与数字有关或以数字表示的；是通用学术形式。"}]},{"heading":"NEAR MEANING","entries":[{"word":"quantitative","ipa":"/ˌkwɒntɪˈteɪtɪv/","tag":"research adjective","definition":"measured by amount rather than by quality. It describes a method, while numerical describes a form.","definitionCN":"以数量而非性质来衡量；描述方法，而 numerical 描述形式。"},{"word":"digital","ipa":"/ˈdɪdʒɪtl/","tag":"technology adjective","definition":"represented by discrete digits, especially in electronics. It is about encoding, not arithmetic.","definitionCN":"以离散数位表示，尤指电子领域；关乎编码，而非算术。"},{"word":"statistical","ipa":"/stəˈtɪstɪkl/","tag":"analysis adjective","definition":"relating to the collection and analysis of data. It uses numbers but adds inference.","definitionCN":"与数据收集和分析有关；使用数字，但增加了推断。"},{"word":"figurative","ipa":"/ˈfɪɡərətɪv/","tag":"language adjective","definition":"using figures of speech rather than literal numbers or plain meaning. It is the opposite direction from numerical.","definitionCN":"使用修辞格而非字面数字或本义；与 numerical 方向相反。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: Latin numerus, number, plus -ical, 'relating to'. Numerical simply means number-related.","cn":"只用真实成分：拉丁语 numerus“数字”，加 -ical“与……有关”。numerical 就是“与数字有关的”。"},"normal":[{"en":"Numerus is number; -ical is related to. Numerical equals number-related, nothing more.","cn":"numerus 是数字，-ical 是“与……有关”。numerical 就是“跟数字有关”，没有别的。"},{"en":"A numerical report shows a row of values instead of a sentence of praise.","cn":"数值报告给出一排数值，而不是一句赞美。"},{"en":"Numerical order is the shelf where 001 always comes before 002.","cn":"数字顺序就是 001 永远排在 002 前面的那种书架。"},{"en":"Numerical superiority counts people, not skill.","cn":"数量优势数的是人，不是本事。"},{"en":"In a workshop, numerical control means the tool reads numbers and moves.","cn":"在车间里，数控意味着刀具读了数字就移动。"}],"abstract":[{"en":"A numerical answer hides its units; without units, the number is only a shape.","cn":"数值答案把单位藏在背后；没有单位，数字只是一个形状。"},{"en":"What can be made numerical can be compared, and what can be compared can be managed.","cn":"能变成数值的东西就能比较，能比较的东西就能被管理。"},{"en":"The word promises precision, but an approximation done in numbers is still an approximation.","cn":"这个词许诺精确，但用数字做出来的近似终究还是近似。"}]},"examples":[{"en":"The committee asked for a numerical estimate, not a general impression of the crowd.","cn":"委员会要求给出人数估计，而不是对人群的笼统印象。"},{"en":"Numerical models disagree with each other mainly in how they treat clouds.","cn":"各数值模型之间的分歧主要在于如何处理云。"},{"en":"The old milling machine was converted to numerical control to cut curved parts.","cn":"那台旧铣床被改装成数控设备，用来切削曲面零件。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"numer（数字）+ ical（的）——满脑子都是数字，就是“数值的”。","word":"numerical"},"root":"源自拉丁语 numerus（数字、计数），经 numericus 与英语后缀 -al 构成，本义为“与数字有关的”；同根词还有 numeral、numerous、enumerate。","sensesIntro":{"en":"Eight senses of numerical. All point to numbers, but the numbers play different roles: they can be the subject, the form of expression, the value of a quantity, a sequence, a count of people, a method of calculation, a kind of data, or instructions for a machine.","cn":"numerical 的八个义项都指向数字，但数字扮演的角色不同：它可以是主题、表达形式、某量的大小、排列次序、人数、计算方法、数据种类，或机器的指令。"},"semanticMap":{"core":{"en":"CORE IMAGE: a wall of small boxes, each holding a single digit, with no adjectives anywhere.","cn":"核心意象：一面墙分成许多小格，每格只放一个数字，没有任何形容词。"},"chain":["LATIN NUMERUS = NUMBER","LATIN NUMERARE = TO COUNT","LATIN NUMERICUS = OF NUMBERS","ENGLISH NUMERICAL = RELATING TO NUMBERS","NUMBERS BECOME VALUES AND SEQUENCES","NUMBERS BECOME DATA, METHODS, AND INSTRUCTIONS"],"branches":[{"senses":"S1 · S2","en":"NUMBERS AS SUBJECT AND FORM: the domain of number, and the choice to express a fact in digits.","cn":"数字作主题与形式：数字的领域，以及选择用数位表达事实。"},{"senses":"S3 · S4","en":"NUMBERS AS VALUE AND ORDER: the size of a quantity, and the sequence on a shelf.","cn":"数字作值与序：量的大小，以及架上的排列次序。"},{"senses":"S5","en":"NUMBERS AS COUNT: superiority that comes from having more units than the opponent.","cn":"数字作计数：因单位多于对手而形成的优势。"},{"senses":"S6 · S7","en":"NUMBERS AS METHOD AND DATA: approximation by calculation, and measurements open to arithmetic.","cn":"数字作方法与数据：以计算求近似，以及可作算术处理的测量值。"},{"senses":"S8","en":"NUMBERS AS COMMAND: coordinates read by a machine tool.","cn":"数字作指令：机床读取的坐标。"}]},"affixes":{"intro":{"en":"Numerical is numerus plus the adjective suffix -ical. The family runs through number, numeral, numerate, and the prefix e- in enumerate.","cn":"numerical 是 numerus 加形容词后缀 -ical。词族包括 number、numeral、numerate，以及带前缀 e- 的 enumerate。"},"latinIntro":{"en":"The base is numerus, number or count, with the verb numerare and the adjective numerosus. Latin also used numerus for rhythm and rank.","cn":"词基是 numerus“数字、计数”，另有动词 numerare 与形容词 numerosus。拉丁语还用 numerus 指节奏与等级。"},"items":[{"word":"number","structure":"Latin numerus through French nombre","meaning":"a count, a symbol, or a quantity","meaningCN":"计数；数字符号；数量","example":"The number of applicants doubled in one year.","exampleCN":"申请人数量一年内翻了一倍。"},{"word":"numeral","structure":"Latin numeralis (of number) + English -al","meaning":"a symbol used to write a number","meaningCN":"书写数字所用的符号","example":"Roman numerals use letters instead of digits.","exampleCN":"罗马数字用字母而非数位。"},{"word":"numerical","structure":"Latin numericus + -al (relating to)","meaning":"relating to numbers or expressed by them","meaningCN":"与数字有关的，或以数字表示的","example":"The table gives numerical results for each trial.","exampleCN":"表格给出每次试验的数值结果。"},{"word":"numerically","structure":"numerical + -ly (adverb)","meaning":"in number or in numerical terms","meaningCN":"在数量上；以数值方式","example":"The two groups were numerically equal.","exampleCN":"两个群体在人数上相等。"},{"word":"numerate","structure":"Latin numerare (to count) + -ate","meaning":"able to work with numbers; also to count","meaningCN":"会算数的；也可作动词表示计数","example":"A numerate reader can check the totals quickly.","exampleCN":"会算数的读者能很快核对总数。"},{"word":"numerator","structure":"Latin numerator (counter) + -or","meaning":"the number above the line in a fraction","meaningCN":"分数线上方的数；分子","example":"In three quarters, three is the numerator.","exampleCN":"在四分之三里，三是分子。"},{"word":"enumerate","structure":"e- (out) + numerare (count) + -ate","meaning":"to list items one by one","meaningCN":"逐项列出；列举","example":"The report enumerates every source of error.","exampleCN":"报告逐项列出了每一种误差来源。"},{"word":"numerous","structure":"Latin numerosus (full of number) + -ous","meaning":"many in number","meaningCN":"数量众多的","example":"Numerous studies report the same pattern.","exampleCN":"众多研究报告了同样的模式。"},{"word":"innumerable","structure":"in- (not) + numerable (countable)","meaning":"too many to be counted","meaningCN":"多得无法计数的","example":"The storm left innumerable branches on the road.","exampleCN":"暴风雨在路面上留下数不清的树枝。"}],"latinEntries":[{"word":"numerus","structure":"Latin noun","meaning":"number, count, measure, rank","meaningCN":"数字；计数；度量；等级"},{"word":"numerare","structure":"Latin verb","meaning":"to count, to reckon","meaningCN":"计数；计算"},{"word":"numericus","structure":"Late Latin adjective","meaning":"concerned with numbers","meaningCN":"与数字有关的"}]}},{"word":"objectively","ipa_uk":"/ɒbˈdʒektɪvli/","ipa_us":"/ɑːbˈdʒektɪvli/","definition_zh":"客观地；不带个人偏见地；依据事实地；从外部看地","definition_en":"in a way based on observable facts rather than personal feelings, opinions, or interests","core_image":"一台摄像机架在房间角落，不参与对话，只把每个人说的话原样录下来。","scene":"两位评审先各自独立打分，再对照结果，避免互相影响。Each reviewer scored the papers objectively before comparing notes.","sceneCN":"这里 objectively 是“不带个人偏见地、依据可观察事实地”（第 1 个义项）；句意：每位评审在对照之前都客观地给论文打分。","pos":[{"tag":"adv.","zh":"客观地；不带个人偏见地；依据事实地；从外部看地"}],"collocations":[{"phrase":"objectively true","zh":"客观上成立"},{"phrase":"objectively measurable","zh":"可客观测量的"},{"phrase":"objectively assessed","zh":"经客观评估的"},{"phrase":"objectively speaking","zh":"客观地说"},{"phrase":"view something objectively","zh":"客观地看待某事"},{"phrase":"objectively verifiable","zh":"可客观验证的"}],"forms":[{"label":"原级（副词）","form":"objectively"},{"label":"比较级（用 more）","form":"more objectively"},{"label":"最高级（用 most）","form":"most objectively"},{"label":"形容词形式","form":"objective"},{"label":"名词形式","form":"objectivity"}],"derivatives":[{"word":"object","pos":"n./v.","zh":"物体；对象；反对"},{"word":"objective","pos":"adj./n.","zh":"客观的；目标"},{"word":"objectivity","pos":"n.","zh":"客观性；客观态度"},{"word":"objection","pos":"n.","zh":"反对；异议"}],"senses":[{"no":"01","title":"Without personal bias","titleCN":"不带偏见：把自己的好恶放到一边","definition":"in a manner free from personal preference, prejudice, or interest","definitionCN":"不带个人偏好、成见或利益的方式","example":"The reviewer tried to judge the manuscript objectively, though she disliked its topic.","exampleCN":"尽管不喜欢这个题目，评审仍努力客观地评判稿件。","why":"Objectivity begins with separating the observer's feelings from the judgement; the adverb says the separation was attempted.","whyCN":"客观始于把观察者的感受与判断分开；这个副词表示这种分离被付诸实践。"},{"no":"02","title":"On the evidence available","titleCN":"依据事实：让证据先说话","definition":"by relying on evidence that others can examine, rather than on private impressions","definitionCN":"依据他人也能查验的证据，而非私人印象","example":"The damage was assessed objectively from photographs and measurements.","exampleCN":"损失是依据照片与测量数据客观评估的。","why":"A judgement is objective when it can be checked: the evidence stands outside the judge and can be produced again for someone else.","whyCN":"当判断可以被复核时，它就是客观的：证据在判断者之外，可以再拿出来给别人看。"},{"no":"03","title":"Open to measurement","titleCN":"可客观测量：尺子和仪器说了算","definition":"in a way that can be measured or counted by instruments independent of the observer","definitionCN":"可由独立于观察者的仪器测量或计数的方式","example":"Improvement was measured objectively as the number of errors per page.","exampleCN":"进步以每页错误数这一指标被客观测量。","why":"Measurement turns a claim into a number that another lab can repeat; the adverb marks that the number, not the impression, carries the argument.","whyCN":"测量把主张变成另一个实验室也能复现的数字；这个副词标明是数字而非印象在支撑论证。"},{"no":"04","title":"True regardless of opinion","titleCN":"客观上成立：谁怎么看都改变不了","definition":"in a way that holds independently of what anyone believes or feels","definitionCN":"不以任何人的信念或感受为转移地成立","example":"The task was objectively harder, even if the volunteers enjoyed it more.","exampleCN":"这项任务客观上更难，即使志愿者更喜欢它。","why":"This sense asserts independence from belief: the fact would remain what it is even if every observer changed their mind.","whyCN":"这一义项主张独立于信念：即使所有观察者都改变想法，事实仍会是那样。"},{"no":"05","title":"Seen from outside","titleCN":"从外部看：把自己当成旁观者","definition":"by viewing a situation from an external standpoint rather than from inside one's own experience","definitionCN":"从外部立场而非自身经验内部来看待情境","example":"She described her own illness objectively, as a case rather than as her life.","exampleCN":"她客观地描述自己的病，把它当成病例而不是自己的人生。","why":"The adverb can move the viewpoint: to see oneself objectively is to occupy the position of a stranger looking at the same facts.","whyCN":"这个副词可以移动视点：客观地看自己，就是站到一个陌生人看同样事实的位置上。"},{"no":"06","title":"Not merely a matter of taste","titleCN":"客观而言：不是“我觉得”，而是“确实”","definition":"used to mark a judgement as factual rather than a matter of personal taste","definitionCN":"用来标明某判断属于事实，而非个人口味","example":"Objectively, the second route is shorter, whatever the scenery is like.","exampleCN":"客观而言，第二条路线更短，不管风景如何。","why":"In conversation the adverb is a signal: it invites the listener to separate the measurable part of a claim from the part that is opinion.","whyCN":"在对话中，这个副词是一种信号：它请听者把主张中可测量的部分与属于意见的部分分开。"},{"no":"07","title":"Even-handedly","titleCN":"不偏不倚：给双方同样的尺子","definition":"in a fair manner that applies the same standard to all parties","definitionCN":"对各方适用同一标准的公平方式","example":"The chair summed up both proposals objectively before calling the vote.","exampleCN":"主席在表决前不偏不倚地总结了双方提案。","why":"Fairness is objectivity applied between people: the same rule is used on both sides, so no one is measured with a shorter ruler.","whyCN":"公平是用于人际之间的客观：同一条规则施于双方，没人被用短尺衡量。"},{"no":"08","title":"By external review","titleCN":"经外部评审：让局外人来核","definition":"by means of review conducted by people or methods outside the original group","definitionCN":"由原群体之外的人或方法进行审查的方式","example":"The safety record was objectively reviewed by an independent laboratory.","exampleCN":"安全记录由一家独立实验室作了客观审查。","why":"Institutions secure objectivity by moving the judgement outside: the reviewer has no stake, and the method is published for scrutiny.","whyCN":"机构通过把判断移到外部来确保客观：评审者无利害关系，方法也公开可供审视。"}],"etymology":{"intro":{"en":"Objectively is objective plus -ly. Objective comes from Latin objectum, 'something thrown before', from obicere: ob- 'against' plus iacere 'to throw'.","cn":"objectively 是 objective 加 -ly。objective 来自拉丁语 objectum“被抛到面前的东西”，出自 obicere：ob-“对着”加 iacere“投掷”。"},"items":[{"era":"LATIN iacere","en":"Iacere meant to throw or cast. It is the root of project, reject, inject, and jet, all involving something sent in a direction.","cn":"iacere 意为投、掷。它是 project、reject、inject、jet 的词根，这些词都含“把某物朝某方向送出”的意思。"},{"era":"LATIN obicere","en":"Ob- 'against, before' plus iacere gave obicere, to throw something in front of someone, hence to present or to oppose.","cn":"ob-“对着、在前”加 iacere 得到 obicere：把东西抛到某人面前，因而表示“呈现”或“反对”。"},{"era":"LATIN objectum","en":"Objectum was the thing thrown before the mind or the eyes: an object of thought, of sight, or of an argument.","cn":"objectum 是被抛到心智或眼睛之前的东西：思想的对象、视觉的对象，或争论的议题。"},{"era":"MEDIEVAL LATIN objectivus","en":"Scholastic Latin used objectivus for what exists in the mind as an object of thought, as opposed to what exists in itself.","cn":"经院拉丁语用 objectivus 指“作为思想对象存在于心智中的”，与“自身独立存在”的相对。"},{"era":"ENGLISH 17c","en":"English objective reversed the emphasis: it came to mean the thing outside the mind, and hence a judgement free of private feeling.","cn":"英语 objective 反转了侧重：它开始指心智之外的事物，因而指不带私人感受的判断。"},{"era":"MODERN ENGLISH","en":"Objectively then developed its adverb senses: by evidence, by measurement, from outside, and by independent review.","cn":"objectively 随后发展出副词义项：依据证据、依据测量、从外部看，以及经独立评审。"}]},"similar":{"note":{"en":"The first group is the object family; the second compares adverbs for judging without personal colour.","cn":"第一组是 object 词族；第二组比较几个表示“不带个人色彩地判断”的副词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"object","ipa":"/ˈɒbdʒekt/","tag":"noun","definition":"a thing that can be seen or touched, or the thing a thought or action is directed at. As a verb it means to oppose.","definitionCN":"可见可触的物体，或思想与行动指向的对象；作动词时表示反对。"},{"word":"objective","ipa":"/ɒbˈdʒektɪv/","tag":"adjective or noun","definition":"based on facts rather than feelings; as a noun, a goal to be reached.","definitionCN":"依据事实而非感受的；作名词时指目标。"},{"word":"objectivity","ipa":"/ˌɒbdʒekˈtɪvəti/","tag":"quality noun","definition":"the quality of judging without personal bias.","definitionCN":"不带个人偏见地判断的品质。"},{"word":"objectively","ipa":"/ɒbˈdʒektɪvli/","tag":"adverb","definition":"in a factual, unbiased manner.","definitionCN":"以依据事实、无偏见的方式。"}]},{"heading":"NEAR MEANING","entries":[{"word":"impartially","ipa":"/ɪmˈpɑːʃəli/","tag":"fairness adverb","definition":"without favouring one party over another. It concerns people and sides, not measurement.","definitionCN":"不偏袒任何一方；关乎人与阵营，而非测量。"},{"word":"neutrally","ipa":"/ˈnjuːtrəli/","tag":"stance adverb","definition":"without taking either side. It can describe a policy of staying out.","definitionCN":"不站任何一边；可描述置身事外的政策。"},{"word":"factually","ipa":"/ˈfæktʃuəli/","tag":"evidence adverb","definition":"with attention to facts. It checks accuracy rather than freedom from bias.","definitionCN":"着眼于事实；检验准确与否，而非是否有偏见。"},{"word":"rationally","ipa":"/ˈræʃənəli/","tag":"reason adverb","definition":"by reasoning rather than emotion. One can reason rationally from biased premises.","definitionCN":"凭推理而非情绪；但人可以从不偏的前提理性推理，也可以从有偏的前提理性推理。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: ob- 'before' plus iacere 'throw', then -ive and -ly. The objective is what is thrown in front of everyone to be seen.","cn":"只用真实成分：ob-“在前”加 iacere“投掷”，再加 -ive 与 -ly。objective 就是被抛到所有人面前、供人看见的东西。"},"normal":[{"en":"Thrown in front: the evidence lies on the table where everyone can see it.","cn":"抛到前面：证据摊在桌上，谁都能看见。"},{"en":"A camera in the corner records without having an opinion.","cn":"角落里的摄像机只记录，不发表意见。"},{"en":"Objectively measurable means a second lab can get the same number.","cn":"可客观测量，意味着第二个实验室也能得到同一个数。"},{"en":"Two reviewers score separately so that the first voice cannot lead the second.","cn":"两位评审分开打分，好让第一个声音带不走第二个。"},{"en":"Objective and objection share a root: both put something in front of you.","cn":"objective 与 objection 同根：两者都把东西摆到你面前。"}],"abstract":[{"en":"Objectivity is not the absence of a viewpoint but the willingness to show where the viewpoint stands.","cn":"客观不是没有视角，而是愿意把视角的位置摆出来。"},{"en":"Every measuring instrument encodes a decision about what counts, and that decision was made by someone.","cn":"每件测量仪器都编码了一个“什么才算数”的决定，而这个决定是某个人做的。"},{"en":"To see oneself objectively is to lend one's own life to a stranger for a moment, then take it back.","cn":"客观地看自己，就是把自己的生活暂借给一个陌生人，然后再收回来。"}]},"examples":[{"en":"The panel could not judge the design objectively until it agreed on the criteria.","cn":"在就标准达成一致之前，评审组无法客观评判这项设计。"},{"en":"Objectively, the old bridge carries less traffic than the new one, whatever residents remember.","cn":"客观而言，旧桥承载的车流少于新桥，不管居民记得什么。"},{"en":"The experiment was objectively reviewed by a laboratory that had no funding from the company.","cn":"该实验由一家未接受该公司资助的实验室作了客观审查。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"object（对象）+ ively——把对象摆到面前看，不掺自己的情绪，就是客观地。","word":"objectively"},"root":"由 objective（客观的）加 -ly 构成；objective 源自拉丁语 objectum“被抛到面前之物”，出自 obicere：ob-“对着、在前”加 iacere“投掷”，故本义为“摆在面前供众人审视”，引申为“不掺私情的判断”。","sensesIntro":{"en":"Eight senses of objectively. They share one move: the judgement is placed outside the judge. It can be outside the judge's feelings, outside the judge's instruments, outside the judge's own experience, or outside the judge's institution.","cn":"objectively 的八个义项共享一个动作：把判断移到判断者之外。它可以移出判断者的情绪、仪器、自身经验，或所属机构之外。"},"semanticMap":{"core":{"en":"CORE IMAGE: a camera fixed in the corner of a room, recording every voice and taking no part in the conversation.","cn":"核心意象：固定在房间角落的摄像机，录下每个声音，却不参与对话。"},"chain":["LATIN IACERE = TO THROW","LATIN OBICERE = TO THROW BEFORE","LATIN OBJECTUM = THE THING SET BEFORE THE MIND","MEDIEVAL OBJECTIVUS = EXISTING AS AN OBJECT OF THOUGHT","ENGLISH OBJECTIVE = OUTSIDE THE MIND, FACTUAL","OBJECTIVELY = WITH THE JUDGEMENT PLACED OUTSIDE THE JUDGE"],"branches":[{"senses":"S1 · S2","en":"OUTSIDE FEELING AND PRIVATE IMPRESSION: bias set aside, evidence left on the table.","cn":"移出情绪与私人印象：搁下偏见，把证据留在桌上。"},{"senses":"S3 · S8","en":"OUTSIDE THE OBSERVER: measurement by instrument and review by an independent body.","cn":"移出观察者：以仪器测量，由独立机构审查。"},{"senses":"S4 · S6","en":"OUTSIDE OPINION: a fact that survives any change of taste, marked in speech as 'not just my view'.","cn":"移出意见：不随口味改变的事实，并在言语中标为“不只是我的看法”。"},{"senses":"S5","en":"OUTSIDE ONESELF: one's own life described as a case seen from a stranger's chair.","cn":"移出自身：把自己的生活当成从陌生人椅子上看到的病例。"},{"senses":"S7","en":"OUTSIDE THE PARTY: one standard applied to both sides of an argument.","cn":"移出阵营：用同一把尺子量争论双方。"}]},"affixes":{"intro":{"en":"Objectively is objective plus -ly. Objective is object plus -ive, and object goes back to obicere, to throw before. The family also gives objection and objectivity.","cn":"objectively 是 objective 加 -ly。objective 是 object 加 -ive，而 object 上溯 obicere“抛到面前”。词族还有 objection 与 objectivity。"},"latinIntro":{"en":"The base is iacere, to throw, with the prefixed verb obicere and the noun objectum. The same verb underlies project, reject, inject, and subject.","cn":"词基是 iacere“投掷”，加前缀的动词 obicere 与名词 objectum。同一动词还构成 project、reject、inject、subject。"},"items":[{"word":"object","structure":"Latin objectum (thing thrown before) + English -ect","meaning":"a thing perceived or aimed at; as a verb, to oppose","meaningCN":"被感知或指向的对象；作动词表示反对","example":"The object on the table was a sealed box.","exampleCN":"桌上的物体是一个封好的盒子。"},{"word":"objective","structure":"object + -ive (adjective)","meaning":"based on external facts; as a noun, an aim","meaningCN":"依据外部事实的；作名词指目标","example":"The report gives an objective account of the dispute.","exampleCN":"报告对争端作了客观叙述。"},{"word":"objectively","structure":"objective + -ly (adverb)","meaning":"in an unbiased, evidence-based way","meaningCN":"以无偏见、依据证据的方式","example":"The two samples were objectively compared.","exampleCN":"两个样本被客观地加以比较。"},{"word":"objectivity","structure":"objective + -ity (quality noun)","meaning":"the quality of being free from personal bias","meaningCN":"不受个人偏见影响的品质；客观性","example":"Objectivity requires that the method be public.","exampleCN":"客观性要求方法公开。"},{"word":"objection","structure":"ob- (against) + iacere (throw) + -ion","meaning":"a statement thrown against a proposal","meaningCN":"对提案提出的反对意见","example":"The lawyer raised an objection to the question.","exampleCN":"律师对该问题提出异议。"},{"word":"project","structure":"pro- (forward) + iacere (throw)","meaning":"to cast forward, hence a planned undertaking","meaningCN":"向前投出，因而指计划、项目","example":"The city approved the housing project.","exampleCN":"市里批准了这个住房项目。"},{"word":"reject","structure":"re- (back) + iacere (throw)","meaning":"to throw back, hence to refuse","meaningCN":"掷回，因而表示拒绝","example":"The committee rejected the first draft.","exampleCN":"委员会否决了初稿。"},{"word":"inject","structure":"in- (into) + iacere (throw)","meaning":"to throw something in","meaningCN":"投入；注入","example":"The nurse injected the vaccine into the arm.","exampleCN":"护士把疫苗注入手臂。"},{"word":"subject","structure":"sub- (under) + iacere (throw)","meaning":"thrown under, hence placed under control or discussion","meaningCN":"置于其下，因而指受支配或受讨论的对象","example":"The topic became the subject of a long inquiry.","exampleCN":"这个话题成了一场漫长调查的对象。"}],"latinEntries":[{"word":"iacere","structure":"Latin verb","meaning":"to throw, cast, lay","meaningCN":"投；掷；放置"},{"word":"obicere","structure":"ob- (before, against) + iacere","meaning":"to throw before, to present, to oppose","meaningCN":"抛到面前；呈现；反对"},{"word":"objectum","structure":"Latin noun","meaning":"a thing set before the mind or eyes","meaningCN":"摆在心智或眼前之物"}]}},{"word":"observation","ipa_uk":"/ˌɒbzəˈveɪʃn/","ipa_us":"/ˌɑːbzərˈveɪʃn/","definition_zh":"观察；观测；观察结果；评论；（对规则的）遵守","definition_en":"the act of watching something carefully, a recorded result of such watching, or a remark based on it","core_image":"一个人站在窗前，手里拿着本子，把鸟落下的时间一秒一秒写下来。","scene":"医生让病人先留院一晚，第二天早上再看检查数据。The patient stayed in the hospital for a night of observation.","sceneCN":"这里 observation 是“医学上的观察期、留观”（第 4 个义项）；句意：病人留院接受一晚的观察。","pos":[{"tag":"n.","zh":"观察；观测；观察结果；评论；遵守"}],"collocations":[{"phrase":"under observation","zh":"处于观察中；受观察"},{"phrase":"make an observation","zh":"发表评论；提出看法"},{"phrase":"direct observation","zh":"直接观察"},{"phrase":"observation data","zh":"观测数据"},{"phrase":"a period of observation","zh":"观察期"},{"phrase":"observation of the rules","zh":"对规则的遵守"},{"phrase":"participant observation","zh":"参与式观察"}],"forms":[{"label":"复数（名词）","form":"observations"},{"label":"动词形式","form":"observe"},{"label":"形容词形式","form":"observational"},{"label":"施动者名词","form":"observer"}],"derivatives":[{"word":"observe","pos":"v.","zh":"观察；注意到；遵守"},{"word":"observer","pos":"n.","zh":"观察者；观察员"},{"word":"observant","pos":"adj.","zh":"善于观察的；遵守的"},{"word":"observable","pos":"adj.","zh":"可观察到的；可遵守的"}],"senses":[{"no":"01","title":"Watching with attention","titleCN":"观察：有目的地看","definition":"the act of watching someone or something closely and with attention","definitionCN":"密切而专注地注视某人或某事的行为","example":"Careful observation showed that the birds returned at the same hour each day.","exampleCN":"仔细观察显示，这些鸟每天在同一时刻返回。","why":"Observation is not passive seeing: the watcher has chosen an object and a purpose, so attention is the defining element.","whyCN":"观察不是被动地看见：观察者已经选定了对象与目的，因此“专注”才是定义性的要素。"},{"no":"02","title":"A recorded result","titleCN":"观察结果：本子上那行字","definition":"a piece of information obtained by watching and often written down for later use","definitionCN":"通过观察获得、常被记录下来备用的信息","example":"The notebook contained observations from six mornings at the lake.","exampleCN":"笔记本里记着六个早晨在湖边的观察结果。","why":"Once written, the act becomes a fact others can read; the word then names the record rather than the watching.","whyCN":"一旦写下来，行为就变成别人可读的事实；此时这个词命名的是记录，而不是“看”本身。"},{"no":"03","title":"A remark drawn from noticing","titleCN":"评论：看见了，就说一句","definition":"a spoken or written remark based on something noticed","definitionCN":"基于所注意到的事情而作出的口头或书面评论","example":"His observation that the room felt colder was correct.","exampleCN":"他说房间变冷了，这个观察是对的。","why":"The sense shifts from the eye to the mouth: a remark is called an observation when it reports a noticed fact rather than an opinion.","whyCN":"这一义项从眼睛移到嘴：当一句话报告的是被注意到的事实而非意见时，它就被称作 observation。"},{"no":"04","title":"A medical watch","titleCN":"留观：先看着，等数据说话","definition":"a period during which a patient is watched in hospital before a decision is made","definitionCN":"病人留院接受看护、等待作出决定的一段时间","example":"She was kept in observation overnight after the fall.","exampleCN":"摔倒后她被留院观察了一夜。","why":"Medicine uses observation as a treatment stage: when the diagnosis is still open, watching is safer than acting.","whyCN":"医学把观察当作一个治疗阶段：诊断尚未确定时，看着比动手更安全。"},{"no":"05","title":"Keeping a rule","titleCN":"遵守：把规定看在眼里并照做","definition":"the keeping or honouring of a law, custom, or religious practice","definitionCN":"遵守或尊重法律、习俗或宗教实践","example":"Observation of the Sabbath was strict in that community.","exampleCN":"那个社群对安息日的遵守很严格。","why":"The older sense of observare is to heed or keep; the same verb that means watch over also means keep faith with a rule.","whyCN":"observare 更早的含义是“留意、守护”；同一个既表示“看护”又表示“守信于规则”的动词。"},{"no":"06","title":"A post for watching","titleCN":"观察位：专门用来盯的地方","definition":"a place, especially a military one, set up for watching an area","definitionCN":"为监视某一区域而设置的场所，尤指军事用途","example":"The soldiers held the observation post on the ridge through the night.","exampleCN":"士兵们整夜守住山脊上的观察哨。","why":"The act needs a place; when watching is continuous, the place itself takes the name and becomes part of the operation.","whyCN":"观察需要地点；当观察持续进行时，地点本身也取了这个名字，成为行动的一部分。"},{"no":"07","title":"Studying from inside a group","titleCN":"参与式观察：进去，同时记下来","definition":"a research method in which the researcher joins a group and records its life while taking part in it","definitionCN":"研究者加入某群体、在参与其生活的同时作记录的研究方法","example":"Her participant observation of the night market lasted a full year.","exampleCN":"她对夜市的参与式观察持续了整整一年。","why":"The method accepts a tension: to see ordinary life closely one must enter it, yet entering changes what is being observed.","whyCN":"这种方法接受一种张力：要贴近看日常生活就必须进去，可一旦进去，被观察的对象也变了。"},{"no":"08","title":"Measuring the sky","titleCN":"天文观测：把望远镜对准天上","definition":"the systematic recording of celestial objects and events with instruments","definitionCN":"用仪器对天体与天象作系统记录","example":"The observation of the eclipse required clear skies and an exact location.","exampleCN":"观测这次日食需要晴朗天空和精确地点。","why":"Astronomy turns observation into data: the eye is replaced by a detector, and the record must state time, place, and instrument.","whyCN":"天文学把观察变成数据：眼睛被探测器取代，记录必须写明时间、地点与仪器。"}],"etymology":{"intro":{"en":"Observation comes from Latin observatio, a watching or a heed, from observare: ob- 'over, before' plus servare 'to keep, watch over'. Servare also gives preserve, reserve, and conserve.","cn":"observation 来自拉丁语 observatio“看护、留意”，出自 observare：ob-“在上、在前”加 servare“守护、留意”。servare 还给出 preserve、reserve、conserve。"},"items":[{"era":"LATIN servare","en":"Servare meant to keep, guard, or preserve. The idea of keeping is older than the idea of looking.","cn":"servare 意为保持、守护、保存。“守”的观念比“看”的观念更早。"},{"era":"LATIN observare","en":"Ob- added the sense of direction or attention: to watch over, to heed, to keep a rule, and to observe signs.","cn":"ob- 增加了方向与注意的含义：看护、留意、遵守规则，以及观察征兆。"},{"era":"LATIN observatio","en":"The noun covered watching, noting, and also compliance with a custom or a law.","cn":"该名词涵盖看护、记录，也涵盖对习俗或法律的遵守。"},{"era":"FRENCH observation","en":"French kept both the watching sense and the remark sense, and English borrowed both in the 14th century.","cn":"法语同时保留了“观察”与“评论”两义，英语于 14 世纪把两者一并借入。"},{"era":"ENGLISH 14c-17c","en":"English observation grew in science and navigation, where watching had to be recorded with time and place.","cn":"英语 observation 在科学与航海领域壮大，那里的观察必须连同时间与地点一起记录。"},{"era":"MODERN ENGLISH","en":"The 19th and 20th centuries added medical observation, participant observation, and instrument-based astronomical observation.","cn":"19 与 20 世纪增加了医学留观、参与式观察，以及依靠仪器的天文观测。"}]},"similar":{"note":{"en":"The first group is the observe family; the second compares ways of gaining knowledge by watching, checking, or testing.","cn":"第一组是 observe 词族；第二组比较通过观看、核查或检验获取知识的几种方式。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"observe","ipa":"/əˈzɜːv/","tag":"verb","definition":"to watch carefully, to notice, or to keep a rule. It names the action behind observation.","definitionCN":"仔细观察、注意到，或遵守规则；命名的是 observation 背后的动作。"},{"word":"observer","ipa":"/əbˈzɜːvə/","tag":"person noun","definition":"a person who watches, especially one sent to report on an event.","definitionCN":"观察的人，尤指被派去报道某一事件的人。"},{"word":"observant","ipa":"/əbˈzɜːvənt/","tag":"adjective","definition":"quick to notice things; also careful to keep a rule.","definitionCN":"善于注意细节的；也指谨慎守规的。"},{"word":"observance","ipa":"/əbˈzɜːvəns/","tag":"noun","definition":"the keeping of a law, rite, or custom. It is the 'compliance' sense without the scientific one.","definitionCN":"对法律、仪式或习俗的遵守；只有“遵从”义，没有科学观察义。"}]},{"heading":"NEAR MEANING","entries":[{"word":"watching","ipa":"/ˈwɒtʃɪŋ/","tag":"activity noun","definition":"looking at something over time, often without a formal purpose. Observation adds method.","definitionCN":"持续地看，常无正式目的；observation 则增加了方法。"},{"word":"monitoring","ipa":"/ˈmɒnɪtərɪŋ/","tag":"technical noun","definition":"continuous checking by instruments or staff, usually against limits. It is observation with a threshold.","definitionCN":"用仪器或人员持续核查，通常对照限值；是有阈值的观察。"},{"word":"measurement","ipa":"/ˈmeʒəmənt/","tag":"quantitative noun","definition":"the assignment of a number to a property. It turns observation into quantity.","definitionCN":"给性质赋予数值；它把观察变成数量。"},{"word":"remark","ipa":"/rɪˈmɑːk/","tag":"speech noun","definition":"something said briefly. It need not be based on careful watching.","definitionCN":"简短说出的话；不必基于仔细的观察。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: ob- 'over' plus servare 'keep'. Observation is keeping watch, and keeping a rule.","cn":"只用真实成分：ob-“在上”加 servare“守护”。observation 就是守望着，也是守着规则。"},"normal":[{"en":"Observe means both to watch and to keep: the same act of holding something in view.","cn":"observe 既表示“看”，也表示“守”：都是把某物保持在视野里。"},{"en":"An observation notebook is a watch that leaves a mark.","cn":"观察笔记本就是一只会留下痕迹的表。"},{"en":"In hospital, observation is a room where time does the testing.","cn":"在医院，observation 是一间让时间来检验的病房。"},{"en":"An observation post is the act of watching with a fixed address.","cn":"观察哨就是有了固定地址的“看”。"},{"en":"Astronomers write down three things: what, when, and with which instrument.","cn":"天文学家记三件事：看到了什么、什么时候、用什么仪器。"}],"abstract":[{"en":"Observation never arrives pure; the choice of what to watch is already a theory about what matters.","cn":"观察从不以纯粹状态到来；选择看什么，本身已是关于“什么重要”的理论。"},{"en":"The same verb means to watch and to obey, as if attention and loyalty came from one root.","cn":"同一个动词既表示观看又表示服从，仿佛注意与忠诚出自同一根。"},{"en":"To observe a group closely is to change it; the observer is always part of the observed world.","cn":"近距离观察一个群体就会改变它；观察者永远是被观察世界的一部分。"}]},"examples":[{"en":"The ornithologist's observation of the nest lasted from dawn until the chicks fledged.","cn":"这位鸟类学家对鸟巢的观察从黎明持续到雏鸟长出飞羽。"},{"en":"After the head injury, the patient stayed under observation for twenty-four hours.","cn":"头部受伤后，病人留院观察了二十四小时。"},{"en":"Her observation that the machine ran quieter after warming up turned out to be important.","cn":"她观察到机器预热后运转更安静，后来证明这一点很重要。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"observe（观察）+ ation（名词）——看得很仔细，还记下来，就是观察、观测。","word":"observation"},"root":"源自拉丁语 observatio（看护、留意、遵从），出自 observare：ob-“在上、在前”加 servare“守护、保持”。同一词根兼有“看”与“守”两面，因此既指观察、观测，也指对规则、习俗的遵守。","sensesIntro":{"en":"Eight senses of observation, all descended from one act of keeping watch. The watch can be scientific, medical, military, or social; its product can be a record, a remark, a data set, or a habit of obeying.","cn":"observation 的八个义项都源自同一个“守望”动作。守望可以是科学的、医学的、军事的或社会的；其产物可以是记录、评论、数据集，或遵守的习惯。"},"semanticMap":{"core":{"en":"CORE IMAGE: a person at a window with a notebook, writing down the exact second a bird lands.","cn":"核心意象：窗边的人拿着本子，记下鸟落下的那一秒。"},"chain":["LATIN SERVARE = TO KEEP, GUARD","LATIN OBSERVARE = TO WATCH OVER, HEED","LATIN OBSERVATIO = A WATCHING, A HEEDING","FRENCH OBSERVATION = WATCHING AND REMARK","ENGLISH OBSERVATION = CAREFUL WATCHING","ITS RECORD, ITS REMARK, ITS POST, ITS METHOD"],"branches":[{"senses":"S1 · S2","en":"THE ACT AND ITS RECORD: watching with purpose, and the line written down afterwards.","cn":"行为与记录：有目的地看，以及随后写下的那一行。"},{"senses":"S3 · S5","en":"WORD AND RULE: a remark drawn from noticing, and the keeping of a law or custom.","cn":"言语与规则：由注意得出的评论，以及对法律或习俗的遵守。"},{"senses":"S4","en":"MEDICAL WAITING: a patient watched until the evidence becomes clear.","cn":"医学等待：病人被观察到证据明朗为止。"},{"senses":"S6 · S7","en":"PLACE AND METHOD: a post built for watching, and a researcher watching from inside a group.","cn":"地点与方法：为观察而建的哨位，以及研究者从群体内部观察。"},{"senses":"S8","en":"INSTRUMENTAL WATCHING: the sky recorded with time, place, and detector.","cn":"仪器化观察：连同时间、地点与探测器一起记录天空。"}]},"affixes":{"intro":{"en":"Observation is observe plus -ation, the action-noun suffix. The family adds -er for the person, -ant for the habit, -ance for the keeping of a rule, and -able for what can be seen.","cn":"observation 是 observe 加 -ation（动作名词后缀）。词族用 -er 表示人，-ant 表示习性，-ance 表示对规则的遵守，-able 表示可被看见。"},"latinIntro":{"en":"The base is servare, to keep or guard, with ob- adding the direction of attention. Related Latin words give preserve, reserve, conserve, and servant.","cn":"词基是 servare“保持、守护”，ob- 增加注意的方向。相关拉丁词给出 preserve、reserve、conserve、servant。"},"items":[{"word":"observe","structure":"Latin observare (watch over) + English -e","meaning":"to watch closely, notice, or keep a rule","meaningCN":"仔细观察；注意到；遵守","example":"Scientists observe the same plot every spring.","exampleCN":"科学家每年春天观察同一块样地。"},{"word":"observation","structure":"observe + -ation (action noun)","meaning":"the act, result, or remark of watching","meaningCN":"观察的行为、结果或评论","example":"His observation was recorded in the margin.","exampleCN":"他的观察被记在页边。"},{"word":"observer","structure":"observe + -er (agent noun)","meaning":"one who watches or reports","meaningCN":"观察者；观察员","example":"An observer sat at the back of the meeting.","exampleCN":"一名观察员坐在会议后排。"},{"word":"observant","structure":"observe + -ant (adjective)","meaning":"quick to notice; careful to comply","meaningCN":"善于察觉的；谨慎遵守的","example":"An observant reader will spot the repeated date.","exampleCN":"细心的读者会注意到重复出现的日期。"},{"word":"observance","structure":"observant + -ce (state noun)","meaning":"the keeping of a law, rite, or custom","meaningCN":"对法律、仪式或习俗的遵守","example":"Observance of the treaty was monitored by neutrals.","exampleCN":"条约的遵守情况由中立国监督。"},{"word":"observable","structure":"observe + -able (able to be)","meaning":"able to be seen or noticed","meaningCN":"可观察到的","example":"The effect is observable only at low temperatures.","exampleCN":"这一效应只在低温下可观察到。"},{"word":"observatory","structure":"observe + -atory (place)","meaning":"a place built for watching the sky or nature","meaningCN":"为观测天空或自然而建的场所；天文台","example":"The observatory opens to the public on Fridays.","exampleCN":"这座天文台周五向公众开放。"},{"word":"preserve","structure":"prae- (before) + servare (keep)","meaning":"to keep something safe from harm or change","meaningCN":"保护某物免受损害或改变；保存","example":"The salt preserves the fish for the winter.","exampleCN":"盐把鱼保存过冬。"},{"word":"reserve","structure":"re- (back) + servare (keep)","meaning":"to keep back for later use","meaningCN":"留作后用；保留","example":"They reserved two seats near the window.","exampleCN":"他们预留了两个靠窗座位。"},{"word":"conserve","structure":"con- (together, wholly) + servare (keep)","meaning":"to keep from being lost or wasted","meaningCN":"节约；保护以免损耗","example":"The town conserves water during dry summers.","exampleCN":"这个镇在干旱夏季节约用水。"}],"latinEntries":[{"word":"servare","structure":"Latin verb","meaning":"to keep, guard, preserve","meaningCN":"保持；守护；保存"},{"word":"observare","structure":"ob- (over, before) + servare","meaning":"to watch over, heed, comply with","meaningCN":"看护；留意；遵从"},{"word":"observatio","structure":"Latin noun","meaning":"a watching, a remark, a compliance","meaningCN":"观察；评论；遵从"}]}},{"word":"observational","ipa_uk":"/ˌɒbzəˈveɪʃənl/","ipa_us":"/ˌɑːbzərˈveɪʃənl/","definition_zh":"观察的；观测的；观察性的；依据观察的","definition_en":"relating to or based on observation, especially in research that watches without intervening","core_image":"一间教室的后排，研究者坐在椅子上不发一言，只在表格里勾画孩子们每一次举手。","scene":"论文的方法部分写明，这项研究不设对照组，也不干预受试者的日常活动。The study is observational: there is no control group and no interference.","sceneCN":"这里 observational 是“以观察为方法、不施加干预的”（第 2 个义项）；句意：这项研究属于观察性研究，没有对照组，也不施加干预。","pos":[{"tag":"adj.","zh":"观察的；观测的；观察性的；依据观察的"}],"collocations":[{"phrase":"an observational study","zh":"观察性研究"},{"phrase":"observational data","zh":"观测数据"},{"phrase":"observational astronomy","zh":"观测天文学"},{"phrase":"observational learning","zh":"观察学习"},{"phrase":"observational evidence","zh":"观察证据"},{"phrase":"observational error","zh":"观测误差"},{"phrase":"observational skills","zh":"观察能力"}],"forms":[{"label":"原级（形容词）","form":"observational"},{"label":"比较级（用 more）","form":"more observational"},{"label":"最高级（用 most）","form":"most observational"},{"label":"副词形式","form":"observationally"}],"derivatives":[{"word":"observation","pos":"n.","zh":"观察；观测；观察结果"},{"word":"observe","pos":"v.","zh":"观察；注意到；遵守"},{"word":"observer","pos":"n.","zh":"观察者；观察员"},{"word":"observationally","pos":"adv.","zh":"在观测上；从观察角度"}],"senses":[{"no":"01","title":"Belonging to watching","titleCN":"观察的：与“看”这一活动有关","definition":"relating to the act of watching something carefully","definitionCN":"与仔细观看某物的行为有关","example":"The study's observational phase lasted six months before any interviews began.","exampleCN":"这项研究的观察阶段持续了六个月，之后才开始访谈。","why":"The suffix marks a domain: whatever the activity of watching produces or requires can be called observational.","whyCN":"这个后缀标出领域：凡由“看”这一活动产生或所需的东西，都可以叫 observational。"},{"no":"02","title":"Research that does not intervene","titleCN":"观察性研究：只看，不动手","definition":"describing a study in which researchers watch and record without controlling the conditions","definitionCN":"指研究者只观察记录、不控制条件的研究","example":"The observational study followed thousands of smokers without asking any of them to change.","exampleCN":"这项观察性研究跟踪了数千名吸烟者，却没有要求任何人改变习惯。","why":"The word contrasts with experimental: nothing is assigned or manipulated, so the researchers accept whatever conditions already exist.","whyCN":"这个词与“实验性研究”相对：不分配、不操纵，研究者接受业已存在的条件。"},{"no":"03","title":"Data taken from watching","titleCN":"观测数据：仪器和眼睛记下来的","definition":"describing measurements or records obtained by watching rather than by experiment","definitionCN":"指通过观察而非实验获得的测量值或记录","example":"Observational data from the buoys showed a slow rise in water temperature.","exampleCN":"浮标传来的观测数据显示水温在缓慢上升。","why":"Data is observational when its source is the world as it is, not a world the researcher arranged.","whyCN":"当数据来源是“本来的世界”而不是研究者安排的世界时，它就是观测数据。"},{"no":"04","title":"Astronomy by detection","titleCN":"观测天文学：靠接收光来研究天体","definition":"describing astronomy that studies celestial objects through detected radiation rather than theory alone","definitionCN":"指通过探测辐射而非仅凭理论研究天体的天文学分支","example":"Observational astronomy confirmed the prediction with a new image of the nebula.","exampleCN":"观测天文学用一张新的星云图像证实了这一预测。","why":"Astronomers cannot run experiments on stars; observation replaces manipulation, so the branch is named for its only available method.","whyCN":"天文学家无法对恒星做实验；观察取代了操纵，因此这一分支以它唯一可用的方法命名。"},{"no":"05","title":"Learning by watching others","titleCN":"观察学习：看别人做，自己学会","definition":"describing the acquisition of behaviour by watching others perform it","definitionCN":"指通过观看他人行为而习得行为的过程","example":"Observational learning explains how a child copies a gesture never directly taught.","exampleCN":"观察学习解释了孩子如何学会一个从未被直接教过的手势。","why":"Here the watching is the teaching: no instruction is given, yet the model's behaviour passes to the observer.","whyCN":"这里的“看”就是“教”：没有指令，示范者的行为却传给了观察者。"},{"no":"06","title":"Evidence from what is seen","titleCN":"观察证据：眼睛能作证的部分","definition":"describing evidence that comes from direct or recorded watching","definitionCN":"指来自直接或记录下来的观察的证据","example":"Observational evidence supported the theory long before a test could be designed.","exampleCN":"在设计出检验之前很久，观察证据就已支持这一理论。","why":"Evidence is observational when it can be pointed at: the argument rests on what was seen, not on what was assumed.","whyCN":"当证据可以被指认时，它就是观察证据：论证依靠看见的东西，而不是假定的东西。"},{"no":"07","title":"Error introduced by watching","titleCN":"观测误差：看的人也会看错","definition":"describing error that arises from the limits of the observer or the instrument","definitionCN":"指由观察者或仪器的局限造成的误差","example":"Observational error was reduced by averaging many readings.","exampleCN":"通过平均多次读数，观测误差被降低了。","why":"Since observation is a human or instrumental act, it carries its own kind of error, distinct from the error of the thing observed.","whyCN":"既然观察是人或仪器的行为，它就带有自身的误差，与被观察物本身的误差不同。"},{"no":"08","title":"A trained capacity","titleCN":"观察能力：看得出别人看不出的","definition":"describing the skills or habits involved in noticing details accurately","definitionCN":"指准确注意细节所需的技能或习惯","example":"Good observational skills let the nurse notice a change in breathing.","exampleCN":"良好的观察能力让护士注意到呼吸的变化。","why":"Practice turns watching into a competence: the trained observer sees distinctions that an untrained eye smooths over.","whyCN":"练习把“看”变成一种能力：受过训练的眼睛能看出未经训练的眼睛会抹平的差别。"}],"etymology":{"intro":{"en":"Observational is observation plus -al. Behind observation is Latin observare, ob- 'over' plus servare 'to keep or guard'.","cn":"observational 是 observation 加 -al。observation 背后是拉丁语 observare：ob-“在上”加 servare“守护、保持”。"},"items":[{"era":"LATIN servare","en":"Servare meant to keep or guard. Watching and keeping were one act: one keeps what one watches over.","cn":"servare 意为保持、守护。看与守曾是一个动作：人守着自己所看护的东西。"},{"era":"LATIN observare","en":"With ob-, the verb meant to watch over, to heed, and to comply with a rule or sign.","cn":"加上 ob- 后，动词意为看护、留意，并遵从规则或征兆。"},{"era":"LATIN observatio","en":"The noun named the act of watching and the remark produced by it. Medieval science leaned on this noun for recorded attention.","cn":"该名词指看护行为及其产生的评论。中世纪科学倚重这个名词来表示有记录的注意。"},{"era":"ENGLISH observation","en":"English observation arrived through French in the 14th century and became a key term in navigation, medicine, and natural philosophy.","cn":"英语 observation 于 14 世纪经法语进入，成为航海、医学与自然哲学的关键术语。"},{"era":"ENGLISH -al","en":"The suffix -al turns the noun into an adjective meaning 'of or relating to'. Observational therefore means 'of observation'.","cn":"后缀 -al 把名词变成意为“与……有关的”形容词。因此 observational 就是“与观察有关的”。"},{"era":"MODERN ENGLISH","en":"In the 20th century, epidemiology and psychology standardised observational study and observational learning as named methods.","cn":"20 世纪，流行病学与心理学把 observational study 与 observational learning 固定为有名称的方法。"}]},"similar":{"note":{"en":"The first group is the observation family; the second compares research and evidence labels that differ in how much the researcher intervenes.","cn":"第一组是 observation 词族；第二组比较几个研究方法与证据标签，区别在于研究者干预的程度。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"observation","ipa":"/ˌɒbzəˈveɪʃn/","tag":"noun","definition":"the act, result, or remark of watching. It is the noun that observational modifies.","definitionCN":"观察的行为、结果或评论；是 observational 所修饰的名词。"},{"word":"observable","ipa":"/əbˈzɜːvəbl/","tag":"adjective","definition":"able to be seen or noticed. It describes a quality of the object, not a method.","definitionCN":"可被看见或注意到的；描述对象的性质，而非方法。"},{"word":"observant","ipa":"/əbˈzɜːvənt/","tag":"person adjective","definition":"quick to notice things. It describes a person's habit.","definitionCN":"善于察觉的；描述人的习性。"},{"word":"observational","ipa":"/ˌɒbzəˈveɪʃənl/","tag":"method adjective","definition":"relating to observation as a method or a body of data.","definitionCN":"与作为方法或数据来源的观察有关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"experimental","ipa":"/ɪkˌsperɪˈmentl/","tag":"method adjective","definition":"based on controlled tests in which conditions are changed. It is the direct opposite of observational.","definitionCN":"基于改变条件的受控试验；与 observational 直接相对。"},{"word":"empirical","ipa":"/ɪmˈpɪrɪkl/","tag":"evidence adjective","definition":"based on experience or data rather than theory. It can cover both observation and experiment.","definitionCN":"依据经验或数据而非理论；可同时涵盖观察与实验。"},{"word":"correlational","ipa":"/ˌkɒrəˈleɪʃənl/","tag":"statistical adjective","definition":"describing a study that measures whether two variables move together, without changing either.","definitionCN":"指测量两个变量是否同向变化、而不改变任一变量的研究。"},{"word":"anecdotal","ipa":"/ˌænɪkˈdəʊtl/","tag":"evidence adjective","definition":"based on isolated stories rather than systematic watching. It is the weakest cousin of observational.","definitionCN":"基于零散个例而非系统观察；是 observational 最弱的表亲。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: observation plus -al. No new root enters; the adjective simply means 'of observation'.","cn":"只用真实成分：observation 加 -al。没有新词根进入；这个形容词只表示“属于观察的”。"},"normal":[{"en":"Observation + al: anything that belongs to watching is observational.","cn":"observation 加 al：凡属于“看”的东西都是 observational。"},{"en":"An observational study sits at the back of the room and takes notes.","cn":"观察性研究坐在教室后排做笔记。"},{"en":"Experimental changes the room; observational records the room as it is.","cn":"实验研究改变房间；观察研究记录房间本来的样子。"},{"en":"Observational astronomy cannot touch a star, so it watches light instead.","cn":"观测天文学碰不到恒星，于是改为看光。"},{"en":"Observational error belongs to the watcher; the object may be perfectly steady.","cn":"观测误差属于看的人；被看的东西可能完全稳定。"}],"abstract":[{"en":"Observation without intervention is an ideal that no observer fully reaches; presence itself is a kind of touch.","cn":"不干预的观察是一种理想，没有观察者能完全达到；在场本身就是一种触碰。"},{"en":"An observational study can show that things travel together, never that one pushed the other.","cn":"观察性研究能显示事物同行，却不能显示是谁推了谁。"},{"en":"The adjective hides the instrument: 'observational' sounds neutral, yet every observation has a device behind it.","cn":"这个形容词把仪器藏了起来：observational 听起来中立，可每次观察背后都有一台装置。"}]},"examples":[{"en":"The observational study could not rule out that healthier people simply walked more.","cn":"这项观察性研究无法排除“本来就更健康的人走得更多”这一可能。"},{"en":"Observational astronomy relies on telescopes that record light far beyond the visible range.","cn":"观测天文学依靠能记录可见范围之外光线的望远镜。"},{"en":"Young animals acquire many skills through observational learning rather than direct practice.","cn":"幼年动物通过观察学习而非直接练习获得许多技能。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"observation（观察）+ al（的）——凡跟“观察”有关的，就是观察性的。","word":"observational"},"root":"由 observation（观察，源自拉丁语 observare“看护、留意”）加形容词后缀 -al 构成，意为“与观察有关的”；在研究方法中指不施加干预、仅作记录的一类研究。","sensesIntro":{"en":"Eight senses of observational, all variations on one adjective. It can name the activity of watching, a method that avoids interference, the data such a method yields, the error it introduces, or the skill it requires.","cn":"observational 的八个义项都是同一个形容词的变化。它可以指观看活动、避免干预的方法、该方法产生的数据、它带来的误差，或它所需的技能。"},"semanticMap":{"core":{"en":"CORE IMAGE: a researcher seated at the back of a classroom, silent, ticking each hand raised.","cn":"核心意象：研究者坐在教室后排，一言不发，每次有人举手就打一个勾。"},"chain":["LATIN SERVARE = TO KEEP, GUARD","LATIN OBSERVARE = TO WATCH OVER","LATIN OBSERVATIO = A WATCHING","ENGLISH OBSERVATION = CAREFUL WATCHING","SUFFIX -AL = RELATING TO","OBSERVATIONAL = OF OR BY WATCHING"],"branches":[{"senses":"S1 · S8","en":"THE ACT AND THE SKILL: watching as an activity, and watching as a trained competence.","cn":"行为与能力：作为活动的观看，以及作为训练有素的本领。"},{"senses":"S2 · S3","en":"METHOD AND DATA: a study without intervention, and the records it produces.","cn":"方法与数据：不干预的研究，以及它产生的记录。"},{"senses":"S4","en":"ASTRONOMY'S ONLY METHOD: watching light because stars cannot be handled.","cn":"天文学唯一的方法：恒星无法摆弄，只能看光。"},{"senses":"S5","en":"LEARNING BY IMITATION: behaviour passed on through watching a model.","cn":"通过模仿学习：行为通过观看示范者而传递。"},{"senses":"S6 · S7","en":"EVIDENCE AND ITS COST: what the eye can support, and the error the eye adds.","cn":"证据与代价：眼睛能支持的内容，以及眼睛附加的误差。"}]},"affixes":{"intro":{"en":"Observational is observation plus -al. The family keeps -ation for the act, -er for the person, -ance for compliance, and -atory for the place.","cn":"observational 是 observation 加 -al。词族保留 -ation 表示行为，-er 表示人，-ance 表示遵从，-atory 表示场所。"},"latinIntro":{"en":"The base is servare, to keep, with ob- adding attention. The same Latin verb yields preserve, reserve, conserve, and servant.","cn":"词基是 servare“保持”，ob- 增加“注意”的方向。同一拉丁动词给出 preserve、reserve、conserve、servant。"},"items":[{"word":"observe","structure":"Latin observare (watch over)","meaning":"to watch, notice, or keep a rule","meaningCN":"观察；注意到；遵守","example":"The team observed the site for three seasons.","exampleCN":"团队对该地点观察了三个季节。"},{"word":"observation","structure":"observe + -ation (action noun)","meaning":"the act or result of watching","meaningCN":"观察的行为或结果","example":"The observation was repeated by a second team.","exampleCN":"这一观察由第二个团队重复了一次。"},{"word":"observational","structure":"observation + -al (relating to)","meaning":"relating to watching as a method","meaningCN":"与作为方法的观察有关","example":"The paper is observational rather than experimental.","exampleCN":"这篇论文属于观察性而非实验性研究。"},{"word":"observationally","structure":"observational + -ly (adverb)","meaning":"from the standpoint of observation","meaningCN":"从观测角度；在观测上","example":"The two sites are observationally similar but geologically distinct.","exampleCN":"这两个地点在观测上相似，地质上却不同。"},{"word":"observer","structure":"observe + -er (agent noun)","meaning":"one who watches and records","meaningCN":"观察并记录的人","example":"Each observer used the same checklist.","exampleCN":"每位观察者都使用同一份核查表。"},{"word":"observant","structure":"observe + -ant (adjective)","meaning":"noticing details readily","meaningCN":"容易注意到细节的","example":"An observant guide points out the small tracks.","exampleCN":"细心的向导会指出那些小小的足迹。"},{"word":"observance","structure":"observant + -ce (state noun)","meaning":"compliance with a rule or rite","meaningCN":"对规则或仪式的遵守","example":"The observance of safety rules improved after the audit.","exampleCN":"审计之后，安全规则的遵守情况有所改善。"},{"word":"observatory","structure":"observe + -atory (place noun)","meaning":"a building equipped for watching the sky","meaningCN":"为观测天空而配备的场所；天文台","example":"The observatory records the sky every clear night.","exampleCN":"这座天文台每个晴夜都记录天空。"},{"word":"observable","structure":"observe + -able (able to be)","meaning":"possible to see or detect","meaningCN":"可见或可探测的","example":"The change is observable in the first week.","exampleCN":"这种变化在第一周就能观察到。"}],"latinEntries":[{"word":"servare","structure":"Latin verb","meaning":"to keep, guard","meaningCN":"保持；守护"},{"word":"observare","structure":"ob- + servare","meaning":"to watch over, heed","meaningCN":"看护；留意"},{"word":"observatio","structure":"Latin noun","meaning":"a watching, a compliance","meaningCN":"观察；遵从"}]}},{"word":"observatory","ipa_uk":"/əbˈzɜːvətri/","ipa_us":"/əbˈzɜːrvətɔːri/","definition_zh":"天文台；观测站；气象台；瞭望台","definition_en":"a building or station equipped for watching the sky, the weather, or other natural phenomena","core_image":"山顶一座白色圆顶，夜里缓缓转动，把一条缝对准天上最暗的那颗星。","scene":"旅行者沿着山路走到山顶，看见圆顶在暮色里转动。From the hilltop observatory, the telescope tracked the rising planet.","sceneCN":"这里 observatory 是“装备望远镜、用于观测天体的天文台”（第 1 个义项）；句意：山顶的天文台用望远镜追踪正在升起的行星。","pos":[{"tag":"n.","zh":"天文台；观测站；气象台；瞭望台"}],"collocations":[{"phrase":"an astronomical observatory","zh":"天文台"},{"phrase":"a meteorological observatory","zh":"气象台"},{"phrase":"the observatory dome","zh":"天文台圆顶"},{"phrase":"a space observatory","zh":"空间天文台"},{"phrase":"the royal observatory","zh":"皇家天文台"},{"phrase":"an observatory station","zh":"观测站"}],"forms":[{"label":"复数（名词）","form":"observatories"},{"label":"动词形式","form":"observe"},{"label":"名词形式（观察）","form":"observation"},{"label":"施动者名词","form":"observer"}],"derivatives":[{"word":"observe","pos":"v.","zh":"观察；观测；遵守"},{"word":"observation","pos":"n.","zh":"观察；观测；观察结果"},{"word":"observational","pos":"adj.","zh":"观察的；观测的"},{"word":"observer","pos":"n.","zh":"观察者；观测员"}],"senses":[{"no":"01","title":"A place for watching the sky","titleCN":"天文台：把望远镜安在山顶","definition":"a building with telescopes and instruments for studying stars, planets, and other celestial objects","definitionCN":"配备望远镜与仪器、用于研究恒星、行星等天体的建筑","example":"The observatory on the ridge opens its dome only on clear nights.","exampleCN":"山脊上的天文台只在晴夜打开圆顶。","why":"The suffix -atory names a place; when the watching is of the sky, the place becomes an observatory in the astronomical sense.","whyCN":"后缀 -atory 命名场所；当所看的是天空时，这个场所就成了天文学意义上的 observatory。"},{"no":"02","title":"A station for weather","titleCN":"气象台：按时记录风、雨和温度","definition":"a station where weather conditions are measured and recorded regularly","definitionCN":"定期测量并记录天气状况的观测站","example":"The mountain observatory has kept rainfall records since 1890.","exampleCN":"这座高山气象台自 1890 年起记录降雨。","why":"Weather also requires a fixed place and a regular hour; the same building type serves meteorology under the same name.","whyCN":"天气同样需要固定地点与固定时刻；同一种建筑在气象学中也沿用这个名字。"},{"no":"03","title":"A station for the ground","titleCN":"地震观测站：听地下的动静","definition":"a station equipped to detect and record seismic or geomagnetic activity","definitionCN":"配备仪器探测并记录地震或地磁活动的站点","example":"The seismic observatory detected the tremor before the city felt it.","exampleCN":"地震观测站在城市感到震动之前就探测到了。","why":"The word travels to any phenomenon that must be watched continuously from a fixed point, including movements under the earth.","whyCN":"这个词扩展到任何需要从固定点持续观察的现象，包括地下的运动。"},{"no":"04","title":"A tower for looking out","titleCN":"瞭望台：看远处的动静","definition":"a raised structure used to watch a wide area, especially for approaching danger","definitionCN":"用于监视广阔区域、尤为了望来袭危险的高台","example":"From the old observatory on the hill, the guard could see the whole bay.","exampleCN":"从山上旧瞭望台，卫兵能看见整个海湾。","why":"Height does for the naked eye what a lens does for the telescope: it extends the range of watching.","whyCN":"高度对肉眼的作用，正如透镜对望远镜的作用：它延长了“看”的范围。"},{"no":"05","title":"A historic scientific site","titleCN":"历史天文台：一条本初子午线所在的地方","definition":"a long-established observatory that has become a scientific or national landmark","definitionCN":"历史悠久、已成为科学或国家地标的天文台","example":"Visitors stood on the line at the old observatory where longitude begins.","exampleCN":"游客站在古老天文台的那条线上，经度从那里起算。","why":"Some observatories become reference points themselves; their location fixes a standard that maps and clocks depend on.","whyCN":"有些天文台本身成了参照点：它们的位置确定了地图与时钟所依赖的标准。"},{"no":"06","title":"An instrument in orbit","titleCN":"空间天文台：把望远镜送上天","definition":"a telescope or instrument placed in space to observe without the interference of the atmosphere","definitionCN":"送入太空、以避开大气干扰的望远镜或观测装置","example":"The space observatory has watched the same galaxy for twenty years.","exampleCN":"这台空间天文台已经观测同一个星系二十年。","why":"When the instrument leaves the ground, the place-name travels with it: the observatory is now the payload, not the building.","whyCN":"当仪器离开地面，这个“场所名”也跟着走了：此时 observatory 指载荷，而不是建筑。"},{"no":"07","title":"A shared archive in the cloud","titleCN":"虚拟天文台：数据合在一起看","definition":"a system that links many astronomical data archives so they can be searched as one","definitionCN":"把众多天文数据档案连接起来、可作为一个整体检索的系统","example":"The virtual observatory lets a student compare images from a dozen telescopes.","exampleCN":"虚拟天文台让学生能比较十几台望远镜的图像。","why":"If watching produces archives, then a place that gathers archives can act like an observatory even without a dome.","whyCN":"如果观察会产生档案，那么汇集档案的地方即使没有圆顶，也能像天文台一样运作。"},{"no":"08","title":"The dome itself","titleCN":"圆顶：会转的那只大碗","definition":"the rotating dome that shelters and points a telescope","definitionCN":"遮蔽并指向望远镜的旋转圆顶","example":"The observatory's white dome turned until the slit faced the rising moon.","exampleCN":"天文台的白色圆顶转动，直到那条缝对准升起的月亮。","why":"By metonymy the building's most visible part stands for the whole; the dome moves because the sky does.","whyCN":"借代之下，建筑最显眼的部分代表整体；圆顶之所以转动，是因为天空在转。"}],"etymology":{"intro":{"en":"Observatory comes from Latin observatorium, a place for observing, from observare, to watch over. The Latin suffix -torium marks a place or instrument.","cn":"observatory 来自拉丁语 observatorium“观察之所”，出自 observare“看护、留意”。拉丁后缀 -torium 表示场所或器具。"},"items":[{"era":"LATIN servare","en":"Servare meant to keep or guard. An observatory is a place where keeping watch is the purpose of the building.","cn":"servare 意为保持、守护。天文台就是把“守望着”当作建筑用途的地方。"},{"era":"LATIN observare","en":"Observare combined ob- 'over' with servare: to watch over, to heed signs in the sky, to keep a rule.","cn":"observare 把 ob-“在上”与 servare 结合：看护、留意天上的征兆、遵守规则。"},{"era":"LATIN observatorium","en":"The noun named a place or a device for observation. It could refer to a lookout as well as to an instrument.","cn":"该名词指用于观察的场所或装置，既可指瞭望处，也可指仪器。"},{"era":"FRENCH observatoire","en":"French used observatoire for a building set aside for astronomical work, and English borrowed the word in the 17th century.","cn":"法语用 observatoire 指专为天文工作设立的建筑，英语于 17 世纪借入。"},{"era":"ENGLISH 17c","en":"The first English observatories were private rooms with telescopes; national observatories followed as navigation needed accurate star positions.","cn":"最早的英语 observatory 是装有望远镜的私人房间；随着航海需要精确星位，国家天文台随之出现。"},{"era":"MODERN ENGLISH","en":"The 20th century added space observatories and virtual observatories, moving the 'place' from a dome to a payload or a data network.","cn":"20 世纪增加了空间天文台与虚拟天文台，把“场所”从圆顶移到载荷或数据网络。"}]},"similar":{"note":{"en":"The first group is the observation family; the second compares buildings and places built for watching or measuring.","cn":"第一组是 observation 词族；第二组比较为观察或测量而建的建筑与场所。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"observation","ipa":"/ˌɒbzəˈveɪʃn/","tag":"noun","definition":"the act or result of watching. It names the activity, not the building.","definitionCN":"观察的行为或结果；命名的是活动，不是建筑。"},{"word":"observational","ipa":"/ˌɒbzəˈveɪʃənl/","tag":"adjective","definition":"relating to watching as a method.","definitionCN":"与作为方法的观察有关。"},{"word":"observer","ipa":"/əbˈzɜːvə/","tag":"person noun","definition":"the person who watches, especially one stationed at a site.","definitionCN":"观察的人，尤指驻守某地的人。"},{"word":"observatory","ipa":"/əbˈzɜːvətri/","tag":"place noun","definition":"the place or instrument built for watching. The -atory ending marks location.","definitionCN":"为观察而建的场所或装置；-atory 结尾标出地点。"}]},{"heading":"NEAR MEANING","entries":[{"word":"laboratory","ipa":"/ləˈbɒrətri/","tag":"place noun","definition":"a room for controlled experiments. It shares the -atory ending but changes conditions rather than watching them.","definitionCN":"进行受控实验的房间；共享 -atory 结尾，但改变条件而非观察条件。"},{"word":"planetarium","ipa":"/ˌplænɪˈteəriəm/","tag":"place noun","definition":"a domed theatre that projects the sky for teaching. It shows a model, not the real sky.","definitionCN":"用圆顶投影天空用于教学的场所；展示模型，而非真实天空。"},{"word":"weather station","ipa":"/ˈweðə steɪʃn/","tag":"place noun","definition":"a small site with instruments for local weather records. It is the routine cousin of a meteorological observatory.","definitionCN":"配备仪器记录本地天气的小型站点；是气象台在日常尺度上的表亲。"},{"word":"lookout","ipa":"/ˈlʊkaʊt/","tag":"place or person noun","definition":"a place or person kept watch for danger. It is older and less scientific than observatory.","definitionCN":"为防危险而设的哨位或哨兵；比 observatory 更古老，也更不科学化。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: observare, to watch over, plus -torium, a place. An observatory is literally a watching-place.","cn":"只用真实成分：observare“看护”，加 -torium“场所”。observatory 字面上就是“看的地方”。"},"normal":[{"en":"Observe plus -atory: a place whose whole job is to watch.","cn":"observe 加 -atory：一个全部工作就是“看”的地方。"},{"en":"A white dome turning at night is the building following the sky.","cn":"夜里转动的白色圆顶，是建筑在跟着天空走。"},{"en":"On a hill, height does the work of a lens: the lookout sees the whole bay.","cn":"在山上，高度承担了透镜的工作：瞭望台看得见整个海湾。"},{"en":"Weather, earthquakes, and stars all get their own observatory.","cn":"天气、地震和星星都有各自的天文台或观测站。"},{"en":"When the telescope goes into orbit, the observatory becomes a payload.","cn":"当望远镜进入轨道，observatory 就变成了一个载荷。"}],"abstract":[{"en":"An observatory is a building that admits it exists only to look, and that honesty is rare among buildings.","cn":"天文台是一栋承认自己只为“看”而存在的建筑，这种诚实对建筑而言很罕见。"},{"en":"The dome turns because the sky will not come to it; patience is built into the architecture.","cn":"圆顶要转，是因为天空不会自己过来；耐心被造进了建筑里。"},{"en":"A virtual observatory has no sky above it, only the collected eyes of many instruments.","cn":"虚拟天文台头顶没有天空，只有许多仪器汇集起来的眼睛。"}]},"examples":[{"en":"The observatory's dome was damaged in the storm, so the telescope stayed covered for a week.","cn":"天文台的圆顶在风暴中受损，望远镜因此盖了一周。"},{"en":"A small weather observatory on the pass records wind speed every ten minutes.","cn":"山口的一座小型气象台每十分钟记录一次风速。"},{"en":"Data from the space observatory changed how astronomers date the oldest galaxies.","cn":"空间天文台的数据改变了天文学家测定最古老星系年代的方式。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"observe（观察）+ atory（场所）——专门看星星的地方，就是天文台。","word":"observatory"},"root":"源自拉丁语 observatorium（观察之所），出自 observare“看护、留意”；-torium 为表示场所或器具的后缀，经法语 observatoire 进入英语，本义即“用于观察的地方”。","sensesIntro":{"en":"Eight senses of observatory, all naming a place or instrument devoted to watching. The object changes from stars to weather to the ground to a whole bay, and the place shrinks from a building to a dome, a satellite, or a data network.","cn":"observatory 的八个义项都指专门用于观察的场所或装置。观察对象从恒星到天气、到地下、到整个海湾；而“场所”从建筑缩小到圆顶、卫星，或一张数据网络。"},"semanticMap":{"core":{"en":"CORE IMAGE: a white dome on a ridge turning slowly until its slit aims at the faintest star.","cn":"核心意象：山脊上的白色圆顶缓缓转动，直到那条缝对准最暗的星。"},"chain":["LATIN SERVARE = TO KEEP, GUARD","LATIN OBSERVARE = TO WATCH OVER","LATIN OBSERVATORIUM = A PLACE FOR WATCHING","FRENCH OBSERVATOIRE = ASTRONOMICAL BUILDING","ENGLISH OBSERVATORY = A WATCHING-PLACE","ANY PLACE OR INSTRUMENT DEDICATED TO WATCHING"],"branches":[{"senses":"S1 · S8","en":"THE ASTRONOMICAL PLACE: the building with telescopes, and the dome that points them.","cn":"天文场所：装有望远镜的建筑，以及指向目标的圆顶。"},{"senses":"S2 · S3","en":"WATCHING THE EARTH: weather measured on schedule, and seismic movement detected below.","cn":"观察地球：按时测量天气，以及探测地下的震动。"},{"senses":"S4 · S5","en":"HEIGHT AND HISTORY: a lookout over the bay, and an old site that fixes longitude.","cn":"高度与历史：俯瞰海湾的瞭望台，以及确定经度的古老台址。"},{"senses":"S6","en":"WATCHING FROM ORBIT: an instrument that carries the place-name into space.","cn":"从轨道观察：把“场所之名”带进太空的仪器。"},{"senses":"S7","en":"WATCHING THROUGH ARCHIVES: many telescopes joined into one searchable system.","cn":"透过档案观察：许多望远镜被联结成一个可检索的系统。"}]},"affixes":{"intro":{"en":"Observatory is observe plus -atory, a Latin place suffix. The family keeps -ation for the act, -er for the watcher, and -al for the method adjective.","cn":"observatory 是 observe 加 -atory（拉丁语场所后缀）。词族保留 -ation 表示行为，-er 表示观察者，-al 构成方法形容词。"},"latinIntro":{"en":"The base is servare, to keep, with ob- adding the direction of attention. Latin -torium names the place where an action happens.","cn":"词基是 servare“保持”，ob- 增加注意的方向。拉丁语 -torium 命名动作发生的场所。"},"items":[{"word":"observe","structure":"Latin observare (watch over)","meaning":"to watch, notice, or comply","meaningCN":"观察；注意到；遵守","example":"They observe the sky from dusk until midnight.","exampleCN":"他们从黄昏观察到午夜。"},{"word":"observatory","structure":"observe + -atory (place)","meaning":"a place equipped for watching the sky or nature","meaningCN":"为观测天空或自然而配备的场所","example":"The observatory stands above the clouds.","exampleCN":"这座天文台立在云层之上。"},{"word":"observation","structure":"observe + -ation (action noun)","meaning":"the act or record of watching","meaningCN":"观察的行为或记录","example":"The observation was logged at 03:12.","exampleCN":"这次观测记录于凌晨三点十二分。"},{"word":"observational","structure":"observation + -al (relating to)","meaning":"of or by watching","meaningCN":"观察的；以观察为方法的","example":"Observational work supplies the raw images.","exampleCN":"观测工作提供原始图像。"},{"word":"observer","structure":"observe + -er (agent noun)","meaning":"one who watches, especially on duty","meaningCN":"观察者，尤指值班观测的人","example":"The night observer records every hour.","exampleCN":"夜班观测员每小时记录一次。"},{"word":"observant","structure":"observe + -ant (adjective)","meaning":"alert to details","meaningCN":"对细节警觉的","example":"An observant visitor notices the repaired dome.","exampleCN":"细心的参观者会注意到修过的圆顶。"},{"word":"observance","structure":"observant + -ce (state noun)","meaning":"keeping a rule or rite","meaningCN":"对规则或仪式的遵守","example":"Observance of the night schedule is strict.","exampleCN":"夜间值班制度的遵守很严格。"},{"word":"observable","structure":"observe + -able (able to be)","meaning":"able to be seen","meaningCN":"可被看见的","example":"The comet is observable with small binoculars.","exampleCN":"这颗彗星用小双筒望远镜就能看到。"},{"word":"conservatory","structure":"con- + servare + -atory (place)","meaning":"a place for keeping plants or for music, from the same place suffix","meaningCN":"用同一场所后缀构成的“温室”或“音乐学院”","example":"The glass conservatory keeps the ferns through winter.","exampleCN":"这座玻璃温室让蕨类过冬。"}],"latinEntries":[{"word":"servare","structure":"Latin verb","meaning":"to keep, guard","meaningCN":"保持；守护"},{"word":"observare","structure":"ob- + servare","meaning":"to watch over, heed","meaningCN":"看护；留意"},{"word":"observatorium","structure":"Latin noun","meaning":"a place or instrument for observing","meaningCN":"用于观察的场所或器具"}]}},{"word":"occurrence","ipa_uk":"/əˈkʌrəns/","ipa_us":"/əˈkɜːrəns/","definition_zh":"发生；出现；事件；发生率；（矿物的）产出；出现次数","definition_en":"the fact of something happening or existing, or an event that happens","core_image":"日历上某一天被红笔圈了一下，旁边只写了两个字：发生了。","scene":"保险报告统计过去五年同类事故的情况，发现多数集中在雨季。The report counted the occurrence of similar accidents over five years.","sceneCN":"这里 occurrence 是“同类事件发生的次数、发生情况”（第 3 个义项）；句意：报告统计了过去五年同类事故的发生次数。","pos":[{"tag":"n.","zh":"发生；出现；事件；发生率；（矿物的）产出；出现次数"}],"collocations":[{"phrase":"the occurrence of something","zh":"某事的出现"},{"phrase":"a common occurrence","zh":"常见的事"},{"phrase":"a rare occurrence","zh":"罕见的事件"},{"phrase":"frequency of occurrence","zh":"出现频率"},{"phrase":"an everyday occurrence","zh":"日常会发生的事"},{"phrase":"the occurrence rate","zh":"发生率"},{"phrase":"a natural occurrence","zh":"自然发生的事"}],"forms":[{"label":"复数（名词）","form":"occurrences"},{"label":"动词形式","form":"occur"},{"label":"形容词形式","form":"occurrent"},{"label":"名词（重复发生）","form":"recurrence"}],"derivatives":[{"word":"occur","pos":"v.","zh":"发生；出现；被想到"},{"word":"recur","pos":"v.","zh":"再次发生；复发"},{"word":"occurrent","pos":"adj.","zh":"正在发生的；偶然发生的"},{"word":"occurrence","pos":"n.","zh":"发生；事件；出现次数"}],"senses":[{"no":"01","title":"Something that happens","titleCN":"事件：发生的一件事","definition":"an event or incident that takes place, especially one that is noticed","definitionCN":"发生的事件或事故，尤指被注意到的一次","example":"The police logged every unusual occurrence at the border that night.","exampleCN":"警方记录了那晚边境上每一件不寻常的事。","why":"The word can point at the thing itself: once an event has happened, it can be counted, listed, and reported like an object.","whyCN":"这个词可以指向事情本身：事件一旦发生，就能像物件一样被计数、列举与报告。"},{"no":"02","title":"The fact of happening","titleCN":"发生：出现这件事本身","definition":"the fact or process of something happening or existing","definitionCN":"某事物发生或存在的事实与过程","example":"The occurrence of frost in June surprised the growers.","exampleCN":"六月出现霜冻让种植户感到意外。","why":"Here the word names not the event but its coming into being; the emphasis is on 'that it happened at all'.","whyCN":"这里命名的不是事件，而是它“产生”这一过程；重点在于“它竟然发生了”。"},{"no":"03","title":"How often it happens","titleCN":"出现次数：一段时间里发生了几回","definition":"the number of times something happens within a stated period or group","definitionCN":"某事物在特定时段或群体内发生的次数","example":"The occurrence of the error fell by half after the new check was added.","exampleCN":"加入新检查后，该错误的发生次数减少了一半。","why":"Counting turns an event into a rate; agencies need the count, not the story of any single case.","whyCN":"计数把事件变成比率；机构需要的是次数，而不是任何单个案例的故事。"},{"no":"04","title":"A rate in statistics","titleCN":"发生率：分母里的那批人","definition":"the proportion of a population in which a specified event happens over a period","definitionCN":"在一段时间内，特定事件在某一群体中发生的比例","example":"The occurrence rate of the side effect was two cases per thousand patients.","exampleCN":"该副作用的发生率为每千名患者两例。","why":"Statistics adds a denominator: the same number of cases means different things in a small town and a large city.","whyCN":"统计学加上了分母：同样的病例数，在小镇和大城市意味着不同的事情。"},{"no":"05","title":"Something found in nature","titleCN":"自然出现：不必人为制造","definition":"the presence of a substance, species, or phenomenon in the natural environment","definitionCN":"某物质、物种或现象在自然环境中存在","example":"The natural occurrence of the mineral in local rock made mining cheap.","exampleCN":"这种矿物在当地岩石中天然产出，使开采成本很低。","why":"The word reports existence without agency: no one made it happen, it is simply found where conditions allowed it.","whyCN":"这个词报告的是“存在”而非“作为”：无人使它发生，它只是在条件允许的地方被找到。"},{"no":"06","title":"A mineral showing in rock","titleCN":"矿点：地质图上标出的那一处","definition":"a deposit or showing of a mineral in a particular place, as recorded in geology","definitionCN":"地质记录中某地矿物的矿床或露头","example":"The survey marked three occurrences of copper in the valley.","exampleCN":"勘测在山谷里标出了三处铜矿点。","why":"Geology gives the word a spatial sense: an occurrence is where the mineral 'turns up', a point on a map rather than a moment in time.","whyCN":"地质学给这个词一个空间义：occurrence 是矿物“露面”的地点，是地图上的一点，而不是时间中的一刻。"},{"no":"07","title":"A word appearing in text","titleCN":"出现：某个词在文本里露了几次","definition":"an instance of a linguistic item appearing in a text or corpus","definitionCN":"某一语言项在文本或语料库中出现的一次实例","example":"The corpus records each occurrence of the phrase with its source line.","exampleCN":"语料库记录该短语的每一次出现及其所在行。","why":"Linguistics counts tokens: every time the same form appears, it is a separate occurrence, even though the word is one.","whyCN":"语言学数的是“个例”：同一形式每出现一次就是一个独立的 occurrence，尽管那个词只有一个。"},{"no":"08","title":"A case of disease","titleCN":"病例出现：医院登记的那一例","definition":"a single diagnosed case of a disease in a population under surveillance","definitionCN":"监测群体中被诊断出的一例疾病","example":"The health office reported the first occurrence of the new strain in March.","exampleCN":"卫生部门报告了这种新毒株在三月首次出现。","why":"Public health treats each case as a countable unit; the word then means 'one more instance has entered the record'.","whyCN":"公共卫生把每一例当作可计数的单位；这个词于是表示“记录里又多了一例”。"}],"etymology":{"intro":{"en":"Occurrence comes from Latin occurrentia, from occurrere, to run to meet: ob- 'toward, against' plus currere 'to run'. The same verb gives occur and current.","cn":"occurrence 来自拉丁语 occurrentia，出自 occurrere“跑过去相遇”：ob-“朝向、对着”加 currere“跑”。同一动词给出 occur 与 current。"},"items":[{"era":"LATIN currere","en":"Currere meant to run. It underlies current, course, cursor, and excursion, all involving movement along a path.","cn":"currere 意为跑。它构成 current、course、cursor、excursion，这些都涉及沿路径的运动。"},{"era":"LATIN occurrere","en":"Ob- plus currere meant to run up against something, hence to meet it, to present itself, or to come to mind.","cn":"ob- 加 currere 意为跑上去撞见某物，因而表示相遇、浮现，或想起。"},{"era":"LATIN occurrentia","en":"The noun named the act of meeting or turning up, and later a thing that turns up.","cn":"该名词指相遇或出现的行为，后来指出现的事物。"},{"era":"FRENCH occurrence","en":"French occurrence kept the sense of an event that presents itself, especially something unexpected.","cn":"法语 occurrence 保留“自行出现的事件”之义，尤指意外之事。"},{"era":"ENGLISH 16c","en":"English occurrence first meant a happening or an incident, then extended to frequency and to the presence of substances in nature.","cn":"英语 occurrence 最初指发生的事情或事件，随后扩展到频次，以及物质在自然中的存在。"},{"era":"MODERN ENGLISH","en":"Statistics, geology, linguistics, and medicine each gave the word a technical count: rate, deposit, token, case.","cn":"统计学、地质学、语言学与医学各自给这个词一个技术性计数：比率、矿点、个例、病例。"}]},"similar":{"note":{"en":"The first group is the occur family; the second compares words for things that happen, from the neutral event to the unexpected incident.","cn":"第一组是 occur 词族；第二组比较表示“发生之事”的词，从中性的事件到意外的变故。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"occur","ipa":"/əˈkɜː/","tag":"verb","definition":"to happen or exist; also to come into the mind. It names the event's coming about.","definitionCN":"发生、存在；也指被想到；命名的是事件的发生。"},{"word":"recur","ipa":"/rɪˈkɜː/","tag":"verb","definition":"to happen again, especially at intervals. The prefix re- adds repetition.","definitionCN":"再次发生，尤指有间隔地复发；前缀 re- 增加重复义。"},{"word":"occurrent","ipa":"/əˈkʌrənt/","tag":"adjective","definition":"happening at a particular time; also used in philosophy for what is present.","definitionCN":"在某一时刻发生的；哲学中也指当下呈现的。"},{"word":"occurrence","ipa":"/əˈkʌrəns/","tag":"noun","definition":"an event, or the fact of happening. It turns the verb into a countable thing.","definitionCN":"事件，或发生的事实；把动词变成可计数的东西。"}]},{"heading":"NEAR MEANING","entries":[{"word":"event","ipa":"/ɪˈvent/","tag":"general noun","definition":"anything that happens, especially something planned or notable. It is the broadest word.","definitionCN":"发生的任何事，尤指计划中的或值得注意的；是最宽泛的词。"},{"word":"incident","ipa":"/ˈɪnsɪdənt/","tag":"event noun","definition":"an event, often minor or unpleasant, that interrupts normal activity.","definitionCN":"打断正常活动的意外事件，常较轻微或不愉快。"},{"word":"instance","ipa":"/ˈɪnstəns/","tag":"count noun","definition":"a single example or case of something general. It stresses the sample, not the happening.","definitionCN":"一般事物的单个例子或案例；侧重样本，而非发生。"},{"word":"frequency","ipa":"/ˈfriːkwənsi/","tag":"rate noun","definition":"the number of times something happens in a period. It measures the count, not the event.","definitionCN":"某事物在一段时间内发生的次数；测量计数，而非事件。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: ob- 'against' plus currere 'to run', then -ence. Something that runs up against you has occurred.","cn":"只用真实成分：ob-“对着”加 currere“跑”，再加 -ence。跑上来撞见你的东西，就是“发生了”。"},"normal":[{"en":"Occurrence is a run-in: something came along the path and met the moment.","cn":"occurrence 是一次撞见：某物沿路跑来，撞上了那个时刻。"},{"en":"A red circle on the calendar marks one occurrence; the tally beside it counts them all.","cn":"日历上的红圈标出一次 occurrence；旁边的计数把它们全数出来。"},{"en":"Geology puts occurrence on a map; statistics puts it in a rate.","cn":"地质学把 occurrence 放到地图上；统计学把它放进比率里。"},{"en":"Every occurrence of a word in a corpus is one more token, even if the word is one.","cn":"语料库里每出现一次该词就是一个新的个例，尽管那个词只有一个。"},{"en":"A rare occurrence is news; a common occurrence is weather.","cn":"罕见的事是新闻；常见的事是天气。"}],"abstract":[{"en":"Occurrence is the most neutral word for change: it reports that something met the world, without saying why.","cn":"occurrence 是关于变化最中性的词：它报告某物遇上了世界，却不解释原因。"},{"en":"Counting occurrences turns a story into a rate, and a rate is easier to compare than a story.","cn":"统计发生次数把故事变成比率，而比率比故事更容易比较。"},{"en":"What counts as an occurrence depends on where the observer draws the boundary of the event.","cn":"什么算作一次 occurrence，取决于观察者把事件的边界画在哪里。"}]},"examples":[{"en":"Flooding used to be a rare occurrence here, but the records now show it every other spring.","cn":"这里过去很少发生洪水，但记录显示如今几乎隔年春天就有一次。"},{"en":"The mineral's occurrence in the cliff was noted long before anyone tried to mine it.","cn":"早在有人尝试开采之前，这种矿物在崖壁上的产出就已被记录。"},{"en":"Each occurrence of the symbol in the manuscript was catalogued by hand.","cn":"手稿中该符号的每一次出现都被手工编入目录。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"occur（发生）+ rence（名词）——发生的事、出现的次数，就是 occurrence。","word":"occurrence"},"root":"源自拉丁语 occurrentia，出自 occurrere“跑上去相遇”：ob-“对着”加 currere“跑”；本义为“迎面出现”，引申为“发生、事件、出现次数”。","sensesIntro":{"en":"Eight senses of occurrence. One idea holds them together: something turns up. It may turn up as a single event, as the fact of happening, as a count, as a rate, as a mineral in rock, as a word in a text, or as a case in a clinic.","cn":"occurrence 的八个义项由同一个观念维系：某物露面了。它可以是单个事件、发生这一事实、一个计数、一个比率、岩石中的矿物、文本中的词，或诊所里的一例病例。"},"semanticMap":{"core":{"en":"CORE IMAGE: one day circled in red on a calendar, with two words beside it: it happened.","cn":"核心意象：日历上某一天被红笔圈住，旁边写着两个字：发生了。"},"chain":["LATIN CURRERE = TO RUN","LATIN OB- = TOWARD, AGAINST","LATIN OCCURRERE = TO RUN UPON, MEET","LATIN OCCURRENTIA = A TURNING UP","FRENCH OCCURRENCE = AN EVENT THAT PRESENTS ITSELF","ENGLISH OCCURRENCE = ANYTHING THAT TURNS UP"],"branches":[{"senses":"S1 · S2","en":"THE THING AND THE FACT: an event that happened, and the bare fact that it happened.","cn":"事情与事实：发生的事件，以及“它发生了”这一赤裸事实。"},{"senses":"S3 · S4","en":"COUNT AND RATE: how many times it turned up, and what proportion of a population it touched.","cn":"次数与比率：它出现了多少回，以及它触及了群体中多大的比例。"},{"senses":"S5","en":"TURNING UP IN NATURE: a substance or species present without being made.","cn":"在自然中露面：未被制造却已存在的物质或物种。"},{"senses":"S6 · S7","en":"TURNING UP IN SPACE AND TEXT: a mineral point on a map, a token in a corpus.","cn":"在空间与文本中露面：地图上的矿点，语料库中的一个词例。"},{"senses":"S8","en":"TURNING UP IN THE CLINIC: one more diagnosed case entering the record.","cn":"在诊所里露面：又一例确诊病例进入记录。"}]},"affixes":{"intro":{"en":"Occurrence is occur plus -ence, the noun suffix for a state or an act. The family uses re- for happening again and -ent for the adjective.","cn":"occurrence 是 occur 加 -ence（表示状态或行为的名词后缀）。词族用 re- 表示再次发生，-ent 构成形容词。"},"latinIntro":{"en":"The base is currere, to run, with ob- adding the meeting. Latin occurrere also meant to come to mind, which survives in the phrase 'it occurred to me'.","cn":"词基是 currere“跑”，ob- 增加“相遇”之义。拉丁语 occurrere 也指“想起”，这一含义留在英语 it occurred to me 中。"},"items":[{"word":"occur","structure":"Latin occurrere (run to meet) + English -ur","meaning":"to happen, or to come to mind","meaningCN":"发生；被想到","example":"The accident occurred at the junction.","exampleCN":"事故发生在交叉路口。"},{"word":"occurrence","structure":"occur + -ence (state noun)","meaning":"an event or the fact of happening","meaningCN":"事件，或发生的事实","example":"Power cuts are a daily occurrence in the old quarter.","exampleCN":"老城区每天都会停电。"},{"word":"recur","structure":"re- (again) + occur","meaning":"to happen again","meaningCN":"再次发生；复发","example":"The fever recurred after the treatment stopped.","exampleCN":"停药后发烧再次出现。"},{"word":"recurrence","structure":"recur + -ence (state noun)","meaning":"a return of something after an interval","meaningCN":"某事物间隔一段时间后再次出现","example":"The recurrence rate was lower in the second group.","exampleCN":"第二组的复发率更低。"},{"word":"occurrent","structure":"occur + -ent (adjective)","meaning":"happening at a given time","meaningCN":"在某一时刻发生的","example":"The occurrent event was recorded but not explained.","exampleCN":"发生的事件被记录下来，却未得到解释。"},{"word":"concurrent","structure":"con- (together) + currere (run) + -ent","meaning":"happening at the same time","meaningCN":"同时发生的","example":"Two concurrent storms hit the coast.","exampleCN":"两场风暴同时袭击了海岸。"},{"word":"current","structure":"Latin currere (run) + -ent","meaning":"a flow of water, air, or electricity; also present in time","meaningCN":"水流、气流或电流；也指当下的","example":"The current carries the boat downstream.","exampleCN":"水流把船带向下游。"},{"word":"cursor","structure":"Latin cursor (runner)","meaning":"the moving marker on a screen","meaningCN":"屏幕上移动的光标","example":"The cursor stopped at the start of the line.","exampleCN":"光标停在行首。"},{"word":"excursion","structure":"ex- (out) + currere (run) + -ion","meaning":"a short trip out and back","meaningCN":"短途往返的出行；远足","example":"The class made a day excursion to the quarry.","exampleCN":"班级去采石场做了一日远足。"}],"latinEntries":[{"word":"currere","structure":"Latin verb","meaning":"to run, to move quickly","meaningCN":"跑；快速移动"},{"word":"occurrere","structure":"ob- + currere","meaning":"to run to meet, to present itself","meaningCN":"跑上去相遇；自行出现"},{"word":"occurrentia","structure":"Latin noun","meaning":"a turning up, an event","meaningCN":"出现；事件"}]}},{"word":"operational","ipa_uk":"/ˌɒpəˈreɪʃənl/","ipa_us":"/ˌɑːpəˈreɪʃənl/","definition_zh":"运行的；运营的；可投入使用的；操作层面的；（军事）作战的","definition_en":"relating to the way something works in practice, or to the activities and costs of running an organization or machine","core_image":"一条生产线正在运转，指示灯全绿，工人各就各位，没有一处停着等修。","scene":"项目经理说系统已经通过测试，下周可以交给值班团队试用。The system will be operational next week.","sceneCN":"这里 operational 是“已具备运行条件、可投入使用”（第 2 个义项）；句意：系统下周就可以投入运行。","pos":[{"tag":"adj.","zh":"运行的；运营的；可投入使用的；操作层面的；（军事）作战的"}],"collocations":[{"phrase":"operational costs","zh":"运营成本"},{"phrase":"operational risk","zh":"运营风险"},{"phrase":"an operational definition","zh":"操作定义"},{"phrase":"operational research","zh":"运筹学"},{"phrase":"fully operational","zh":"全面投入运行的"},{"phrase":"operational efficiency","zh":"运营效率"},{"phrase":"operational command","zh":"作战指挥"}],"forms":[{"label":"原级（形容词）","form":"operational"},{"label":"比较级（用 more）","form":"more operational"},{"label":"最高级（用 most）","form":"most operational"},{"label":"副词形式","form":"operationally"}],"derivatives":[{"word":"operate","pos":"v.","zh":"操作；运行；经营；动手术"},{"word":"operation","pos":"n.","zh":"运行；操作；手术；行动"},{"word":"operator","pos":"n.","zh":"操作员；运营商"},{"word":"operationally","pos":"adv.","zh":"在运行上；从操作角度"}],"senses":[{"no":"01","title":"Relating to how it runs","titleCN":"运行上的：与机器怎么转有关","definition":"relating to the working of a machine, system, or process","definitionCN":"与机器、系统或流程如何运转有关","example":"The engineers separated design problems from operational problems.","exampleCN":"工程师把设计问题与运行问题分开处理。","why":"The suffix -al points to a domain: what happens while the thing is running, as distinct from how it was designed.","whyCN":"后缀 -al 指向一个领域：事物运转时发生的事，与它如何被设计区分开来。"},{"no":"02","title":"Ready to be used","titleCN":"可投入使用：不是图纸，是能跑的","definition":"in a state of being able to work or be used as intended","definitionCN":"处于能够按预期工作或使用的状态","example":"The new control tower is operational after two years of testing.","exampleCN":"新控制塔经过两年测试后已可投入使用。","why":"Here the word answers a readiness question: the thing is not merely complete on paper, it can actually perform its function.","whyCN":"这里这个词回答的是“就绪”问题：事物不只在纸面上完成，它真能履行职责。"},{"no":"03","title":"The cost of keeping it running","titleCN":"运营成本：让它每天转起来的钱","definition":"describing the expenses of running an organization or facility rather than building it","definitionCN":"指维持组织或设施日常运转的开支，而非建设开支","example":"Operational costs rose with fuel and staff wages.","exampleCN":"运营成本随燃料与员工工资上涨。","why":"Budgets split capital from operation: one pays to build, the other pays to keep the thing alive each day.","whyCN":"预算把资本支出与运营支出分开：一笔付建设，另一笔付让它每天活下去。"},{"no":"04","title":"Defined by what you do","titleCN":"操作定义：用做法代替概念","definition":"describing a definition that specifies the procedures or measurements used to identify something","definitionCN":"指用识别某事物所需的具体程序或测量来下定义","example":"The study operationalised 'stress' as a rise in heart rate during the task.","exampleCN":"该研究把“压力”操作化为任务期间心率上升。","why":"Some ideas cannot be seen directly, so science defines them by the operations that produce them, making the concept testable.","whyCN":"有些概念无法直接看见，科学便用产生它的操作来定义，使概念可被检验。"},{"no":"05","title":"The mathematics of decisions","titleCN":"运筹：把调度问题算清楚","definition":"describing the use of mathematical methods to improve the planning and running of complex activities","definitionCN":"指用数学方法改进复杂活动的计划与运行","example":"Operational research cut the average waiting time at the depot.","exampleCN":"运筹研究缩短了车站的平均等待时间。","why":"When an organization runs, its choices can be modelled; operational research treats scheduling as a problem with a best answer.","whyCN":"组织一旦运转，其选择就可以建模型；运筹研究把调度当作一个有最优解的问题。"},{"no":"06","title":"At the level of action","titleCN":"作战层面：战略之下、战术之上","definition":"describing the level of military activity concerned with planning and conducting campaigns","definitionCN":"指军事活动中负责筹划与实施战役的层级","example":"Operational command decided where the units would meet before the battle.","exampleCN":"作战指挥决定各部队在战斗前于何处会合。","why":"Military theory separates strategy (why to fight), operations (where and when to move), and tactics (how to fight the next hour).","whyCN":"军事理论把战略（为何打）、作战（何时何地调动）与战术（接下来一小时怎么打）分开。"},{"no":"07","title":"Risk from daily running","titleCN":"运营风险：不是市场，而是流程出错","definition":"describing the risk of loss from failed processes, people, systems, or external events","definitionCN":"指因流程、人员、系统失效或外部事件造成损失的风险","example":"The bank holds capital against operational risk as well as credit risk.","exampleCN":"银行不仅为信用风险，也为运营风险持有资本。","why":"Finance distinguishes risk from markets and borrowers from risk that arises simply because an organization must run every day.","whyCN":"金融业把市场与借款人的风险，同“组织每天必须运转”本身带来的风险区分开。"},{"no":"08","title":"A circuit that computes","titleCN":"运算放大器：让电路做算术","definition":"describing an amplifier designed to perform mathematical operations on signals","definitionCN":"指为对信号执行数学运算而设计的放大器","example":"The operational amplifier summed the two sensor voltages.","exampleCN":"运算放大器把两个传感器的电压相加。","why":"Early analogue computers used amplifiers to add and integrate; the name stayed even after the circuits became general-purpose components.","whyCN":"早期模拟计算机用放大器做加法与积分；即使这些电路后来成了通用元件，名字仍保留下来。"}],"etymology":{"intro":{"en":"Operational is operation plus -al. Operation comes from Latin operatio, a working, from operari, to work, and opus, work.","cn":"operational 是 operation 加 -al。operation 来自拉丁语 operatio“劳作”，出自 operari“工作”与 opus“工作、作品”。"},"items":[{"era":"LATIN opus","en":"Opus meant work, a task, or a product of work. It survives in magnum opus and in the musical term opera.","cn":"opus 意为工作、任务或劳动成果。它留在 magnum opus 与音乐术语 opera 中。"},{"era":"LATIN operari","en":"The verb meant to work, to labour, and to perform a task. It could describe both physical labour and the working of a power.","cn":"该动词意为工作、劳作、执行任务，既可描述体力劳动，也可描述某种力量的作用。"},{"era":"LATIN operatio","en":"The noun named a working or an effect produced. Medieval Latin also used it for mathematical and medical procedures.","cn":"该名词指劳作或产生的效果。中世纪拉丁语也用它指数学与医学操作。"},{"era":"FRENCH operation","en":"French operation covered work, a surgical procedure, and a military action. English borrowed all three.","cn":"法语 operation 涵盖工作、外科手术与军事行动；英语把这三层都借了进来。"},{"era":"ENGLISH 17c-19c","en":"Operational first meant 'of an operation' in surgery and mathematics, then extended to machines and organizations in the industrial age.","cn":"operational 最初指外科与数学意义上的“操作的”， industrial 时代扩展到机器与组织。"},{"era":"MODERN ENGLISH","en":"The 20th century added operational research, operational definition, operational risk, and the operational amplifier.","cn":"20 世纪增加了运筹研究、操作定义、运营风险与运算放大器等用法。"}]},"similar":{"note":{"en":"The first group is the operate family; the second compares adjectives that describe readiness, function, and practical work.","cn":"第一组是 operate 词族；第二组比较表示就绪、功能与实际运作的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"operate","ipa":"/ˈɒpəreɪt/","tag":"verb","definition":"to work or control a machine, to run a business, or to perform surgery.","definitionCN":"操作或控制机器、经营业务，或施行手术。"},{"word":"operation","ipa":"/ˌɒpəˈreɪʃn/","tag":"noun","definition":"the act of working, a surgical procedure, or a military action.","definitionCN":"工作行为、外科手术，或军事行动。"},{"word":"operator","ipa":"/ˈɒpəreɪtə/","tag":"person noun","definition":"a person who runs a machine, or a company that runs a service.","definitionCN":"操作机器的人，或经营某项服务的公司。"},{"word":"operational","ipa":"/ˌɒpəˈreɪʃənl/","tag":"adjective","definition":"relating to running or being ready to run.","definitionCN":"与运行有关，或指已可运行的。"}]},{"heading":"NEAR MEANING","entries":[{"word":"functional","ipa":"/ˈfʌŋkʃənl/","tag":"readiness adjective","definition":"working as designed. It stresses purpose served, while operational can also stress the running process or its cost.","definitionCN":"按设计正常工作；强调所服务的目的，而 operational 也可强调运行过程或成本。"},{"word":"practical","ipa":"/ˈpræktɪkl/","tag":"usefulness adjective","definition":"useful in real situations rather than theoretical. It judges usefulness, not running status.","definitionCN":"在真实情境中有用而非理论的；判断的是用处，不是运行状态。"},{"word":"active","ipa":"/ˈæktɪv/","tag":"state adjective","definition":"in action or in effect. A system can be active without being fully operational.","definitionCN":"正在行动或生效的；系统可以处于活动状态却尚未完全可运行。"},{"word":"strategic","ipa":"/strəˈtiːdʒɪk/","tag":"level adjective","definition":"relating to long-term aims. In military theory it is the level above operational.","definitionCN":"与长期目标有关；在军事理论中位于“作战”之上。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: opus, work, plus operari, to work, then -ation and -al. Operational means 'of the working'.","cn":"只用真实成分：opus“工作”，加 operari“工作”，再加 -ation 与 -al。operational 就是“属于运转的”。"},"normal":[{"en":"Opus is work; operational is the adjective of work being done right now.","cn":"opus 是工作；operational 是“工作正在进行”的形容词。"},{"en":"Design is the drawing; operational is the machine actually turning.","cn":"设计是图纸；operational 是机器真的在转。"},{"en":"Operational costs are the money paid every day, not the money paid to build.","cn":"运营成本是每天都要付的钱，不是建造时付的钱。"},{"en":"An operational definition says what you do, not what you mean.","cn":"操作定义说的是你怎么做，而不是你指什么。"},{"en":"All green lights mean the system is operational.","cn":"指示灯全绿，就表示系统处于可运行状态。"}],"abstract":[{"en":"'Operational' is where plans meet friction: everything works on paper, and only some things work at three in the morning.","cn":"operational 是计划撞上摩擦的地方：纸面上一切都能行，凌晨三点只有一部分真能行。"},{"en":"An operational definition trades depth for testability, and the trade is usually worth making.","cn":"操作定义用深度换可检验性，这笔交易通常值得。"},{"en":"The word hides the labour inside the system; what looks automatic is a schedule of people and maintenance.","cn":"这个词把系统里的劳动藏了起来；看似自动的东西，其实是一张排班表与维护表。"}]},"examples":[{"en":"The plant became fully operational only after the cooling system passed its safety test.","cn":"冷却系统通过安全测试后，这座工厂才全面投入运行。"},{"en":"Operational costs, not construction costs, decide whether the railway survives.","cn":"决定这条铁路能否存续的是运营成本，而不是建设成本。"},{"en":"The team agreed on an operational definition of 'success' before collecting any data.","cn":"团队在收集数据之前先就“成功”的操作定义达成一致。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"operate（运行）+ ional（的）——能跑起来、正在运转的，都是 operational。","word":"operational"},"root":"由 operation（运行、操作，源自拉丁语 operatio“劳作”）加 -al 构成；词基为拉丁语 opus“工作”与 operari“工作”，故本义为“与运转、操作有关的”。","sensesIntro":{"en":"Eight senses of operational, all concerned with work being done. The work may be a machine turning, a system ready to run, the cost of daily upkeep, a procedure that defines a concept, a mathematical plan, a military campaign, a process failure, or an analogue computation.","cn":"operational 的八个义项都与“正在做的工作”有关。这工作可以是机器转动、系统就绪、日常维护成本、定义概念的程序、数学调度、军事战役、流程失效，或模拟电路运算。"},"semanticMap":{"core":{"en":"CORE IMAGE: a production line running with every indicator green and nobody waiting for a repair.","cn":"核心意象：生产线正在运转，指示灯全绿，没有人等着维修。"},"chain":["LATIN OPUS = WORK","LATIN OPERARI = TO WORK","LATIN OPERATIO = A WORKING","FRENCH OPERATION = WORK, SURGERY, ACTION","ENGLISH OPERATION = THE ACT OF RUNNING","OPERATIONAL = OF RUNNING OR READY TO RUN"],"branches":[{"senses":"S1 · S2","en":"RUNNING AND READY: the process of working, and the state of being fit to work.","cn":"运转与就绪：工作的过程，以及能够工作的状态。"},{"senses":"S3 · S7","en":"THE PRICE OF RUNNING: daily costs and the risks that arise from ordinary processes.","cn":"运转的代价：日常成本，以及普通流程带来的风险。"},{"senses":"S4","en":"DEFINITION BY PROCEDURE: a concept replaced by the operations that measure it.","cn":"以程序定义：用测量它的操作取代概念本身。"},{"senses":"S5 · S6","en":"PLANNING ACTION: mathematical scheduling and the military level between strategy and tactics.","cn":"筹划行动：数学调度，以及位于战略与战术之间的军事层级。"},{"senses":"S8","en":"COMPUTING BY CIRCUIT: an amplifier named for the operations it performs.","cn":"用电路运算：因执行运算而得名的放大器。"}]},"affixes":{"intro":{"en":"Operational is operation plus -al. The family runs through operate, operator, and operation, with opus as the Latin base.","cn":"operational 是 operation 加 -al。词族包括 operate、operator、operation，拉丁词基为 opus。"},"latinIntro":{"en":"The base is opus, work, and its verb operari. Latin operatio names the working or the effect produced.","cn":"词基是 opus“工作”及其动词 operari。拉丁语 operatio 指劳作或产生的效果。"},"items":[{"word":"operate","structure":"Latin operari (to work) + English -ate","meaning":"to work, control, or carry out an activity","meaningCN":"工作；操作；开展活动","example":"Only trained staff may operate the crane.","exampleCN":"只有受过训练的员工可以操作这台起重机。"},{"word":"operation","structure":"Latin operatio (a working) + English -ion","meaning":"the act of working, or a planned action","meaningCN":"工作行为，或计划好的行动","example":"The operation runs from six in the morning.","exampleCN":"这项作业从早晨六点开始运行。"},{"word":"operational","structure":"operation + -al (relating to)","meaning":"relating to running, or ready to run","meaningCN":"与运行有关的，或已可运行的","example":"The system is operational but not yet open to the public.","exampleCN":"系统已可运行，但尚未向公众开放。"},{"word":"operationally","structure":"operational + -ly (adverb)","meaning":"from the point of view of running","meaningCN":"从运行角度看","example":"Operationally, the two designs are almost the same.","exampleCN":"从运行角度看，两种设计几乎一样。"},{"word":"operator","structure":"operate + -or (agent noun)","meaning":"a person or firm that runs something","meaningCN":"操作者，或经营某项业务的公司","example":"The operator stopped the line for a safety check.","exampleCN":"操作员为安全检查停下了生产线。"},{"word":"cooperate","structure":"co- (together) + operari (work)","meaning":"to work together toward a shared aim","meaningCN":"为共同目标一起工作；合作","example":"The two labs cooperated on the trial.","exampleCN":"两个实验室在该试验上合作。"},{"word":"operative","structure":"Latin operativus (active) + -ive","meaning":"in effect or ready to act; also a surgical adjective","meaningCN":"生效的、可行动的；也用于外科语境","example":"The new rule is operative from January.","exampleCN":"新规定自一月起生效。"},{"word":"opus","structure":"Latin noun","meaning":"a work, especially a large artistic or musical work","meaningCN":"作品，尤指大型艺术或音乐作品","example":"The symphony became his best-known opus.","exampleCN":"这部交响曲成了他最著名的作品。"},{"word":"operable","structure":"operate + -able (able to be)","meaning":"able to be operated or used","meaningCN":"可操作、可使用的","example":"The hatch is operable from inside.","exampleCN":"这个舱门可从内部操作。"}],"latinEntries":[{"word":"opus","structure":"Latin noun","meaning":"work, task, product of work","meaningCN":"工作；任务；劳动成果"},{"word":"operari","structure":"Latin deponent verb","meaning":"to work, labour, perform","meaningCN":"工作；劳作；执行"},{"word":"operatio","structure":"Latin noun","meaning":"a working, an effect produced","meaningCN":"劳作；产生的效果"}]}},{"word":"operationally","ipa_uk":"/ˌɒpəˈreɪʃənəli/","ipa_us":"/ˌɑːpəˈreɪʃənəli/","definition_zh":"在运行上；从操作角度看；在实际运作中；以操作方式地","definition_en":"in terms of how something actually works or is run, rather than how it is designed or described in theory","core_image":"两个人站在同一台机器前，一个看说明书，一个盯着运转中的指示灯。","scene":"评审会上，工程师说这个方案理论上更省电，但维护太频繁。Operationally, the design saves power but needs frequent maintenance.","sceneCN":"这里 operationally 是“从实际运行、运营的角度看”（第 2 个义项）；句意：从运行角度看，这个设计省电，但维护太频繁。","pos":[{"tag":"adv.","zh":"在运行上；从操作角度看；在实际运作中；以操作方式地"}],"collocations":[{"phrase":"operationally feasible","zh":"在运行上可行的"},{"phrase":"operationally defined","zh":"以操作方式定义的"},{"phrase":"operationally ready","zh":"已具备运行条件的"},{"phrase":"operationally independent","zh":"在运行上独立的"},{"phrase":"operationally difficult","zh":"在实际操作中困难的"},{"phrase":"operationally deployed","zh":"已实际部署的"}],"forms":[{"label":"原级（副词）","form":"operationally"},{"label":"比较级（用 more）","form":"more operationally"},{"label":"最高级（用 most）","form":"most operationally"},{"label":"形容词形式","form":"operational"}],"derivatives":[{"word":"operational","pos":"adj.","zh":"运行的；可投入使用的；操作层面的"},{"word":"operation","pos":"n.","zh":"运行；操作；行动"},{"word":"operate","pos":"v.","zh":"操作；运行；经营"},{"word":"operator","pos":"n.","zh":"操作员；运营商"}],"senses":[{"no":"01","title":"At the level of running","titleCN":"在运行层面：不问设计，只问转不转","definition":"with regard to the working of a system rather than its design or theory","definitionCN":"就系统的运转而非其设计或理论而言","example":"Operationally, the two models differ only in how often they need calibration.","exampleCN":"在运行层面，两个模型只在需要多久校准一次上不同。","why":"The adverb moves the viewpoint: the question is no longer 'what is it?' but 'how does it behave while working?'","whyCN":"这个副词移动了视点：问题不再是“它是什么”，而是“它工作时表现如何”。"},{"no":"02","title":"From the point of view of running it","titleCN":"从运营角度：算的是人手、维护和钱","definition":"from the standpoint of the people and costs needed to keep something running","definitionCN":"从维持其运转所需人力与费用这一立场看","example":"Operationally, adding a second shift costs less than buying another machine.","exampleCN":"从运营角度看，增加一个班次比再买一台机器更省钱。","why":"Operations staff see what designers do not: rosters, spare parts, training hours, and the cost of a shutdown.","whyCN":"运营人员看见设计师看不见的东西：排班、备件、培训工时，以及停机的代价。"},{"no":"03","title":"By stated procedure","titleCN":"以操作方式：把概念落成一套做法","definition":"by means of a definition or measurement that specifies concrete procedures","definitionCN":"借助规定具体程序的定义或测量方式","example":"The team operationally defined 'engagement' as time spent on the page.","exampleCN":"团队把“参与度”操作化定义为停留在页面上的时间。","why":"An abstract concept becomes researchable when it is operationally defined: the procedure decides what will count as an instance.","whyCN":"抽象概念在被操作化定义后才可研究：程序决定了什么算作一个实例。"},{"no":"04","title":"In practice, in effect","titleCN":"实际运作上：结果上等于什么","definition":"in terms of the practical effect produced, even if the formal description differs","definitionCN":"就产生的实际效果而言，即使正式描述有所不同","example":"The two rules are different on paper but operationally identical.","exampleCN":"这两条规则在纸面上不同，实际运作上却一样。","why":"This sense compares outcomes rather than texts: what matters is what the system does, not what the document says it does.","whyCN":"这一义项比较结果而非文本：要紧的是系统实际做什么，而不是文件说它做什么。"},{"no":"05","title":"Ready for service","titleCN":"具备运行条件地：能上岗了","definition":"in a state of being ready to perform its intended function","definitionCN":"处于能够履行预期功能的状态","example":"The satellite is operationally ready but waits for a launch window.","exampleCN":"这颗卫星已具备运行条件，只等发射窗口。","why":"Readiness is assessed operationally: checks are run, crews are trained, and the answer is whether it can start today.","whyCN":"就绪是按运行标准评估的：检查做完、人员练好，答案就是“今天能不能开动”。"},{"no":"06","title":"At the campaign level","titleCN":"在作战层面：调得动、供得上","definition":"with regard to the planning and conduct of a military campaign rather than a single fight","definitionCN":"就战役的筹划与实施而言，而非单场交战","example":"Operationally, the force was stretched too thin to hold both crossings.","exampleCN":"在作战层面，这支部队铺得太开，守不住两处渡口。","why":"Military usage separates the campaign from the battle: operationally asks whether units can move, supply, and arrive in time.","whyCN":"军事用法把战役与战斗分开：作战层面问的是部队能否按时调动、补给与抵达。"},{"no":"07","title":"By signal operation","titleCN":"在运算上：电路做了什么运算","definition":"with regard to the mathematical operation performed by a circuit or device","definitionCN":"就电路或装置所执行的数学运算而言","example":"The two inputs are operationally combined by the amplifier.","exampleCN":"放大器在运算上把两路输入合并起来。","why":"In electronics the adverb names what the circuit does to a signal: add, subtract, integrate, or compare.","whyCN":"在电子学中，这个副词命名电路对信号做的事：相加、相减、积分或比较。"},{"no":"08","title":"In execution, not in plan","titleCN":"在执行中：计划之外的那部分现实","definition":"as actually carried out, as opposed to as planned or proposed","definitionCN":"指实际执行的方式，与计划或提议相对","example":"The reform was operationally difficult even though its goals were widely supported.","exampleCN":"这项改革在执行上很困难，尽管其目标广受支持。","why":"Plans are clean because they leave out sequence and resistance; operationally describes the messy version that actually happens.","whyCN":"计划之所以干净，是因为省掉了顺序与阻力；operationally 描述的是实际发生的那团乱麻。"}],"etymology":{"intro":{"en":"Operationally is operational plus -ly. Operational is operation plus -al, and operation goes back to Latin opus, work, and operari, to work.","cn":"operationally 是 operational 加 -ly。operational 是 operation 加 -al，而 operation 上溯拉丁语 opus“工作”与 operari“工作”。"},"items":[{"era":"LATIN opus","en":"Opus named work or a product of work. The word already implied effort rather than mere existence.","cn":"opus 指工作或劳动成果。这个词从一开始就暗含“费力”，而不只是“存在”。"},{"era":"LATIN operari","en":"Operari meant to work or to perform. Its participle operans described something in the middle of doing.","cn":"operari 意为工作、执行。其分词 operans 描述“正在做”的事物。"},{"era":"LATIN operatio","en":"The noun named the working and its effect, including medical and mathematical procedures in later Latin.","cn":"该名词指劳作及其效果；晚期拉丁语中也包括医学与数学程序。"},{"era":"ENGLISH operational","en":"Operational entered English in the 19th century for surgical and mechanical matters, then widened to organizations.","cn":"operational 于 19 世纪进入英语，用于外科与机械事务，随后扩展到组织管理。"},{"era":"ENGLISH -ly","en":"The adverb suffix -ly, from Old English -lice, turns operational into a viewpoint marker: 'viewed as running'.","cn":"副词后缀 -ly（源自古英语 -lice）把 operational 变成视点标记：“从运行的角度看”。"},{"era":"MODERN ENGLISH","en":"Operationally became common in engineering, military planning, and research methods, where it separates practice from design.","cn":"operationally 在工程、军事计划与研究方法中普及，用来把实践与设计分开。"}]},"similar":{"note":{"en":"The first group is the operational family; the second compares adverbs that shift the viewpoint to practice or procedure.","cn":"第一组是 operational 词族；第二组比较几个把视点转向实践或程序的副词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"operational","ipa":"/ˌɒpəˈreɪʃənl/","tag":"adjective","definition":"relating to running, or ready to run.","definitionCN":"与运行有关，或指已可运行的。"},{"word":"operation","ipa":"/ˌɒpəˈreɪʃn/","tag":"noun","definition":"the act of running or a planned action.","definitionCN":"运行行为，或计划好的行动。"},{"word":"operative","ipa":"/ˈɒpərətɪv/","tag":"adjective","definition":"in effect or ready to act. It often describes a rule or a clause.","definitionCN":"生效的或可行动的；常描述规则或条款。"},{"word":"operationally","ipa":"/ˌɒpəˈreɪʃənəli/","tag":"adverb","definition":"viewed from the standpoint of running or procedure.","definitionCN":"从运行或程序的立场看。"}]},{"heading":"NEAR MEANING","entries":[{"word":"practically","ipa":"/ˈpræktɪkli/","tag":"viewpoint adverb","definition":"in practice, or almost. It judges feasibility, while operationally judges running conditions.","definitionCN":"实际上，或“几乎”；判断可行性，而 operationally 判断运行条件。"},{"word":"functionally","ipa":"/ˈfʌŋkʃənəli/","tag":"viewpoint adverb","definition":"in terms of the function served. It asks whether the purpose is met, not how the system is maintained.","definitionCN":"就所履行的功能而言；问目的是否达到，而非系统如何维护。"},{"word":"technically","ipa":"/tekˈnɪkli/","tag":"viewpoint adverb","definition":"according to a strict technical rule. It can contrast with how things work in practice.","definitionCN":"依严格技术规则而言；常与实际运作形成对照。"},{"word":"effectively","ipa":"/ɪˈfektɪvli/","tag":"outcome adverb","definition":"in terms of the result achieved. It focuses on effect, not on process.","definitionCN":"就达到的结果而言；关注效果，而非过程。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: operation plus -al plus -ly. The adverb frames a statement as 'from the running side'.","cn":"只用真实成分：operation 加 -al 再加 -ly。这个副词把一句话框定为“从运转那一侧看”。"},"normal":[{"en":"Operationally means the machine is already turning while you are still reading the manual.","cn":"operationally 意味着你还在读说明书，机器已经开始转了。"},{"en":"On paper it is cheaper; operationally it needs two extra staff.","cn":"纸面上更便宜；从运营角度看却要多两名员工。"},{"en":"Operationally defined means the procedure decides what counts.","cn":"以操作方式定义，意味着由程序决定什么算数。"},{"en":"Operationally ready means today, not someday.","cn":"具备运行条件指的是今天就能用，而不是某天能用。"},{"en":"In a circuit, operationally describes what the signal is made to do.","cn":"在电路里，operationally 描述信号被要求做什么。"}],"abstract":[{"en":"Every plan has a second life that begins when the first shift starts, and that life is the operational one.","cn":"每份计划都有第二次生命，它从第一个班次开始时展开，那就是“运行的那一生”。"},{"en":"Operationally is an honest adverb: it admits that how things work may not match how they were described.","cn":"operationally 是个诚实的副词：它承认事情的运作方式未必与描述相符。"},{"en":"Shifting to the operational view makes costs visible that the design view kept off the page.","cn":"切换到运行视角，会让设计视角留在纸外的那部分成本显形。"}]},"examples":[{"en":"Operationally, the merger changed little: the same staff ran the same routes.","cn":"从运营角度看，这次合并变化不大：同一批员工跑同样的线路。"},{"en":"The concept is operationally defined as the number of correct answers in ten minutes.","cn":"该概念被操作化定义为十分钟内的正确答题数。"},{"en":"The brigade was operationally stretched across three valleys at once.","cn":"该旅在作战层面被同时摊在三个山谷上。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"operational（运行的）+ ly（地）——换个角度，从“跑起来会怎样”看，就是在运行上。","word":"operationally"},"root":"由 operational（运行的，源自拉丁语 opus“工作”与 operari“工作”）加副词后缀 -ly 构成，本义为“从运行、操作的角度看”，用于把讨论从设计或理论转到实际运转。","sensesIntro":{"en":"Eight senses of operationally. All of them shift the frame from description to running: from design to behaviour, from budget to upkeep, from concept to procedure, from paper to practice, from plan to execution.","cn":"operationally 的八个义项都在移动框架：从描述移到运转，从设计移到行为，从预算移到维护，从概念移到程序，从纸面移到实践，从计划移到执行。"},"semanticMap":{"core":{"en":"CORE IMAGE: two people before one machine, one reading the manual and one watching the running lights.","cn":"核心意象：两人站在同一台机器前，一个读说明书，一个盯着运转的指示灯。"},"chain":["LATIN OPUS = WORK","LATIN OPERARI = TO WORK","LATIN OPERATIO = A WORKING","ENGLISH OPERATIONAL = OF RUNNING","SUFFIX -LY = IN THAT RESPECT","OPERATIONALLY = VIEWED FROM THE RUNNING SIDE"],"branches":[{"senses":"S1 · S2","en":"RUNNING AND ITS COSTS: how the system behaves, and what it takes in staff and money to keep it behaving.","cn":"运转及其代价：系统表现如何，以及维持这种表现需要多少人和钱。"},{"senses":"S3","en":"CONCEPT AS PROCEDURE: an abstract term replaced by the steps that measure it.","cn":"概念即程序：抽象术语被测量它的步骤取代。"},{"senses":"S4 · S8","en":"PRACTICE AGAINST PAPER: identical in effect though different in text, and difficult in execution though supported in plan.","cn":"实践对纸面：文本不同而效果相同；计划受支持而执行困难。"},{"senses":"S5 · S6","en":"READINESS AND CAMPAIGN: fit for service today, and able to move and supply across a theatre.","cn":"就绪与战役：今天即可上岗，以及能在战区调动与补给。"},{"senses":"S7","en":"SIGNAL ARITHMETIC: what a circuit is made to do with an input.","cn":"信号算术：电路被要求对输入做什么。"}]},"affixes":{"intro":{"en":"Operationally is operational plus -ly. Operational is operation plus -al, and operation is built on Latin opus and operari.","cn":"operationally 是 operational 加 -ly。operational 是 operation 加 -al，而 operation 建立在拉丁语 opus 与 operari 之上。"},"latinIntro":{"en":"The base is opus, work, with the verb operari and the noun operatio. The English suffix -ly comes from Old English -lice, not from Latin.","cn":"词基是 opus“工作”，另有动词 operari 与名词 operatio。英语后缀 -ly 源自古英语 -lice，并非来自拉丁语。"},"items":[{"word":"operate","structure":"Latin operari (work) + -ate","meaning":"to work or control something","meaningCN":"工作；操作；控制","example":"The pump operates at low pressure.","exampleCN":"这台泵在低压下运行。"},{"word":"operation","structure":"Latin operatio + -ion","meaning":"the act of working or a planned action","meaningCN":"工作行为，或计划好的行动","example":"The whole operation takes four hours.","exampleCN":"整个作业需要四小时。"},{"word":"operational","structure":"operation + -al (relating to)","meaning":"relating to running","meaningCN":"与运行有关的","example":"Operational noise comes from the fan, not the motor.","exampleCN":"运行噪声来自风扇，而不是电机。"},{"word":"operationally","structure":"operational + -ly (adverb)","meaning":"from the standpoint of running","meaningCN":"从运行角度","example":"Operationally, the old route is still the cheapest.","exampleCN":"从运营角度看，旧路线仍然最便宜。"},{"word":"operator","structure":"operate + -or (agent noun)","meaning":"one who operates a machine or service","meaningCN":"操作机器或经营服务的人","example":"The operator logged the pressure every hour.","exampleCN":"操作员每小时记录一次压力。"},{"word":"operative","structure":"Latin operativus + -ive","meaning":"in force or ready to act","meaningCN":"生效的；可行动的","example":"The clause is operative from the date of signing.","exampleCN":"该条款自签署之日起生效。"},{"word":"cooperate","structure":"co- (together) + operari (work)","meaning":"to work together","meaningCN":"合作；共同工作","example":"The two teams cooperated on the survey.","exampleCN":"两个团队在勘测中合作。"},{"word":"operable","structure":"operate + -able (able to be)","meaning":"able to be operated","meaningCN":"可操作的","example":"The valve is operable by hand.","exampleCN":"这个阀门可手动操作。"},{"word":"postoperative","structure":"post- (after) + operative","meaning":"relating to the period after surgery","meaningCN":"手术之后的","example":"Postoperative care lasted three days.","exampleCN":"术后护理持续了三天。"}],"latinEntries":[{"word":"opus","structure":"Latin noun","meaning":"work, task","meaningCN":"工作；任务"},{"word":"operari","structure":"Latin deponent verb","meaning":"to work, perform","meaningCN":"工作；执行"},{"word":"operatio","structure":"Latin noun","meaning":"a working, an effect","meaningCN":"劳作；效果"}]}},{"word":"optimization","ipa_uk":"/ˌɒptɪmaɪˈzeɪʃn/","ipa_us":"/ˌɑːptɪməˈzeɪʃn/","definition_zh":"优化；最优化；最佳化；调优","definition_en":"the process of making something as good or as effective as possible, often within stated limits","core_image":"一条曲线上有一个最低点，一支笔沿着线移动，最后停在那一点上。","scene":"工程团队反复调整参数，让同一台发动机在油耗与动力之间找到折中。Years of optimization brought fuel use and power into balance.","sceneCN":"这里 optimization 是“在约束下把效果调到最好”（第 2 个义项）；句意：多年的优化让油耗与动力达到平衡。","pos":[{"tag":"n.","zh":"优化；最优化；最佳化；调优"}],"collocations":[{"phrase":"an optimization problem","zh":"最优化问题"},{"phrase":"an optimization algorithm","zh":"优化算法"},{"phrase":"cost optimization","zh":"成本优化"},{"phrase":"performance optimization","zh":"性能优化"},{"phrase":"search engine optimization","zh":"搜索引擎优化"},{"phrase":"resource optimization","zh":"资源优化"},{"phrase":"compiler optimization","zh":"编译器优化"}],"forms":[{"label":"复数（名词）","form":"optimizations"},{"label":"动词形式","form":"optimize"},{"label":"形容词形式","form":"optimal"},{"label":"副词形式","form":"optimally"}],"derivatives":[{"word":"optimize","pos":"v.","zh":"优化；使最优"},{"word":"optimal","pos":"adj.","zh":"最优的；最佳的"},{"word":"optimum","pos":"n./adj.","zh":"最适条件；最佳的"},{"word":"optimist","pos":"n.","zh":"乐观主义者"}],"senses":[{"no":"01","title":"Making it as good as it can be","titleCN":"优化：往最好的方向调","definition":"the process of improving something toward its best possible state","definitionCN":"使某事物朝其最佳可能状态改进的过程","example":"The optimization of the design took months of small changes.","exampleCN":"这项设计的优化花了数月时间做小改动。","why":"The word is comparative in secret: it assumes a scale of better and worse, then moves an object along that scale.","whyCN":"这个词暗含比较：它预设了一条“更好—更差”的尺度，然后把对象沿这条尺度推动。"},{"no":"02","title":"Best under constraints","titleCN":"最优化：在限制里找最好的那点","definition":"the mathematical process of finding the best solution to a problem within given limits","definitionCN":"在给定限制内为问题寻找最佳解的数学过程","example":"The optimization problem asked for the shortest route under a fixed budget.","exampleCN":"这个最优化问题要求在固定预算下找出最短路线。","why":"Mathematics adds constraints: without limits almost anything could be improved, and with them a best point may exist.","whyCN":"数学加上了约束：没有限制，几乎任何东西都能再改进；有了限制，才可能存在一个最优点。"},{"no":"03","title":"A procedure that searches","titleCN":"优化算法：一步步试出更好的解","definition":"an algorithm or method that searches for a better solution by repeated adjustment","definitionCN":"通过反复调整搜索更优解的算法或方法","example":"The optimization converged after forty iterations.","exampleCN":"该优化过程在四十次迭代后收敛。","why":"When the best point cannot be calculated directly, the work becomes a search: adjust, measure, keep what improves, repeat.","whyCN":"当最优点无法直接算出时，工作就变成搜索：调整、测量、保留改进、重复。"},{"no":"04","title":"Spending less for the same result","titleCN":"成本优化：同样的效果，更少的钱","definition":"the reduction of costs while maintaining an acceptable level of output or quality","definitionCN":"在维持可接受产出或质量水平的同时降低成本","example":"Cost optimization cut the packaging budget without changing the product.","exampleCN":"成本优化削减了包装预算，产品本身没有变化。","why":"In business the scale is money: the same output is held fixed while the input is pushed down, which is optimization in one direction.","whyCN":"在商业中，尺度是钱：产出保持不变，投入被压低，这是单向的优化。"},{"no":"05","title":"Being found by search engines","titleCN":"搜索引擎优化：让页面更容易被找到","definition":"the practice of improving a web page so that search engines rank it more highly","definitionCN":"改进网页以使其在搜索引擎中获得更高排名的做法","example":"Search engine optimization raised the shop's traffic without any advertising.","exampleCN":"搜索引擎优化在没有投放广告的情况下提高了店铺流量。","why":"Here the 'best state' is defined by an external ranking system, so optimization means fitting the page to someone else's scoring rule.","whyCN":"这里的“最佳状态”由外部排名系统定义，因此优化意味着让页面迎合别人的评分规则。"},{"no":"06","title":"Getting more from what you have","titleCN":"资源优化：同一批人、同一批料，做出更多","definition":"the arrangement of people, materials, or time so that available resources produce the most value","definitionCN":"安排人力、物料或时间，使现有资源产出最大价值","example":"Resource optimization moved two nurses to the night shift and cut waiting times.","exampleCN":"资源优化把两名护士调去夜班，缩短了等待时间。","why":"When resources are fixed, improvement can only come from arrangement: the same pieces are ordered differently.","whyCN":"当资源固定时，改进只能来自安排：同样的零件被重新排序。"},{"no":"07","title":"Making software run faster","titleCN":"性能优化：让程序少等、少算","definition":"the process of making software use less time, memory, or power for the same task","definitionCN":"使软件完成同一任务时消耗更少时间、内存或电力的过程","example":"Performance optimization reduced the page load from four seconds to one.","exampleCN":"性能优化把页面加载时间从四秒降到一秒。","why":"Computing gives optimization a measurable target: the same output must be produced with fewer machine cycles.","whyCN":"计算领域给优化一个可测量的目标：同样的输出必须用更少的机器周期完成。"},{"no":"08","title":"Rewriting code before it runs","titleCN":"编译器优化：运行前先替代码省力","definition":"the rewriting of code by a compiler to make the resulting program faster or smaller","definitionCN":"由编译器改写代码，使生成的程序更快或更小","example":"Compiler optimization removed a loop that always ran zero times.","exampleCN":"编译器优化删掉了一个永远执行零次的循环。","why":"The compiler optimizes on the programmer's behalf, using facts proved at compile time to drop work the program would otherwise do.","whyCN":"编译器替程序员做优化，利用编译期已证明的事实删去程序本会执行的工作。"}],"etymology":{"intro":{"en":"Optimization comes from optimize, formed from Latin optimum, 'the best', plus -ize and -ation. Optimum is the neuter of optimus, the superlative of bonus, good.","cn":"optimization 来自 optimize，由拉丁语 optimum“最好的”加 -ize 与 -ation 构成。optimum 是 optimus 的中性形式，而 optimus 是 bonus“好”的最高级。"},"items":[{"era":"LATIN bonus","en":"Bonus meant good. Its comparative melior and superlative optimus supplied the whole scale of better and best.","cn":"bonus 意为好。其比较级 melior 与最高级 optimus 提供了“更好—最好”的整条尺度。"},{"era":"LATIN optimus / optimum","en":"Optimus meant best. The neuter optimum named the best thing or the best condition, and entered English as a noun and adjective.","cn":"optimus 意为最好的。其中性形式 optimum 指最好的事物或最佳条件，作为名词与形容词进入英语。"},{"era":"ENGLISH optimum","en":"English optimum first appeared in scientific writing for the best condition, such as the temperature at which an enzyme works best.","cn":"英语 optimum 最初出现在科学写作中，指最佳条件，例如酶活性最高的温度。"},{"era":"ENGLISH optimize","en":"Optimize was formed in the 19th century on optimum plus -ize, meaning to make the best of a situation.","cn":"optimize 于 19 世纪由 optimum 加 -ize 构成，意为“充分利用条件、使达到最好”。"},{"era":"LATIN -atio","en":"The suffix -ation, from -atio, turns the verb into the name of the process. Optimization is therefore the process of making optimal.","cn":"后缀 -ation（源自 -atio）把动词变成过程之名。因此 optimization 就是“使之最优”的过程。"},{"era":"MODERN ENGLISH","en":"Mathematics and computing gave the word its technical sense: a search for a best point under constraints, and the rewriting of code for speed.","cn":"数学与计算赋予该词技术含义：在约束下搜索最优点，以及为提速而改写代码。"}]},"similar":{"note":{"en":"The first group is the optimum family; the second compares words for improvement, each with a different standard of 'better'.","cn":"第一组是 optimum 词族；第二组比较表示“改进”的词，各自对“更好”的标准不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"optimize","ipa":"/ˈɒptɪmaɪz/","tag":"verb","definition":"to make something as effective as possible. It names the action.","definitionCN":"使某物尽可能有效；命名的是动作。"},{"word":"optimal","ipa":"/ˈɒptɪməl/","tag":"adjective","definition":"best or most favourable among the options available.","definitionCN":"在可选方案中最好的或最有利的。"},{"word":"optimum","ipa":"/ˈɒptɪməm/","tag":"noun or adjective","definition":"the best possible condition or level.","definitionCN":"最佳的可能条件或水平。"},{"word":"optimization","ipa":"/ˌɒptɪmaɪˈzeɪʃn/","tag":"noun","definition":"the process of reaching the best available state.","definitionCN":"达到最佳可能状态的过程。"}]},{"heading":"NEAR MEANING","entries":[{"word":"improvement","ipa":"/ɪmˈpruːvmənt/","tag":"general noun","definition":"a change that makes something better. It does not imply that a best point has been reached.","definitionCN":"使某物变好的改变；不暗示已到达最优点。"},{"word":"refinement","ipa":"/rɪˈfaɪnmənt/","tag":"quality noun","definition":"a small change that makes something more precise or elegant. It is improvement by polishing.","definitionCN":"使事物更精确或更精致的小改动；靠打磨实现的改进。"},{"word":"efficiency","ipa":"/ɪˈfɪʃnsi/","tag":"ratio noun","definition":"output divided by input. Optimization often raises it, but the two are not the same.","definitionCN":"产出与投入之比；优化常提高效率，但二者并不相同。"},{"word":"maximization","ipa":"/ˌmæksɪmaɪˈzeɪʃn/","tag":"objective noun","definition":"making something as large as possible. Optimization can target a maximum or a minimum.","definitionCN":"使某物尽可能大；优化既可以求最大，也可以求最小。"}]}]},"mnemonics":{"normalIntro":{"en":"Real parts only: optimum, the best, plus -ize and -ation. Optimization is the process of moving something toward the best available point.","cn":"只用真实成分：optimum“最好的”，加 -ize 与 -ation。optimization 就是把事物推向最佳可用点的过程。"},"normal":[{"en":"Optimum is the best point on the curve; optimization is the walk toward it.","cn":"optimum 是曲线上的最优点；optimization 是走向它的那段路。"},{"en":"No constraints, no optimum: the limits are what make a best point exist.","cn":"没有约束就没有最优：正是限制让“最优点”得以存在。"},{"en":"Cost optimization keeps the output and squeezes the input.","cn":"成本优化固定产出，挤压投入。"},{"en":"Search engine optimization is fitting a page to someone else's scoring rule.","cn":"搜索引擎优化就是让页面迎合别人的评分规则。"},{"en":"Compiler optimization does the tidying before the program ever runs.","cn":"编译器优化在程序运行之前就替它收拾干净。"}],"abstract":[{"en":"Every optimization chooses a measure, and the measure quietly decides what counts as good.","cn":"每次优化都要选一个度量，而度量悄悄决定了什么算“好”。"},{"en":"What is optimal for one part of a system is often costly for another; the whole is rarely optimized at once.","cn":"对系统某部分最优的事，往往对另一部分代价高昂；整体很少能一次同时达到最优。"},{"en":"The word sounds final, but an optimum is only the best among the options someone thought to consider.","cn":"这个词听起来像终点，但最优点只是“在某人想到要考虑的选项里”最好的那个。"}]},"examples":[{"en":"The optimization of the timetable saved eight buses without lengthening any trip.","cn":"时刻表的优化省下了八辆车，却没有延长任何一趟行程。"},{"en":"The algorithm's optimization step is where most of the computing time goes.","cn":"算法中耗去大部分计算时间的正是优化那一步。"},{"en":"She studied cost optimization in hospitals and found that supplies, not staff, drove the waste.","cn":"她研究医院成本优化，发现造成浪费的是耗材，而不是人力。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"optim（最好）+ ization（化）——朝“最好”去的过程，就是优化、最优化。","word":"optimization"},"root":"源自拉丁语 optimum（最好的，为 optimus 的中性形式，optimus 又是 bonus“好”的最高级），加 -ize 与 -ation 构成，本义为“使之达到最佳状态的过程”。","sensesIntro":{"en":"Eight senses of optimization, all built on one shape: a curve with a best point and a search toward it. The curve may be mathematical, financial, operational, computational, or a search engine's ranking rule.","cn":"optimization 的八个义项都建立在同一个形状上：一条带有最优点的曲线，以及朝它进行的搜索。这条曲线可以是数学的、财务的、运营的、计算的，或搜索引擎的排名规则。"},"semanticMap":{"core":{"en":"CORE IMAGE: a curve with a lowest point, and a pen moving along it until it stops there.","cn":"核心意象：一条带最低点的曲线，一支笔沿线移动，最后停在那一点。"},"chain":["LATIN BONUS = GOOD","LATIN OPTIMUS = BEST","LATIN OPTIMUM = THE BEST CONDITION","ENGLISH OPTIMIZE = TO MAKE THE BEST OF","SUFFIX -ATION = THE PROCESS","OPTIMIZATION = THE SEARCH FOR THE BEST AVAILABLE POINT"],"branches":[{"senses":"S1 · S2","en":"THE GENERAL MOVE AND THE MATHEMATICAL ONE: improving toward a best state, and finding a best point under constraints.","cn":"一般推进与数学求解：朝最佳状态改进，以及在约束下找最优点。"},{"senses":"S3","en":"SEARCH BY ITERATION: adjust, measure, keep what improves, repeat.","cn":"迭代搜索：调整、测量、保留改进、重复。"},{"senses":"S4 · S6","en":"SAME OUTPUT, LESS INPUT: cost squeezed with quality held, and fixed resources rearranged.","cn":"同产出、少投入：质量不变而压缩成本，以及重排固定资源。"},{"senses":"S5","en":"FITTING AN EXTERNAL RULE: a page tuned to a ranking system it does not control.","cn":"迎合外部规则：页面被调向一个它无法控制的排名系统。"},{"senses":"S7 · S8","en":"MACHINE SPEED: fewer cycles at run time, and code rewritten before run time.","cn":"机器速度：运行时减少周期，以及运行前改写代码。"}]},"affixes":{"intro":{"en":"Optimization is optimize plus -ation. Optimize is optimum plus -ize, and optimum is the Latin superlative 'best'. The family also gives optimal, optimally, and optimist.","cn":"optimization 是 optimize 加 -ation。optimize 是 optimum 加 -ize，而 optimum 是拉丁语最高级“最好的”。词族还有 optimal、optimally、optimist。"},"latinIntro":{"en":"The base is optimus, best, the superlative of bonus, good. Optimum is its neuter form, used as a noun for the best condition.","cn":"词基是 optimus“最好的”，为 bonus“好”的最高级。optimum 是其中性形式，作名词指最佳条件。"},"items":[{"word":"optimum","structure":"Latin optimum (the best) < optimus","meaning":"the most favourable condition or level","meaningCN":"最有利的条件或水平","example":"The crop grows best near the optimum temperature.","exampleCN":"这种作物在最佳温度附近长得最好。"},{"word":"optimal","structure":"optimum + -al (adjective)","meaning":"best among available options","meaningCN":"在可选方案中最好的","example":"The optimal route avoids the morning traffic.","exampleCN":"最优路线避开了早高峰。"},{"word":"optimize","structure":"optimum + -ize (make)","meaning":"to make as effective as possible","meaningCN":"使尽可能有效；优化","example":"They optimized the layout to cut walking distance.","exampleCN":"他们优化布局以缩短走动距离。"},{"word":"optimization","structure":"optimize + -ation (process noun)","meaning":"the process of reaching the best available state","meaningCN":"达到最佳可用状态的过程","example":"The optimization reduced fuel use by a fifth.","exampleCN":"这项优化把燃料消耗降低了五分之一。"},{"word":"optimally","structure":"optimal + -ly (adverb)","meaning":"in the best possible way","meaningCN":"以最佳方式","example":"The engine runs optimally at this speed.","exampleCN":"发动机在这个转速下运转最佳。"},{"word":"optimism","structure":"Latin optimum + -ism (doctrine)","meaning":"the view that things are or will be good; hopefulness","meaningCN":"认为事物是或将是好的观点；乐观","example":"Her optimism carried the team through the delay.","exampleCN":"她的乐观让团队熬过了延误。"},{"word":"pessimism","structure":"Latin pessimus (worst) + -ism","meaning":"the opposite of optimism, built on the Latin superlative for worst","meaningCN":"乐观的反面，由拉丁语“最坏”的最高级构成","example":"The two words are structured alike: best and worst plus -ism.","exampleCN":"这两个词结构相同：最好与最坏各加 -ism。"},{"word":"optimality","structure":"optimal + -ity (quality noun)","meaning":"the condition of being the best available","meaningCN":"处于最佳可用状态的性质","example":"The proof establishes the optimality of the schedule.","exampleCN":"该证明确立了这份排程的最优性。"},{"word":"suboptimal","structure":"sub- (below) + optimal","meaning":"below the best possible standard","meaningCN":"低于最佳标准的；次优的","example":"The plant runs at suboptimal pressure in summer.","exampleCN":"这家工厂夏季在次优压力下运行。"}],"latinEntries":[{"word":"optimus","structure":"Latin adjective, superlative of bonus","meaning":"best","meaningCN":"最好的"},{"word":"optimum","structure":"Latin noun and adjective","meaning":"the best condition; best","meaningCN":"最佳条件；最好的"},{"word":"optare","structure":"Latin verb","meaning":"to choose, wish for","meaningCN":"选择；期望"}]}}]);
